[{"id":494,"law_id":132,"seq":0,"text":"ให้คงเก็บภาษีมูลค่าเพิ่มในอัตราร้อยละ 6.3 สำหรับการขายสินค้า การให้บริการ หรือการนำเข้าทุกกรณี ซึ่งความรับผิดในการเสียภาษีมูลค่าเพิ่มเกิดขึ้นตั้งแต่วันที่ 1 ตุลาคม 2560 ถึงวันที่ 30 กันยายน 2568","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":501,"law_id":139,"seq":0,"text":"ให้คงเก็บภาษีมูลค่าเพิ่มในอัตราร้อยละ 6.3 สำหรับการขายสินค้า การให้บริการ หรือการนำเข้าทุกกรณี ตั้งแต่วันที่ 1 ตุลาคม 2560 ถึงวันที่ 30 กันยายน 2569\n\n*อธิบายเพิ่มเติม\tการเก็บภาษีมูลค่าเพิ่ม จะมีภาษีท้องถิ่นอีก 0.7% จึงรวมแล้วเป็น 7%","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":495,"law_id":133,"seq":0,"text":"ให้ดำเนินการจัดเก็บเงินสะสมและเงินสมทบกองทุนสงเคราะห์ลูกจ้างตั้งแต่วันที่ 1 ตุลาคม 2568 เป็นต้นไป","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":502,"law_id":140,"seq":0,"text":"กำหนดให้หน่วยงานที่มีภารกิจหรือเป็นผู้ให้บริการโทรคมนาคมระหว่างประเทศผ่านโครงข่ายภาคพื้นดินและภาคพื้นน้ำ เป็นหน่วยงานโครงสร้างพื้นฐานสำคัญทางสารสนเทศ ซึ่งต้องอยู่ภายใต้การกำกับดูแลของสำนักงานคณะกรรมการกิจการกระจายเสียง กิจการโทรทัศน์และกิจการโทรคมนาคมแห่งชาติ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":525,"law_id":1235,"seq":0,"text":"ข้อ ๓ ให้นายจ้างจัดให้มีข้อบังคับและคู่มือว่าด้วยความปลอดภัยในการทำงานไว้ในสถานประกอบกิจการ","status":"met","responsible":"Safety","frequency":"Annual","documents":"คู่มือความปลอดภัย อาชีวอนามัย และสภาพแวดบ้อมในการทำงานของบริษัท","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":526,"law_id":1235,"seq":1,"text":"ข้อ ๔ ให้นายจ้างซึ่งมีผู้รับเหมาชั้นต้นหรือผู้รับเหมาช่วงเข้ามาปฏิบัติงานในสถานประกอบกิจการ จัดให้มีข้อบังคับและคู่มือตามข้อ ๓","status":"met","responsible":"Safety","frequency":"Annual","documents":"จัดหลักสูตรอบรมโดยทีม QA & Training","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":527,"law_id":1235,"seq":2,"text":"ข้อ ๕ ให้นายจ้างจัดการอบรมลูกจ้างให้มีความรู้เกี่ยวกับข้อบังคับและคู่มือตามข้อ ๓ ก่อนการปฏิบัติงาน","status":"met","responsible":"Safety","frequency":"Annual","documents":"จัดหลักสูตรอบรมโดยทีม QA & Training","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":528,"law_id":1235,"seq":3,"text":"ข้อ ๗ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่ยี่สิบคนขึ้นไป แต่งตั้งลูกจ้างระดับหัวหน้างาน","status":"met","responsible":"Safety","frequency":"Annual","documents":"ประกาศแต่งตั้ง จป.หัวหน้างาน","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":529,"law_id":1236,"seq":0,"text":"ข้อ ๑๖ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่หนึ่งร้อยคนขึ้นไป แต่งตั้งลูกจ้างเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพประจำสถานประกอบกิจการอย่างน้อยหนึ่งคน เพื่อปฏิบัติงานเฉพาะด้านความปลอดภัย","status":"met","responsible":"Safety","frequency":"Annual","documents":"ประกาศแต่งตั้ง จป.วิชาชีพ","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":530,"law_id":1236,"seq":1,"text":"ข้อ ๑๙ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่ยี่สิบคนขึ้นไป แต่งตั้งลูกจ้างระดับบริหารทุกคนเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับบริหารของสถานประกอบกิจการ","status":"met","responsible":"Safety","frequency":"Annual","documents":"ประกาศแต่งตั้ง จป.บริหาร","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":531,"law_id":1236,"seq":2,"text":"ข้อ ๒๓ สถานประกอบกิจการที่มีลูกจ้างตั้งแต่หนึ่งร้อยคนขึ้นไปแต่ไม่ถึงห้าร้อยคน ให้มีกรรมการไม่น้อยกว่าเจ็ดคน ประกอบด้วย นายจ้างหรือผู้แทนนายจ้างระดับบริหาร เป็นประธานกรรมการผู้แทนนายจ้างระดับบังคับบัญชาสองคนและผู้แทนลูกจ้างสามคน เป็นกรรมการ โดยมีเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพ เป็นกรรมการและเลขานุการ","status":"met","responsible":"Safety","frequency":"Annual","documents":"ประกาศแต่งตั้ง คปอ.","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":532,"law_id":1236,"seq":3,"text":"ข้อ ๓๓ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่สองร้อยคนขึ้นไป จัดให้มีหน่วยงานความปลอดภัยภายในสามร้อยหกสิบวันนับแต่วันที่กฎกระทรวงนี้มีผลใช้บังคับ หรือภายในสามร้อยหกสิบวันนับแต่วันที่มีลูกจ้างครบสองร้อยคน","status":"met","responsible":"Safety","frequency":"Annual","documents":"จำนวนพนักงานในบริษัทฯ","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":533,"law_id":1236,"seq":4,"text":"ข้อ ๓๖ ให้นายจ้างแจ้งชื่อเจ้าหน้าที่ความปลอดภัยในการทำงานตามหมวด ๑ เพื่อขึ้นทะเบียนต่อกรมสวัสดิการและคุ้มครองแรงงาน ตามหลักเกณฑ์และวิธีการที่อธิบดีประกาศกำหนด","status":"met","responsible":"Safety","frequency":"Annual","documents":"ส่งเอกสารแต่งตั้งจป. เพื่อแจ้งขึ้นทะเบียนกับ กรมสวัสดิการและคุ้มครองแรงงานจังหวัด","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":534,"law_id":1236,"seq":5,"text":"ข้อ ๓๗ ให้นายจ้างส่งรายงานผลการดำเนินงานของเจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิคขั้นสูงและระดับวิชาชีพต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายตามแบบที่อธิบดีประกาศกำหนด ทุกสามเดือนตามปีปฏิทิน ทั้งนี้ ภายในเวลาไม่เกินสามสิบวันนับแต่วันที่ครบกำหนด","status":"met","responsible":"Safety","frequency":"Annual","documents":"รายงานผลการดำเนินการเจ้าหน้าที่ความปลอดภัยในการทำงาน (จปว.)","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":503,"law_id":141,"seq":0,"text":"-\t(มาตรา 41 วรรค 1) ลูกจ้างหญิงมีสิทธิลาคลอดได้ไม่เกิน 120 วัน หรือตามวันที่กำหนดในพระราชกฤษฎีกา โดยนายจ้างต้องจ่ายค่าจ้างในอัตราค่าจ้างในวันทำงานปกติแต่จ่ายไม่เกิน 60 วันหรือตามที่กำหนดในพระราชกฤษฎีก่า\n-\t(มาตรา 41 วรรค 4) ลูกจ้างหญิงที่ใช้สิทธิลาคลอดแล้ว มีสิทธิลาต่อเนื่องเพื่อเลี้ยงดูบุตรได้อีกไม่เกิน 15 วัน สำหรับกรณีที่บุตรเจ็บป่วยเสี่ยงต่อการเกิดโรคแทรกซ้อน มีความผิดปกติ หรือมีภาวะความพิการ (ต้องแสดงใบรับรองแพทย์) โดยนายจ้างต้องจ่ายค่าจ้างในอัตรา 15% ของค่าจ้างสำหรับวันที่ลา\n-\t(มาตรา 41/1) ลูกจ้างมีสิทธิลาเพื่อช่วยเหลือคู่สมรสที่คลอดบุตรได้ไม่เกิน 15 วัน (ต้องใช้สิทธิก่อนหรือในวันที่ลา ภายใน 90 วันนับแต่วันคลอดบุตร) โดยนายจ้างต้องจ่ายค่าจ้างในอัตราค่าจ้างในวันทำงานปกติตลอดระยะเวลาที่ลา แต่ไม่เกิน 15 วัน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":535,"law_id":1236,"seq":6,"text":"ข้อ ๓๘ เมื่อลูกจ้างประสบอันตราย เจ็บป่วย หรือสูญหายตามกฎหมายว่าด้วยเงินทดแทนให้นายจ้างแจ้งการประสบอันตราย เจ็บป่วย หรือสูญหายต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายตามหลักเกณฑ์และวิธีการที่อธิบดีประกาศกำหนด ภายในสิบห้าวันนับแต่วันที่นายจ้างทราบหรือควรจะได้ทราบถึงการประสบอันตราย เจ็บป่วย หรือสูญหาย","status":"met","responsible":"Safety","frequency":"Annual","documents":"รายงานผลการดำเนินการเจ้าหน้าที่ความปลอดภัยในการทำงาน (จปว.)","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":536,"law_id":1236,"seq":7,"text":"ข้อ ๔๐ นายจ้างต้องจัดทำสำเนาบันทึก รายงานการดำเนินงาน หรือรายงานการประชุมเกี่ยวกับการดำเนินการของคณะกรรมการและหน่วยงานความปลอดภัย เก็บไว้ในสถานประกอบกิจการเป็นเวลาไม่น้อยกว่าสองปีนับแต่วันจัดทำ และพร้อมที่จะให้พนักงานตรวจแรงงานตรวจสอบ","status":"met","responsible":"Safety","frequency":"Annual","documents":"บันทึกการประชม คปอ.ประจำเดือน","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":537,"law_id":1236,"seq":8,"text":"ข้อ ๔๑ ให้นายจ้างส่งสำเนารายชื่อคณะกรรมการและหน้าที่รับผิดชอบตามข้อ ๓๒ ต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายภายในสิบห้าวันนับแต่วันที่แต่งตั้งหรือเปลี่ยนแปลงกรรมการ","status":"met","responsible":"Safety","frequency":"Annual","documents":"จัดทำประกาศแต่งตั้ง และส่งสำเนาประกาศ","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":538,"law_id":1238,"seq":0,"text":"2. ให้นายจ้างติดประกาศสัญลักษณ์เตือนอันตราย และเครื่องหมายเกี่ยวกับความปลอดภัยฯ ให้เหมาะสมกับลักษณะและสภาพการทำงานในที่ที่เห็นได้ง่าย ณ สถานประกอบกิจการ","status":"met","responsible":"Safety\nData center\nMTN\nImplement","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":539,"law_id":1238,"seq":1,"text":"3. ให้นายจ้างติดประกาศข้อความแสดงสิทธิและหน้าที่ของนายจ้างและลูกจ้างตามที่กำหนดไว้ในประกาศฉบับนี้ ในที่ที่เห็นได้ง่าย ณ สถานประกอบกิจการ ซึ่งต้องประกอบด้วยข้อความต่อไปนี้","status":"met","responsible":"Safety","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":540,"law_id":1238,"seq":2,"text":"(1) นายจ้างและลูกจ้างมีหน้าที่ในการปฏิบัติตามพระราชบัญญัติความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554","status":"met","responsible":"Safety","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":541,"law_id":1238,"seq":3,"text":"(2) นายจ้างมีหน้าที่จัดและดูแลสถานประกอบการและลูกจ้างให้มีสภาพการทำงานและสภาพแวดล้อมในการทำงานที่ปลอดภัยและถูกสุขลักษณะ","status":"met","responsible":"Safety","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":542,"law_id":1238,"seq":4,"text":"(3) นายจ้างมีหน้าที่จัดและดูแลให้ลูกจ้างสวมใส่อุปกรณ์ป้องกันอันตรายส่วนบุคคล","status":"met","responsible":"Safety\nData center\nMTN\nImplement","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":543,"law_id":1238,"seq":5,"text":"(4) นายจ้างมีหน้าที่จัดให้ผู้บริหาร หัวหน้างานและลูกจ้างทุกคนได้รับการฝึกอบรมให้สามารถบริหารจัดการและดำเนินงานด้านความปลอดภัย อาชีวอนามัยและสภาพแวดล้อมในการทำงานได้อย่างปลอดภัย","status":"met","responsible":"Safety\nQA","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":544,"law_id":1238,"seq":6,"text":"(5) นายจ้างมีหน้าที่แจ้งให้ลูกจ้างทราบถึงอันตรายที่อาจเกิดขึ้นจากการทำงานและแจกคู่มือปฏิบัติงานให้ลูกจ้างทุกคน","status":"met","responsible":"Safety","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":545,"law_id":1238,"seq":7,"text":"(6) นายจ้างมีหน้าที่ติดประกาศ คำเตือน คำสั่ง หรือคำวินิจฉัยของอธิบดีกรมสวัสดิการและคุ้มครองแรงงาน พนักงานตรวจความปลอดภัย หรือคณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน แล้วแต่กรณี","status":"met","responsible":"Safety","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":62,"law_id":93,"seq":0,"text":"พระราชบัญญัติคุ้มครองแรงงาน พ.ศ. 2541 — ชั่วโมงทำงาน วันหยุด ค่าล่วงเวลา สวัสดิการ และคณะกรรมการสวัสดิการ","status":"met","responsible":"HR / Safety","frequency":"Annual","documents":"ข้อบังคับเกี่ยวกับการทำงาน","note":"","evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":504,"law_id":142,"seq":0,"text":"การติดตั้งแผงโซล่าเซลล์ที่มีน้ำหนักรวมในบริเวณที่ติดตั้งไม่เกิน 20 กิโลกรัม/ตารางเมตร บนหลังคาของอาคาร ไม่ต้องขออนุญาตก่อสร้าง (อ.1)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":546,"law_id":1238,"seq":8,"text":"(7) นายจ้างเป็นผู้ออกค่าใช้จ่ายในการดำเนินงานด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน","status":"met","responsible":"Safety\nOFP","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":547,"law_id":1238,"seq":9,"text":"(8) ลูกจ้างมีหน้าที่ให้ความร่วมมือกับนายจ้างในการดำเนินการและส่งเสริมด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน โดยคำนึงถึงสภาพของงานและหน้าที่รับผิดชอบ","status":"met","responsible":"ทุกคน","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":548,"law_id":1238,"seq":10,"text":"(9) ลูกจ้างมีหน้าที่แจ้งข้อบกพร่องของสภาพการทำงานหรือการชำรุดเสียหายของอาคาร สถานที่ เครื่องมือ เครื่องจักร หรืออุปกรณ์ ที่ไม่สามารถแก้ไขด้วยตนเองต่อเจ้าหน้าที่ความปลอดภัยในการทำงาน หัวหน้างาน หรือผู้บริหาร","status":"met","responsible":"ทุกคน","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":549,"law_id":1238,"seq":11,"text":"(10) ลูกจ้างมีหน้าที่สวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่นายจ้างจัดให้และดูแลให้สามารถใช้งานได้","status":"met","responsible":"ทุกคน","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":550,"law_id":1238,"seq":12,"text":"(11) ในสถานที่ที่มีสถานประกอบกิจการหลายแห่ง ลูกจ้างมีหน้าที่ปฏิบัติตามหลักเกณฑ์เกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานของนายจ้าง และสถานประกอบกิจการอื่นที่ไม่ใช่ของนายจ้างด้วย","status":"met","responsible":"ทุกคน","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":551,"law_id":1238,"seq":13,"text":"(12) ลูกจ้างมีสิทธิได้รับความคุ้มครองจากการเลิกจ้าง หรือถูกโยกย้ายหน้าที่การงานเพราะเหตุที่ฟ้องร้อง เป็นพยาน ให้หลักฐาน หรือให้ข้อมูลเกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานต่อพนักงานตรวจความปลอดภัย คณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน หรือศาล","status":"met","responsible":"ทุกคน","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":552,"law_id":1238,"seq":14,"text":"(13) ลูกจ้างมีสิทธิได้รับค่าจ้างหรือสิทธิประโยชน์อื่นใด ในระหว่างหยุดการทำงานหรือหยุดกระบวนการผลิตตามคำสั่งของพนักงานตรวจความปลอดภัย เว้นแต่ลูกจ้างที่จงใจกระทำการอันเป็นเหตุให้มีการหยุดการทำงานหรือหยุดกระบวนการผลิต","status":"met","responsible":"ทุกคน","frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":553,"law_id":1282,"seq":0,"text":"ปฏิบัติตามสิทิ์ประกันพระราชบัญญัติเงินทดแทนกรณีผู้ประกันตนประสบอันตรายเจ็บป่วยจากการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":554,"law_id":1352,"seq":0,"text":"ข้อ 4 ให้นายจ้างจัดให้มีคณะกรรมการสวัสดิการภายใน 30 วัน นับตั้งแต่วันที่มีลูกจ้างครบ 50 คน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":555,"law_id":1352,"seq":1,"text":"ข้อ 6 ให้ลูกจ้างในสถานประกอบกิจการทุกคนมีสิทธิสมัครรับเลือกตั้ง และมีสิทธิลงคะแนนเสียงเลือกตั้ง โดยวิธีการทางอิเล็กทรอนิกส์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":800,"law_id":120,"seq":1,"text":"2. การควบคุมความมั่นคงปลอดภัยไซเบอร์\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":498,"law_id":136,"seq":0,"text":"\"เพื่อยกเว้นภาษีเงินได้ ภาษีมูลค่าเพิ่ม ภาษีธุรกิจเฉพาะ และอากรแสตมป์ในบางกรณี\n-\tให้ยกเว้นภาษีเงินได้ สำหรับการบริจาคผ่านระบบบริจาคอิเล็คทรอนิกส์ให้แก่สำนักงานบริหารและพัฒนาองค์ความรู้ (องค์กรมหาชน)\nที่ได้กระทำตั้งแต่วันที่ 1 มกราคม 2568 – 31 ธันวาคม 2568 โดยสำหรับนิติบุคคล ให้ยกเว้นสำหรับเงินได้จำนวน 2 เท่าของรายจ่ายที่บริจาค ไม่ว่าจะได้จ่ายเป็นเงินหรือทรัพย์สิน\n-\tต้องนำเงินได้ที่ได้รับยกเว้นข้างต้น มารวมคำนวณกับรายจ่ายที่ได้มีพระราชกฤษฎีกาที่ออกตามความในประมวลรัษฎากรกำหนดให้มีการได้รับยกเว้นภาษีเงินได้เป็นจำนวน 2 เท่าของรายจ่ายและไม่เกินร้อยละ 10 ของกำไรสุทธิก่อนหักรายจ่ายเพื่อการกุศลสาธารณะหรือเพื่อการสาธารณประโยชน์ และรายจ่ายเพื่อการศึกษาหรือเพื่อการกีฬาตามมาตรา 65 ตรี (3) (ข) แห่งประมวลรัษฎากร และ เมื่อรวมคำนวณรายจ่ายตามข้างต้นแล้ว ต้องไม่เกินร้อยละ 10 ของกำไรสุทธิก่อนหักรายจ่ายเพื่อการกุศลสาธารณะหรือเพื่อการสาธารณประโยชน์ และรายจ่ายเพื่อการศึกษาหรือเพื่อการกีฬาตามมาตรา 65 ตรี (3) (ข) แห่งประมวลรัษฎากร\n-\tให้ยกเว้นภาษีเงินได้ ภาษีมูลค่าเพิ่ม ภาษีธุรกิจเฉพาะ และอากรแสตมป์ ให้แก่นิติบุคคล สำหรับเงินได้ที่ได้รับจากการโอนทรัพย์สิน หรือการขายสินค้า หรือสำหรับการกระทำตราสารอันเนื่องมาจากการบริจาคให้แก่สำนักงานบริหาร และพัฒนาองค์ความรู้ (องค์การมหาชน) โดยผู้โอนจะต้องไม่นำต้นทุนของทรัพย์สินหรือสินค้า ซึ่งได้รับยกเว้นภาษีดังกล่าวมาหักเป็นค่าใช้จ่ายในการคำนวณภาษีเงินได้ของนิติบุคคล สำหรับการบริจาคที่ได้กระทำตั้งแต่วันที่ 1 มกราคม 2568 – 31 ธันวาคม 2568 \n-\tนิติบุคคลที่ได้ใช้สิทธิยกเว้นภาษีเงินได้ ตามพระราชกฤษฎีกานี้ ต้องไม่นำเงินบริจาคที่ได้ใช้สิทธิยกเว้นภาษีเงินได้ดังกล่าวไปหักลดหย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":505,"law_id":143,"seq":0,"text":"-\tตั้งแต่วันที่ 1 มกราคม 2569 – 31 ธันวาคม 2571 จำนวนค่าจ้างไม่ต่ำกว่าเดือนละ 1,650 บาท แต่ไม่เกิน 17,500 บาท\n-\tตั้งแต่วันที่ 1 มกราคม 2572 – 31 ธันวาคม 2574 จำนวนไม่ต่ำกว่าเดือนละ 1,650 บาท แต่ไม่เกิน 20,000 บาท\n-\tตั้งแต่วันที่ 1 มกราคม 2575 เป็นต้นไป จำนวนไม่ต่ำกว่าเดอนละ 1,650 บาท แต่ไม่เกิน 23,000 บาท","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":875,"law_id":1402,"seq":0,"text":"ข้อ ๒๔: สถานประกอบกิจการที่ตั้งขึ้นก่อนวันที่กฎกระทรวงนี้มีผลใช้บังคับ ต้องดำเนินการปรับปรุงแก้ไขให้เป็นไปตามกฎกระทรวงนี้ภายในหนึ่งปีนับแต่วันที่กฎกระทรวงนี้มีผลใช้บังคับ","status":"unmet","responsible":"ผู้ดำเนินกิจการ/สถานประกอบกิจการที่ตั้งขึ้นก่อนวันบังคับใช้","frequency":"ครั้งเดียว (ภายในกำหนดเวลา)","documents":"-","note":null,"evaluated_by":"QA & SHE","evaluated_at":"2026-08-13T03:51:55.401+00:00","evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":744,"law_id":85,"seq":9,"text":"10. การใช้บันไดไต่ชนิดเคลื่อนย้ายได้, บันไดไต่ชนิดติดตรึงกับที่ที่มีความสูงเกิน 6 เมตรขึ้นไป, ขาหยั่งหรือม้ายืน นายจ้างต้องดูแลบันได ขาหยั่งหรือม้ายืนให้ปลอดภัยต่อการใช้งาน และเป็นไปตามที่กฎกระทรวงฉบับนี้กำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":499,"law_id":137,"seq":0,"text":"เพื่อยกเว้นภาษีเงินได้ ภาษีมูลค่าเพิ่ม ภาษีธุรกิจเฉพาะ และอากรแสตมป์ในบางกรณี\n-\tให้ยกเว้นภาษีเงินได้ สำหรับการบริจาคผ่านระบบบริจาคอิเล็คทรอนิกส์ให้แก่สภากาชาดไทยหรือมูลนิธิที่ได้กระทำตั้งแต่วันที่ 1 มกราคม 2568 – 31 ธันวาคม 2568 โดยสำหรับนิติบุคคล ให้ยกเว้นสำหรับเงินได้จำนวน 2 เท่าของรายจ่ายที่บริจาค ไม่ว่าจะได้จ่ายเป็นเงินหรือทรัพย์สิน\n-\tต้องนำเงินได้ที่ได้รับยกเว้นข้างต้น มารวมคำนวณกับรายจ่ายที่ได้มีพระราชกฤษฎีกาที่ออกตามความในประมวลรัษฎากรกำหนดให้มีการได้รับยกเว้นภาษีเงินได้เป็นจำนวน 2 เท่าของรายจ่ายและไม่เกินร้อยละ 10 ของกำไรสุทธิก่อนหักรายจ่ายเพื่อการกุศลสาธารณะหรือเพื่อการสาธารณประโยชน์ และรายจ่ายเพื่อการศึกษาหรือเพื่อการกีฬาตามมาตรา 65 ตรี (3) (ข) แห่งประมวลรัษฎากร และ เมื่อรวมคำนวณรายจ่ายตามข้างต้นแล้ว ต้องไม่เกินร้อยละ 10 ของกำไรสุทธิก่อนหักรายจ่ายเพื่อการกุศลสาธารณะหรือเพื่อการสาธารณประโยชน์ และรายจ่ายเพื่อการศึกษาหรือเพื่อการกีฬาตามมาตรา 65 ตรี (3) (ข) แห่งประมวลรัษฎากร\n-\tให้ยกเว้นภาษีเงินได้ ภาษีมูลค่าเพิ่ม ภาษีธุรกิจเฉพาะ และอากรแสตมป์ ให้แก่นิติบุคคล สำหรับเงินได้ที่ได้รับจากการโอนทรัพย์สิน หรือการขายสินค้า หรือสำหรับการกระทำตราสารอันเนื่องมาจากการบริจาคให้แก่สำนักงานบริหาร และพัฒนาองค์ความรู้ (องค์การมหาชน) โดยผู้โอนจะต้องไม่นำต้นทุนของทรัพย์สินหรือสินค้า ซึ่งได้รับยกเว้นภาษีดังกล่าวมาหักเป็นค่าใช้จ่ายในการคำนวณภาษีเงินได้ของนิติบุคคล สำหรับการบริจาคที่ได้กระทำตั้งแต่วันที่ 1 มกราคม 2568 – 31 ธันวาคม 2568 \n-\tนิติบุคคลที่ได้ใช้สิทธิยกเว้นภาษีเงินได้ ตามพระราชกฤษฎีกานี้ ต้องไม่นำเงินบริจาคที่ได้ใช้สิทธิยกเว้นภาษีเงินได้ดังกล่าวไปหักลดหย่อนเป็นเงินบริจาคตามมาตรา 4","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":165,"law_id":1,"seq":0,"text":"3. การแจ้งการดำเนินการหรือส่งเอกสารต่ออธิบดี ผู้ซึ่งอธิบดีมอบหมายหรือพนักงานตรวจแรงงาน นายจ้างอาจแจ้งหรือส่งทางสื่ออิเล็กทรอนิกส์สำหรับการแจ้งหรือส่งดังต่อไปนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":166,"law_id":1,"seq":1,"text":"แบบการแจ้งทางสื่ออิเล็กทรอนิกส์ ให้เป็นไปตามแบบท้ายประกาศนี้แนบท้าย\n- แบบแจ้งรายละเอียดของสารเคมีอันตรายในสถานประกอบการ(แบบ สอ.1)\n- แบบรายงานผลการฝึกซ้อมดับเพลิงและฝึกซ้อมหนีไฟ \n- แบบรายงานการแจ้งผลการตรวจสุขภาพที่พบความผิดปกติหรือการเจ็บป่วย การให้การรักษาพยาบาล และการป้องกัน แก้ไข\n- แบบรายงานผลการตรวจสุขภาพของลูกจ้างที่ผิดปกติหรือเจ็บป่วยซึ่งได้รับอันตรายจากความร้อน แสง เสียง\n- แบบรายงานผลการดำเนินงานของเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพ (แบบ จป.(ว))","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":167,"law_id":1,"seq":2,"text":"4. นายจ้างที่มีรายชื่อสถานประกอบการอยู่ในระบบฐานข้อมูลของกรมสวัสดิการและคุ้มครองแรงงาน หากประสงค์จะแจ้งการดำเนินการหรือส่งเอกสาร ต้องลงทะเบียนเพื่อขอรับชื่อผู้ใช้ (user name) และรหัสผู้ใช้(password) ทางระบบเครือข่ายอินเตอร์เน็ต (www.labour.go.th)  *** การลงทะเบียนเพื่อขอรับชื่อผู้ใช้และรหัสผู้ใช้ทางระบบเครือข่ายอินเตอร์เน็ตเพื่อแจ้งการดำเนินการหรือส่งเอกสารทางสื่ออิเล็กทรอนิกส์ ไม่เป็นการตัดสิทธิของนายจ้างในการแจ้งการดำเนินการหรือส่งเอกสารด้วยตนเอง ทางไปรษณีย์ หรือทางโทรสาร แต่อย่างใด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":168,"law_id":1,"seq":3,"text":"5. เมื่อนายจ้างได้รับชื่อผู้ใช้และรหัสผู้ใช้แล้ว นายจ้างสามารถแจ้งการดำเนินการหรือส่งเอกสารทางสื่ออิเล็กทรอนิกส์ผ่านระบบเครือข่ายอินเตอร์เน็ต (www.labour.go.th)*** การแจ้งการดำเนินการหรือส่งเอกสาร ให้ถือว่าอธิบดี ผู้ซึ่งอธิบดีมอบหมายหรือพนักงานตรวจแรงงานได้รับแจ้งหรือได้รับเอกสารในวันและเวลาตามที่ปรากฏที่เครื่องคอมพิวเตอร์แม่ข่ายกรมสวัสดิการและคุ้มครองแรงงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":169,"law_id":2,"seq":0,"text":"มาตรา ๖ ให้นายจ้างมีหน้าที่จัดและดูแลสถานประกอบกิจการและลูกจ้างให้มีสภาพการทำงานและสภาพแวดล้อมในการทำงานที่ปลอดภัยและถูกสุขลักษณะ รวมทั้งส่งเสริมสนับสนุนการปฏิบัติงานของลูกจ้างมิให้ลูกจ้างได้รับอันตรายต่อชีวิต ร่างกาย จิตใจ และสุขภาพอนามัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":170,"law_id":2,"seq":1,"text":"มาตรา ๘ ให้นายจ้างบริหาร จัดการ และดำเนินการด้านความปลอดภัย อาชีวอนามัยและสภาพแวดล้อมในการทำงาน ให้เป็นไปตามมาตรฐานที่กำหนดในกฎกระทรวง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":171,"law_id":2,"seq":2,"text":"มาตรา ๑๓ ให้นายจ้างจัดให้มีเจ้าหน้าที่ความปลอดภัยในการทำงานและจะต้องขึ้นทะเบียนต่อกรมสวัสดิการและคุ้มครองแรงงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":172,"law_id":2,"seq":3,"text":"มาตรา ๑๖ ให้นายจ้างจัดให้ผู้บริหาร หัวหน้างาน และลูกจ้างทุกคนได้รับการฝึกอบรม ความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน ในกรณีที่นายจ้างรับลูกจ้างเข้างาน เปลี่ยนงาน เปลี่ยนสถานที่ทำงาน หรือเปลี่ยนแปลงเครื่องจักรหรืออุปกรณ์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":173,"law_id":2,"seq":4,"text":"มาตรา ๑๗ ให้นายจ้างติดประกาศสัญลักษณ์เตือนอันตรายและเครื่องหมายเกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":174,"law_id":2,"seq":5,"text":"มาตรา ๒๒ ให้นายจ้างจัดและดูแลให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่ได้มาตรฐานตามที่อธิบดีประกาศกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":175,"law_id":2,"seq":6,"text":"มาตรา ๒๘ การประชุมคณะกรรมการต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของจำนวนกรรมการทั้งหมด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":176,"law_id":2,"seq":7,"text":"มาตรา ๓๒ เพื่อประโยชน์ในการควบคุม กำกับ ดูแลการดำเนินการด้านความปลอดภัยอาชีวอนามัย และสภาพแวดล้อมในการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":177,"law_id":2,"seq":8,"text":"5.  ติดประกาศสัญลักษณ์เตือนอันตรายและเครื่องหมายเกี่ยวกับความปลอดภัย อาชีวอนามัยและสภาพแวดล้อมในการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":178,"law_id":2,"seq":9,"text":"6. ติดข้อความแสดงสิทธิและหน้าที่ของนายจ้างและลูกจ้างในที่เห็นได้ง่าย ณ สถานประกอบการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":179,"law_id":2,"seq":10,"text":"9. กรณีที่สถานประกอบกิจการเกิดอุบัติภัย - กรณีที่ลูกจ้างเสียชีวิต แจ้งต่อพนักงานตรวจความปลอดภัยทันทีที่ทราบโดย โทรศัพท์ สาร หรือวิธีอื่นใด และแจ้งรายละ\nเอียดและสาเหตุเป็นหนังสือภายใน 7 วันนับแต่วันที่ลูกจ้างเสียชีวิต","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":666,"law_id":41,"seq":3,"text":"4. คุณลักษณะที่ต้องการทั่วไป   \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":667,"law_id":41,"seq":4,"text":"5. ข้อสังเกตทั่วไปสำหรับการทดสอบ    \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":180,"law_id":2,"seq":11,"text":"กรณีที่ต้องใช้เงินกองทุนทดแทน ให้เขียน กท.16 และ กท.44 \nหมายเหตุ  กรณีใช้กองทุนเงินทดแทน ต้องส่ง กท.16 และ กท.44  แจ้งนั้นต่อพนักงานตรวจความปลอดภัย ภายใน 7 วัน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":181,"law_id":2,"seq":12,"text":"มาตรา 14 กรณีที่ทำงานในสภาพแวดล้อมที่อาจทำให้ลูกจ้างได้รับอันตรายต่อชีวิต ร่างกาย จิตใจ หรือสุขภาพอนามัย ให้นายจ้างทราบถึงอันตรายที่จะเกิดขึ้นจากการ\nทำงานและแจกคู่มือปฏิบัติงานให้ลูกจ้างทุกคนก่อนที่ ลูกจ้างจะเข้าทำงาน เปลี่ยนงาน หรือเปลี่ยนสถานที่ทำงาน\nกรณีเป็นผู้รับเหมา ให้กระทำเช่นเดียวกันกับข้อกำหนดของโรงงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":182,"law_id":3,"seq":0,"text":"กำหนดให้การใช้เครื่องฟื้นคืนคลื่นหัวใจด้วยไฟฟ้าแบบอัตโนมัติ \n(Automated External Defibrillator : AED) เป็นการปฐมพยาบาล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":202,"law_id":8,"seq":0,"text":"2. ให้นายจ้างติดประกาศสัญลักษณ์เตือนอันตราย และเครื่องหมายเกี่ยวกับความปลอดภัยฯ ให้เหมาะสมกับลักษณะและสภาพการทำงานในที่ที่เห็นได้ง่าย ณ สถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":203,"law_id":8,"seq":1,"text":"3. ให้นายจ้างติดประกาศข้อความแสดงสิทธิและหน้าที่ของนายจ้างและลูกจ้างตามที่กำหนดไว้ในประกาศฉบับนี้ ในที่ที่เห็นได้ง่าย ณ สถานประกอบกิจการ ซึ่งต้องประกอบด้วยข้อความต่อไปนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":204,"law_id":8,"seq":2,"text":"(1) นายจ้างและลูกจ้างมีหน้าที่ในการปฏิบัติตามพระราชบัญญัติความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":184,"law_id":5,"seq":0,"text":"ยกเลิก\nกฎกระทรวงกำหนดหลักเกณฑ์ วิธีการ และมาตรการในการควบคุมสถานประกอบกิจการที่เป็นอันตราย\nต่อสุขภาพ พ.ศ. 2545\nข้อ 4. สถานประกอบกิจการที่มีอาคาร  ต้องมีลักษณะตามที่กำหนด\n - อาคารที่ความมั่นคงแข็งแรง  มีทางหนีไฟ บันไดหนีไฟ ทางออกฉุกเฉิน มีแสงสว่างเพียงพอ  มีป้ายหรือเครื่องหมายแสดงชัดเจน   และทางออกฉุกเฉินต้องมีไฟส่องสว่างฉุกเฉินเมื่อระบบไฟฟ้าปกติขัดข้อง\n - มีแสงสว่างและการระบายอากาศที่เหมาะสม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":185,"law_id":5,"seq":1,"text":"ข้อ 5. สถานประกอบกิจการต้องมีมาตรการความปลอดภัยในการทำงานและปฏิบัติให้เป็นไปตามกฎหมาย\nว่าด้วยความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานและกฎหมายอื่นที่เกี่ยวข้อง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":186,"law_id":5,"seq":2,"text":"ข้อ 6. สถานประกอบกิจการต้องดำเนินการดังนี้\n- ดำเนินการเกี่ยวกับวัตถุอันตรายต้องมีสถานที่ที่ปลอดภัยในการจัดเก็บ  \n- กรณีผู้ปฏิบัติงานที่อาจเปรอะเปื้อนจากสารเคมี  ต้องจัดให้มีที่ล้างตัวและที่ล้างตาฉุกเฉิน\n- การใช้อุปกรณ์ เครื่องมือ หรือเครื่องจักร ต้องติดตั้งในลักษณะที่แข็งแรง มั่นคง มีป้ายเตือนหรือคำแนะนำ\nในการป้องกันอันตราย\n- การจัดให้มีการตรวจสุขภาพพนักงานตามที่กฎหมายกำหนด \n- กรณีที่อาจก่อให้เกิดมลพิษทางเสียง มลพิษทางอากาศ  มลพิษทางน้ำ  มลพิษทางแสง มลพิษทางความร้อน มลพิษทางความสั่นสะเทือนของเสียอันตราย เป็นต้น  ให้ทำการควบคุมและป้องกันผลกระทบ เหตุรำคาญ หรืออันตรายต่อสุชภาพของพนักงานและผู้อยู่อาศัยใกล้เคียง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":217,"law_id":9,"seq":0,"text":"กำหนดให้นายจ้างต้องนารายชื่อเจ้าหน้าที่ความปลอดภัยในการทางานระดับ\nหัวหน้างาน ระดับบริหาร ระดับเทคนิค ระดับเทคนิคขั้นสูง หรือระดับวิชาชีพ และผู้บริหารหน่วยงาน\nความปลอดภัย แจ้งการขึ้นทะเบียน การพ้นจากตาแหน่งหรือพ้นจากหน้าที่ของบุคคลดังกล่าวให้กรมสวัสดิการและคุ้มครองแรงงานทราบภายในสามสิบวัน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":223,"law_id":13,"seq":0,"text":"1. ให้นายจ้างใช้ลูกจ้างทำงานยก แบก หาม หาบ ทูน ลาก หรือเข็นของหนักไม่เกินอัตราน้ำหนักโดยเฉลี่ยต่อลูกจ้างหนึ่งคน ดังต่อไปนี้  \n(1)  20 กิโลกรัมสำหรับลูกจ้างซึ่งเป็นเด็กหญิงอายุตั้งแต่ 15 ปีแต่ยังไม่ถึง 18 ปี\n (2) 25 กิโลกรัมสำหรับลูกจ้างซึ่งเป็นเด็กชายอายุตั้งแต่ 15 ปีแต่ยังไม่ถึง 18 ปี\n (3) 25 กิโลกรัมสำหรับลูกจ้างซึ่งเป็นหญิง\n (4) 55 กิโลกรัมสำหรับลูกจ้างซึ่งเป็นชาย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":227,"law_id":17,"seq":0,"text":"ยกเลิกประกาศกระทรวงอุตสาหกรรมฉบับที่ 1086 (พ.ศ. 2529) และฉบับที่ 1087 (พ.ศ. 2529) ออกตามความในพระราชบัญญัติมาตรฐานผลิตภัณฑ์อุตสาหกรรม พ.ศ. 2511 เรื่อง ยกเลิกและกำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม สีและเครื่องหมายเพื่อความปลอดภัย เล่ม 1 สีและรูปแบบ และเรื่อง กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม สีและเครื่องหมายเพื่อความปลอดภัย เล่ม 2 สมบัติทางสีและแสงของวัสดุ และออกประกาศกำหนดมาตรฐานลิตภัณฑ์อุตสาหกรรม สีและเครื่องหมายเพื่อความปลอดภัยมาตรฐานที่ มอก.635-2554 ขึ้นใหม่","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":228,"law_id":17,"seq":1,"text":"กำหนดรายละเอียดเกี่ยวกับสีที่ใช้ในการชี้บ่งความปลอดภัยและหลักการออกแบบเครื่องหมายเพื่อความปลอดภัยที่ใช้ในสถานที่ทำงานและพื้นที่สาธารณะ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":237,"law_id":21,"seq":0,"text":"กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรมระบบการจัดการอาชีวอนามัยและความปลอดภัย – ข้อกำหนดและข้อแนะนำในการใช้มาตรฐานเลขที่ มอก. 45001 - 2561","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":668,"law_id":41,"seq":5,"text":"6. พิกัด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":801,"law_id":120,"seq":2,"text":"3. การบริการงานแผนการรักษาความมั่นคงปลอดภัยไซเบอร์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":189,"law_id":7,"seq":0,"text":"ข้อ ๘ เจ้าหน้าที่ความปลอดภัยในการทำงานระดับหัวหน้างานต้องเป็นลูกจ้างระดับหัวหน้างาน\n        (๓) จัดทำคู่มือว่าด้วยความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานของ หน่วยงานที่รับผิดชอบ โดยร่วมดำเนินการกับเจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิค ระดับ เทคนิคขั้นสูง หรือระดับวิชาชีพ เพื่อเสนอคณะกรรมการความปลอดภัยหรือนายจ้าง แล้วแต่กรณี และทบทวนคู่มือดังกล่าวตามที่นายจ้างกำาหนด โดยนายจ้างต้องกำหนดให้มีการทบทวนอย่างน้อยทุกหกเดือน ข้อ ๓ ให้นายจ้างจัดให้มีข้อบังคับและคู่มือว่าด้วยความปลอดภัยในการทำงานไว้ในสถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":190,"law_id":7,"seq":1,"text":"ข้อ ๑๑ เจ้าหน้าที่ความปลอดภัยในการทำงานระดับบริหารต้องเป็นลูกจ้างระดับผู้บริหาร ข้อ ๔ ให้นายจ้างซึ่งมีผู้รับเหมาชั้นต้นหรือผู้รับเหมาช่วงเข้ามาปฏิบัติงานในสถานประกอบกิจการ จัดให้มีข้อบังคับและคู่มือตามข้อ ๓","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":191,"law_id":7,"seq":2,"text":"ข้อ ๕ ให้นายจ้างจัดการอบรมลูกจ้างให้มีความรู้เกี่ยวกับข้อบังคับและคู่มือตามข้อ ๓ ก่อนการปฏิบัติงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":192,"law_id":7,"seq":3,"text":"ข้อ ๗ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่ยี่สิบคนขึ้นไป แต่งตั้งลูกจ้างระดับหัวหน้างาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":193,"law_id":7,"seq":4,"text":"ข้อ ๒๐ นายจ้างของสถานประกอบกิจการตามบัญชี ๑ ที่มีลูกจ้างจำนวนสองคนขึ้นไป และสถานประกอบกิจการตามบัญชี ๒ ที่มีลูกจ้างจำนวนหนึ่งร้อยคนขึ้นไป ต้องจัดให้ลูกจ้างซึ่งมีคุณสมบัติ ตามข้อ ๒๑ อย่างน้อยหนึ่งคน เป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพ เพื่อปฏิบัติหน้าที่ประจำสถานประกอบกิจการ ทั้งนี้ ภายในหนึ่งร้อยแปดสิบวันนับแต่วันที่มีลูกจ้างครบจำนวนดังกล่าว ข้อ ๑๖ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่หนึ่งร้อยคนขึ้นไป แต่งตั้งลูกจ้างเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพประจำสถานประกอบกิจการอย่างน้อยหนึ่งคน เพื่อปฏิบัติงานเฉพาะด้านความปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":194,"law_id":7,"seq":5,"text":"ข้อ ๒๓ นายจ้างต้องจัดให้เจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิค ระดับเทคนิคขั้นสูง และระดับวิชาชีพได้รับการฝึกอบรมหรือมีการพัฒนาความรู้เกี่ยวกับความปลอดภัยในการทำงานเพิ่มเติมปีละไม่น้อยกว่าสิบสองชั่วโมงตามหลักสูตรที่อธิบดีประกาศกำหนด โดยนายจ้างต้องแจ้งให้อธิบดีหรือผู้ซึ่งอธิบดีมอบหมายทราบภายในสามสิบวันนับแต่วันที่การดำเนินการดังกล่าวแล้วเสร็จ ข้อ ๑๙ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่ยี่สิบคนขึ้นไป แต่งตั้งลูกจ้างระดับบริหารทุกคนเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับบริหารของสถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":195,"law_id":7,"seq":6,"text":"ข้อ ๒๕ นายจ้างของสถานประกอบกิจการที่มีลูกจ้างจำนวนห้าสิบคนขึ้นไป ต้องจัดให้มีคณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานของสถานประกอบกิจการภายในสามสิบวันนับแต่วันที่มีลูกจ้างครบจำนวนดังกล่าว \n          คณะกรรมการความปลอดภัยตามวรรคหนึ่ง ต้องประกอบด้วย นายจ้างหรือผู้แทนนายจ้างระดับบริหาร เป็นประธานกรรมการความปลอดภัย ผู้แทนนายจ้างระดับบังคับบัญชา และผู้แทนลูกจ้าง เป็นกรรมการความปลอดภัย ในการแต่งตั้งคณะกรรมการความปลอดภัยตามวรรคสอง \n         หากสถานประกอบกิจการตามวรรคหนึ่ง เป็นสถานประกอบกิจการในบัญชี ๑ หรือบัญชี ๒ ให้นายจ้างแต่งตั้งผู้แทนนายจ้าง ระดับบังคับบัญชาซึ่งเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิคขั้นสูงหรือระดับวิชาชีพ จำนวนหนึ่งคน แล้วแต่กรณี เป็นกรรมกาความปลอดภัยและเลขานุการ\n         (จำนวนคณะกรรมการความปลอดภัย (๒) ไม่น้อยกว่าเจ็ดคน ส าหรับสถานประกอบกิจการที่มีลูกจ้างจำนวนหนึ่งร้อยคนขึ้นไปแต่ไม่ถึงห้าร้อยคน) ข้อ ๒๓ สถานประกอบกิจการที่มีลูกจ้างตั้งแต่หนึ่งร้อยคนขึ้นไปแต่ไม่ถึงห้าร้อยคน ให้มีกรรมการไม่น้อยกว่าเจ็ดคน ประกอบด้วย นายจ้างหรือผู้แทนนายจ้างระดับบริหาร เป็นประธานกรรมการผู้แทนนายจ้างระดับบังคับบัญชาสองคนและผู้แทนลูกจ้างสามคน เป็นกรรมการ โดยมีเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพ เป็นกรรมการและเลขานุการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":196,"law_id":7,"seq":7,"text":"ข้อ ๓๓ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่สองร้อยคนขึ้นไป จัดให้มีหน่วยงานความปลอดภัยภายในสามร้อยหกสิบวันนับแต่วันที่กฎกระทรวงนี้มีผลใช้บังคับ หรือภายในสามร้อยหกสิบวันนับแต่วันที่มีลูกจ้างครบสองร้อยคน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":711,"law_id":82,"seq":9,"text":"๑๐) คลอรีน หรือสารประกอบคลอรีน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":712,"law_id":82,"seq":10,"text":"๑๑) แอมโมเนีย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":713,"law_id":82,"seq":11,"text":"๑๒) คาร์บอนไดซัลไฟด์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":197,"law_id":7,"seq":8,"text":"ข้อ ๔๒ นายจ้างต้องนำรายชื่อเจ้าหน้าที่ความปลอดภัยในการทำงานระดับหัวหน้างาน ระดับบริหาร ระดับเทคนิค ระดับเทคนิคขั้นสูง หรือระดับวิชาชีพ และผู้บริหารหน่วยงานความปลอดภัย ไปขึ้นทะเบียนต่อกรมสวัสดิการและคุ้มครองแรงงาน พร้อมเอกสารหรือหลักฐานตามที่ระบุไว้ในแบบคำขอ ภายในสามสิบวันนับแต่วันที่นายจ้างแต่งตั้งบุคคลดังกล่าว ข้อ ๓๖ ให้นายจ้างแจ้งชื่อเจ้าหน้าที่ความปลอดภัยในการทำงานตามหมวด ๑ เพื่อขึ้นทะเบียนต่อกรมสวัสดิการและคุ้มครองแรงงาน ตามหลักเกณฑ์และวิธีการที่อธิบดีประกาศกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":198,"law_id":7,"seq":9,"text":"ข้อ ๔๗ ให้นายจ้างจัดส่งรายงานผลการดำเนินงานของเจ้าหน้าที่ความปลอดภัยในการทำงาน ระดับเทคนิค ระดับเทคนิคขั้นสูง และระดับวิชาชีพ ต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมาย สองครั้ง โดยครั้งแรกภายในสามสิบวันนับแต่วันที่ ๓๐ มิถุนายน และครั้งที่สองภายในสามสิบวันนับแต่วันที่ ๓๑ ธันวาคม ของทุกปี ทั้งนี้ ตามแบบที่อธิบดีประกาศกำหนด ข้อ ๓๗ ให้นายจ้างส่งรายงานผลการดำเนินงานของเจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิคขั้นสูงและระดับวิชาชีพต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายตามแบบที่อธิบดีประกาศกำหนด ทุกสามเดือนตามปีปฏิทิน ทั้งนี้ ภายในเวลาไม่เกินสามสิบวันนับแต่วันที่ครบกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":199,"law_id":7,"seq":10,"text":"ข้อ ๓๘ เมื่อลูกจ้างประสบอันตราย เจ็บป่วย หรือสูญหายตามกฎหมายว่าด้วยเงินทดแทนให้นายจ้างแจ้งการประสบอันตราย เจ็บป่วย หรือสูญหายต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายตามหลักเกณฑ์และวิธีการที่อธิบดีประกาศกำหนด ภายในสิบห้าวันนับแต่วันที่นายจ้างทราบหรือควรจะได้ทราบถึงการประสบอันตราย เจ็บป่วย หรือสูญหาย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":200,"law_id":7,"seq":11,"text":"ข้อ ๔๖ เมื่อมีคำสั่งแต่งตั้งคณะกรรมการความปลอดภัยหรือกรรมการความปลอดภัย ให้นายจ้างส่งสำเนาคำสั่งดังกล่าวต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมาย ภายในสิบห้าวันนับแต่วันที่มีคำสั่ง แต่งตั้ง ข้อ ๔๐ นายจ้างต้องจัดทำสำเนาบันทึก รายงานการดำเนินงาน หรือรายงานการประชุมเกี่ยวกับการดำเนินการของคณะกรรมการและหน่วยงานความปลอดภัย เก็บไว้ในสถานประกอบกิจการเป็นเวลาไม่น้อยกว่าสองปีนับแต่วันจัดทำ และพร้อมที่จะให้พนักงานตรวจแรงงานตรวจสอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":201,"law_id":7,"seq":12,"text":"ข้อ ๔๑ ให้นายจ้างส่งสำเนารายชื่อคณะกรรมการและหน้าที่รับผิดชอบตามข้อ ๓๒ ต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายภายในสิบห้าวันนับแต่วันที่แต่งตั้งหรือเปลี่ยนแปลงกรรมการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":219,"law_id":11,"seq":0,"text":"ข้อ 41. ผู้รับใบอนุญาตประกอบกิจการโรงงาน ต้องจัดให้มีน้ำสะอาดสำหรับดื่มตามมาตรฐานน้ำบริโภคอย่างพอเพียงไว้เป็นที่ต่างหาก อย่างน้อยในอัตราคนงานไม่เกิน 40 คน 1 ที่ คนงานไม่เกิน 80 คน 2 ที่ และเพิ่มขึ้นต่อจากนี้อัตราส่วน 1 ที่ ต่อจำนวนคนงานไม่เกิน 50 คน\nข้อ 42. ต้องจัดหาและรักษาอุปกรณ์การดื่ม และภาชนะที่บรรจุน้ำดื่มให้พอเพียงและอยู่ในสภาพที่สะอาดถูกสุขลักษณะ”","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":241,"law_id":25,"seq":0,"text":"หากพบผู้ซึ่งเป็นหรือมีเหตุอันควรสงสัยว่าเป็นโรคจากการประกอบอาชีพหรือ โรคจากสิ่งแวดล้อมในเขตจังหวัด ภายในสามวันนับแต่พบผู้ซึ่งเป็นหรือมีเหตุ อันควรสงสัยว่าเป็นโรคจากการประกอบอาชีพหรือโรคจากสิ่งแวดล้อม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":400,"law_id":86,"seq":12,"text":"ข้อ ๑๗ ห้ามนายจ้างอนุญาตให้ลูกจ้างทำงานที่ใช้สารระเหยง่าย สารพิษ สารไวไฟในที่อับอากาศ เว้นแต่จะได้จัดให้มีมาตรการความปลอดภัยที่เหมาะสมตามหมวดนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":205,"law_id":8,"seq":3,"text":"(2) นายจ้างมีหน้าที่จัดและดูแลสถานประกอบการและลูกจ้างให้มีสภาพการทำงานและสภาพแวดล้อมในการทำงานที่ปลอดภัยและถูกสุขลักษณะ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":206,"law_id":8,"seq":4,"text":"(3) นายจ้างมีหน้าที่จัดและดูแลให้ลูกจ้างสวมใส่อุปกรณ์ป้องกันอันตรายส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":207,"law_id":8,"seq":5,"text":"(4) นายจ้างมีหน้าที่จัดให้ผู้บริหาร หัวหน้างานและลูกจ้างทุกคนได้รับการฝึกอบรมให้สามารถบริหารจัดการและดำเนินงานด้านความปลอดภัย อาชีวอนามัยและสภาพแวดล้อมในการทำงานได้อย่างปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":208,"law_id":8,"seq":6,"text":"(5) นายจ้างมีหน้าที่แจ้งให้ลูกจ้างทราบถึงอันตรายที่อาจเกิดขึ้นจากการทำงานและแจกคู่มือปฏิบัติงานให้ลูกจ้างทุกคน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":209,"law_id":8,"seq":7,"text":"(6) นายจ้างมีหน้าที่ติดประกาศ คำเตือน คำสั่ง หรือคำวินิจฉัยของอธิบดีกรมสวัสดิการและคุ้มครองแรงงาน พนักงานตรวจความปลอดภัย หรือคณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน แล้วแต่กรณี","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":210,"law_id":8,"seq":8,"text":"(7) นายจ้างเป็นผู้ออกค่าใช้จ่ายในการดำเนินงานด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":211,"law_id":8,"seq":9,"text":"(8) ลูกจ้างมีหน้าที่ให้ความร่วมมือกับนายจ้างในการดำเนินการและส่งเสริมด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน โดยคำนึงถึงสภาพของงานและหน้าที่รับผิดชอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":212,"law_id":8,"seq":10,"text":"(9) ลูกจ้างมีหน้าที่แจ้งข้อบกพร่องของสภาพการทำงานหรือการชำรุดเสียหายของอาคาร สถานที่ เครื่องมือ เครื่องจักร หรืออุปกรณ์ ที่ไม่สามารถแก้ไขด้วยตนเองต่อเจ้าหน้าที่ความปลอดภัยในการทำงาน หัวหน้างาน หรือผู้บริหาร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":213,"law_id":8,"seq":11,"text":"(10) ลูกจ้างมีหน้าที่สวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่นายจ้างจัดให้และดูแลให้สามารถใช้งานได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":214,"law_id":8,"seq":12,"text":"(11) ในสถานที่ที่มีสถานประกอบกิจการหลายแห่ง ลูกจ้างมีหน้าที่ปฏิบัติตามหลักเกณฑ์เกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานของนายจ้าง และสถานประกอบกิจการอื่นที่ไม่ใช่ของนายจ้างด้วย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":215,"law_id":8,"seq":13,"text":"(12) ลูกจ้างมีสิทธิได้รับความคุ้มครองจากการเลิกจ้าง หรือถูกโยกย้ายหน้าที่การงานเพราะเหตุที่ฟ้องร้อง เป็นพยาน ให้หลักฐาน หรือให้ข้อมูลเกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานต่อพนักงานตรวจความปลอดภัย คณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน หรือศาล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":216,"law_id":8,"seq":14,"text":"(13) ลูกจ้างมีสิทธิได้รับค่าจ้างหรือสิทธิประโยชน์อื่นใด ในระหว่างหยุดการทำงานหรือหยุดกระบวนการผลิตตามคำสั่งของพนักงานตรวจความปลอดภัย เว้นแต่ลูกจ้างที่จงใจกระทำการอันเป็นเหตุให้มีการหยุดการทำงานหรือหยุดกระบวนการผลิต","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":220,"law_id":12,"seq":0,"text":"ข้อ ๑ ในสถานที่ทํางานของลูกจ้าง ให้นายจ้างจัดให้มี\n(1)ต้องจัดให้มีน้ำสะอาดสำหรับดื่มตามมาตรฐานน้ำบริโภคอย่างพอเพียงไว้เป็นที่ต่างหาก อย่างน้อยในอัตราคนงานไม่เกิน 40 คน 1 ที่ เศษของสี่สิบคนถ้าเกินยี่สิบคนให้ถือเป็นสี่สิบคน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":221,"law_id":12,"seq":1,"text":"(2) ห้องน้ำและห้องส้วมตามแบบและจำนวนที่กำหนดในกฎหมายและมีการดูแลรักษาความสะอาดให้อยู่ในสภาพที่ถูกสุขลักษณะเป็นประจำทุกวัน ให้นายจ้างจัดให้มีห้องน้ำและห้องส้วมแยกสำหรับลูกจ้างชายและลูกจ้างหญิง และในกรณีที่มีลูกจ้างที่เป็นคนพิการ ให้นายจ้างจัดให้มีห้องน้ำและห้องส้วมสำหรับคนพิการแยกไว้โดยเฉพาะ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":218,"law_id":10,"seq":0,"text":"กำหนดให้นายจ้างต้องจัดให้เจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิค ระดับเทคนิคขั้นสูง และระดับวิชาชีพ ได้รับการฝึกอบรมหรือการพัฒนาความรู้เกี่ยวกับความปลอดภัยในการทำงานเพิ่มเติม ปีละไม่น้อยกว่าสิบสองชั่วโมงตามหลักสูตรที่อธิบดีประกาศกำหนด\nหลักสูตรการฝึกอบรมหรือการพัฒนาความรู้เกี่ยวกับความปลอดภัยในการทำงาน\n1.การฝึกอบรม\n  1.1 ด้านกฎหมายความปลอดภัย\n  1.3 ด้านวิชาการเกี่ยวกับความปลอดภัย\n  1.4  ด้านอื่น ๆ ที่เกี่ยวข้องกับความปลอดภัย\n2.  การพัฒนาความรู้ \n  2.1 การเข้าร่วมการประชุมหรือการสัมมนาวิชาการ\n  2.2 การนำเสนอผลงานทางวิชาการ\n  2.3 การศึกษาดูงานทั้งในประเทศและต่างประเทศ\nแจ้งรายงานผลที่ สนง.สวัสดิการหรือทางอิเลคทรอนิคส์ภายในสามสิบวันนับแต่วันที่ดำเนินการดังกล่าวแล้วเสร็จ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":238,"law_id":22,"seq":0,"text":"นายจ้างต้องจัดให้เจ้าหน้าที่ความปลอดภัยระดับเทคนิค ระดับเทคนิคขั้นสูง และระดับวิชาชีพ ได้รับการฝึกอบรมหรือการพัฒนาความรู้เกี่ยวกับความปลอดภัยในการทำงานเพิ่มเติม ปีละไม่น้อยกว่า 12 ชั่วโมงตามหลักสูตรแนบท้ายประกาศนี้ ได้แก่\n   (1) การฝึกอบรม\n          1.1 ด้านกฎหมายความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานและกฎหมายที่เกี่ยวข้อง หรือกฎหมายที่เกี่ยวข้องกับความปลอดภัยในการทำงาน เช่น พ.ร.บ.ควบคุมโรคจากการประกอบอาชีพและโรคจากสิ่งแวดล้อม พ.ศ. 2562 เป็นต้น\n          1.2 ด้านวิชาการเกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน เช่น การระบายอากาศในงานอุตสาหกรรม การควบคุมมลพิษอากาศ ระบบการจัดการอาชีวอนามัยและความปลอดภัย เป็นต้น\n          1.3 ด้านอื่น ๆ ที่เกี่ยวข้องกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน เช่น เทคนิคการเป็นวิทยากร เทคโนโลยีสะอาด สภาวะโลกร้อน  เป็นต้น\n    (2) การพัฒนาความรู้\n          2.1 การเข้าร่วมการประชุมหรือการสัมมนาวิชาการ\n          2.2 การนำเสนอผลงานทางวิชาการ และการเข้าร่วมกิจกรรมต่างๆ ที่เกี่ยวข้องกับงานความปลอดภัยอาชีวอนามัย และสภาพแวดล้อมในการทำงาน ที่จัดโดยสถาบันการศึกษา หรือหน่วยงานอื่น\n          2.3 การศึกษาดูงานทั้งในประเทศและต่างประเทศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":242,"law_id":26,"seq":0,"text":"หลักสูตร การฝึกอบรม คุณสมบัติของวิทยากร และการดำเนินการฝึกอบรมของนายจ้างหรือผู้ให้บริการ\nด้านการฝึกอบรมให้เป็นไปตามที่อธิบดีประกาศกาหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":270,"law_id":37,"seq":11,"text":"ข้อ ๓๘ เมื่อลูกจ้างประสบอันตราย เจ็บป่วย หรือสูญหายตามกฎหมายว่าด้วยเงินทดแทนให้นายจ้างแจ้งการประสบอันตราย เจ็บป่วย หรือสูญหายต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายตามหลักเกณฑ์และวิธีการที่อธิบดีประกาศกำหนด ภายในสิบห้าวันนับแต่วันที่นายจ้างทราบหรือควรจะได้ทราบถึงการประสบอันตราย เจ็บป่วย หรือสูญหาย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":401,"law_id":86,"seq":13,"text":"หมวด ๓ การอนุญาต","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":224,"law_id":14,"seq":0,"text":"1. ให้งานทุกประเภทมีเวลาทำงานปกติไม่เกิน 8 ชั่วโมง \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":229,"law_id":18,"seq":0,"text":"กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม หลักการและแนวทางการบริหารความเสี่ยง  มาตรฐานเลขที่ มอก. 31000-2555 (ISO 31000 : 2009)\n1. ขอบข่าย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":222,"law_id":12,"seq":2,"text":"ข้อ 2.ในสถานที่ทำงานของลูกจ้าง ให้นายจ้างจัดให้มีสิ่งจำเป็นในการปฐมพยาบาลและการรักษาพยาบาล ดังต่อไปนี้\n(2.1) สถานที่ทำงานที่มีลูกจ้างทำงานตั้งแต่สิบคนขึ้นไป ต้องจัดให้มีเวชภัณฑ์และยาเพื่อใช้ในการปฐมพยาบาลในจำนวนที่เพียงพอ อย่างน้อยตามรายการที่กำหนด ดังนี้\nให้นายจ้างจัดให้มีสิ่งจำเป็นในการปฐมพยาบาลและการรักษาพยาบาล ดังต่อไปนี้\n- กรรไกร  - แก้วยาน้ำ และแก้วยาเม็ด  - เข็มกลัด  - ถ้วยน้ำ\n- ที่ป้ายยา  - ปรอทวัดไข้  - ปากคีบปลายทู่  - ผ้าพันยืด  - ผ้าสามเหลี่ยม\n- สายยางรัดห้ามเลือด  - สำลี ผ้าก๊าซ ผ้าพันแผล และผ้ายางปลาสเตอร์ปิดแผล\n- หลอดหยดยา  - ขี้ผึ้งแก้ปวดบวม  - ทิงเจอร์ไอโอดีน หรือโพวิโดน-ไอโอดีน\n- น้ำยาโพวิโดน-ไอโอดีน ชนอดฟอกแผล  - ผงน้ำตาลเกลือแร่\n- ยาแก้ผดผื่นที่ไม่ได้มาจากการติดเชื้อ  - ยาแก้แพ้  - ยาทาแก้ผดผื่นคัน\n- ยาธาตุน้ำแดง - ยาบรรเทาปวดลดไข้  - ยารักษาแผลน้ำร้อนลวก\n- ยาลดกรดในกระเพาะอาหาร  - เหล้าแอมโมเนียหอม  - แอลกอฮอล์เช็ดแผล\n- ขี้ผึ้งป้ายตา  - ถ้วยล้างตา  - น้ำกรดบอริคล้างตา  - ยาหยอดตา","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":226,"law_id":16,"seq":0,"text":"ออกประกาศกำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม รองเท้าหนังนิรภัย มาตรฐานเลขที่ มอก. 523-2554 ขึ้นใหม่ ดังท้ายประกาศนี้  ครอบคลุมเฉพาะรองเท้านิรภัยที่ทำด้วยหนังแท้หรือหนังเทียมเท่านั้น","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":232,"law_id":20,"seq":0,"text":"3. การแจ้งเป็นหนังสือในกรณีที่สถานประกอบกิจการเกิดอุบัติภัยร้ายแรง หรือลูกจ้างประสบอันตรายจากการทำงาน และสภาพแวดล้อมในการทำงาน ตามมาตรา 34 วรรคสอง แห่งพระราชบัญญัติความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554 ให้เป็นไปตามแบบ สปร. 5 ท้ายประกาศนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":233,"law_id":20,"seq":1,"text":"(1) กรณีลูกจ้างเสียชีวิต ให้แจ้งในทันทีที่ทราบโดยโทรศัพท์ โทรสาร หรือวิธีอื่นใดที่มีรายละเอียดพอสมควร และแจ้งเป็นหนังสือต่อพนักงานตรวจความปลอดภัยตามแบบ สปร. 5  ภายใน 7 วัน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":234,"law_id":20,"seq":2,"text":"(2) กรณีที่สถานประกอบกิจการได้รับความเสียหายหรือต้องหยุดการผลิต หรือมีบุคคลประสบอันตรายหรือได้รับความเสียหายอันเนื่องมาจากเพลิงไหม้ การระเบิด สารเคมีรั่วไหล หรืออุบัติภัยร้ายแรงอื่น ให้นายจ้างแจ้งต่อพนักงานตรวจความปลอดภัยในทันทีที่ทราบโดยโทรศัพท์ โทรสาร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":235,"law_id":20,"seq":3,"text":"หรือวิธีอื่นใด และให้แจ้งเป็นหนังสือโดยระบุสาเหตุอันตรายที่เกิดขึ้น ความเสียหาย การแก้ไขและวิธีการป้องกันการเกิดซ้ำอีกตามแบบ สปร. 5  ภายใน 7 วัน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":236,"law_id":20,"seq":4,"text":"(3) กรณีที่มีลูกจ้างประสบอันตราย หรือเจ็บป่วยตามกฎหมายว่าด้วยเงินทดแทน เมื่อนายจ้างแจ้งการประสบอันตรายหรือเจ็บป่วยต่อสำนักงานประกันสังคมตามกฎหมายดังกล่าวแล้ว ให้นายจ้างนำสำเนา กท. 16 เพียงอย่างเดียวแจ้งต่อพนักงานตรวจความปลอดภัยภายใน 7 วัน ทั้งนี้ อาจแนบแบบ สปร.5 ไปด้วยหรือไม่ก็ได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":244,"law_id":28,"seq":0,"text":"ให้ผู้รับใบสำคัญและผู้รับใบอนุญาต ที่ให้บริการการจัดฝึกอบรมหรือให้คำปรึกษา แจ้งกำหนดการให้บริการแต่ละครั้งก่อนการให้บริการไม่น้อยกว่า 7 วัน (แบบกภ.จ.1   ถึงแบบ  กภ.จ.4)\n และส่งรายงานสรุปผล การให้บริการพร้อมด้วยเอกสารภายใน 30 วัน นับแต่วันที่เสร็จสิ้นการให้บริการ (แบบ  กภ.รง.1  ถึงแบบ  กภ.รง.9)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":248,"law_id":32,"seq":0,"text":"ข้อ 2 ยกเลิกประกาศกรมฯ เรื่อง การเทียบเท่าวุฒิการศึกษาไม่ต่ำกว่าปริญญาตรีสาขาอาชีวอนามัยและความปลอดภัย (26 กันยายน 2566) ข้อ 3","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":225,"law_id":15,"seq":0,"text":"3. มาตรฐานอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล ได้แก่ มาตรฐานผลิตภัณฑ์อุตสาหกรรม มาตรฐานขององค์กรมาตรฐานสากลโลก  (International Standardization and Organization : ISO) มาตรฐานสหภาพยุโรป (European Standards : EN) มาตรฐานประเทศออสเตรเลียและ ประเทศนิวซีแลนด์ (Australia Standards/New Zealand Standards :  AS/NZS) มาตรฐานสถาบันมาตรฐานแห่งชาติประเทศสหรัฐอเมริกา   (American National Standaeds Institute : ANSI) มาตรฐานอุตสาหกรรมประเทศญี่ปุ่น(Japanese Industrial Standards : JIS) มาตรฐานสถาบัน ความปลอดภัยและอนามัยในการทำงานแห่งชาติประเทศสหรัฐอเมริกา (The National Institute for Ocupational Safety and Health : NIOSH)  มาตรฐานสำนักงานบริหารความปลอดภัย และอาชีวอนามัยแห่งชาติ         กรมแรงงานประเทศสหรัฐอเมริกา  (Occupational Safety and Health Administration : OSHA) และมาตรฐานสมาคมป้องกันอัคคีภัยแห่งชาติสหรัฐอเมริกา(National Fire Protection Association : NFPA)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":231,"law_id":19,"seq":0,"text":"มาตรา 18    เมื่อลูกจ้างประสบอันตราย  หรือเจ็บป่วย  หรือสูญหาย  ให้นายจ้างจ่ายค่าทดแทนเป็นรายเดือนให้แก่ลูกจ้างหรือผู้มีสิทธิแล้วแต่กรณี ดังนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":239,"law_id":23,"seq":0,"text":"ให้นายจ้างจัดส่งรายงานผลการดำเนินงานของ จป. ระดับเทคนิค จป.ระดับเทคนิคขั้นสูง และ จป.ระดับวิชาชีพ ตามแบบ จป.ท จป.ส และ จป.ว ท้ายประกาศนี้ จำนวน 2 ครั้ง  โดยครั้งแรกภายใน 30 วันนับแต่วันที่ 30 มิถุนายน และครั้งที่สอง ภายใน 30 วันนับแต่วันที่ 31 ธันวาคม ของทุกปี","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":243,"law_id":27,"seq":0,"text":"กำหนดหลักสูตรคณะกรรมการความฯ ระยะเวลาการฝึกอบรม 12 ชั่วโมง ประกอบด้วย 3 หมวดวิชา ดังต่อไปนี้\n    (1) หมวดวิชาที่ 1 การบริหารคณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานของสถานประกอบกิจการ (3 ชั่วโมง)\n    (2) หมวดวิชาที่ 2 กฎหมายความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน (3 ชั่วโมง)\n    (3) หมวดวิชาที่ 3 การบริหาร จัดการด้านความปลอดภัยตามบทบาทหน้าที่ของคณะกรรมการความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานของสถานประกอบกิจการ (6 ชั่วโมง)\n    โดยหัวข้อวิชาเป็นไปตามที่ประกาศนี้กำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":255,"law_id":35,"seq":0,"text":"ข้อ 3 ยกเลิกประกาศกระทรวงสาธารณสุข เรื่อง ชื่อหรืออาการสำคัญของโรคจากการประกอบอาชีพ พ.ศ. 2563 (ลงวันที่ 29 ธันวาคม 2563)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":256,"law_id":35,"seq":1,"text":"ข้อ 4 กำหนดให้โรคหรืออาการสำคัญดังต่อไปนี้เป็นโรคจากการประกอบอาชีพ\n(1) โรคหรืออาการที่เกิดจากตะกั่วหรือสารประกอบของตะกั่ว\n(2) โรคหรืออาการที่เกิดจากฝุ่นซิลิกา (รวมถึงโรคซิลิโคสิสและมะเร็งปอด)\n(3) โรคหรืออาการที่เกิดจากภาวะอับอากาศ\n(4) โรคหรืออาการที่เกิดจากแอสเบสตอส (แร่ใยหิน) หรือโรคมะเร็งที่เกิดจากแอสเบสตอส (รวมถึงแอสเบสโตสิส ภาวะเยื่อหุ้มปอดหนากระจาย โรคมะเร็งเยื่อหุ้มปอด และมะเร็งปอด)\n(5) โรคหรืออาการที่เกิดจากพิษจากสารกำจัดศัตรูพืช (กลุ่มออร์กาโนฟอสเฟตหรือคาร์บาเมต, สารพาราควอต, สารไกลโฟเสท, สารเอทอิลีนบิสไดโทโอคาร์บาเมต, กลุ่มเบนซิมิตาโซล)\n(6) โรคหรืออาการที่เกิดจากรังสีแตกตัวหรือจากรังสีชนิดก่อไอออน (รวมถึงอาการผิดปกติเฉียบพลันจากรังสี อาการบาดเจ็บเฉพาะที่จากรังสี และอาการที่เกิดในระยะยาว)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":274,"law_id":39,"seq":0,"text":"มาตรา ๖ พระราชบัญญัตินี้ไม่ใช้บังคับแก่น้ำมันเชื้อเพลิงที่ใช้ในราชการทหารโดยเฉพาะ แต่ให้นำหลักเกณฑ์และวิธีการตามที่กำหนดในพระราชบัญญัตินี้ไปเป็นแนวทางในการดำเนินงาน\n มาตรา ๗ เพื่อประโยชน์แก่การป้องกันหรือระงับเหตุเดือดร้อนรำคาญหรือความเสียหายหรืออันตรายที่จะมีผลกระทบต่อบุคคล สัตว์ พืช ทรัพย์ หรือสิ่งแวดล้อมหรือการกำหนดแนวทางหรือลักษณะการดำเนินการเกี่ยวกับการควบคุมน้ำมันเชื้อเพลิงให้สอดคล้องกับสภาพเศรษฐกิจและสังคม ให้รัฐมนตรีมีอำนาจออกกฎกระทรวงดังต่อไปนี้\n(๑) กำหนดการเก็บรักษา การขนส่ง การใช้ การจำหน่าย การแบ่งบรรจุน้ำมันเชื้อเพลิง และการควบคุมอื่นใดเกี่ยวกับน้ำมันเชื้อเพลิง\n(๒) กำหนดที่ตั้ง แผนผัง รูปแบบ และลักษณะของสถานที่เก็บรักษาน้ำมันเชื้อเพลิง สถานีบริการน้ำมันเชื้อเพลิง และคลังน้ำมันเชื้อเพลิง และการบำรุงรักษาสถานที่ดังกล่าว\n(๓) กำหนดลักษณะของถังหรือภาชนะที่ใช้ในการบรรจุหรือขนส่ง และการบำรุงรักษาถังหรือภาชนะดังกล่าว\n(๔) กำหนดคุณสมบัติและการฝึกอบรมผู้ปฏิบัติงานเกี่ยวกับการควบคุมน้ำมันเชื้อเพลิง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":478,"law_id":96,"seq":4,"text":"จัดทำมาตรการรักษาความมั่นคงปลอดภัยของข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":483,"law_id":101,"seq":0,"text":"กำหนดให้ผู้เกี่ยวข้องลงนามในบันทึกข้อตกลงรักษาความลับ (NDA)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":245,"law_id":29,"seq":0,"text":"(ข้อ 7) หลักสูตรฝึกอบรมด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทํางาน สําหรับลูกจ้างทั่วไป\nและลูกจ้างเข้าทํางานใหม่ มีระยะเวลาการฝึกอบรม 6 ชั่วโมง ประกอบด้วยหัวข้อวิชา\n       (1) ความรู้เกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทํางาน ระยะเวลา 1 ชั่วโมง 30 นาที\n       (2) กฎหมายความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทํางาน ระยะเวลา 1 ชั่วโมง 30 นาที\n       (3) คู่มือว่าด้วยความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทํางานของหน่วยงาน ระยะเวลา 3 ชั่วโมง\n     ลูกจ้างที่ผ่านการอบรมตามวรรคหนึ่งจากสถานประกอบกิจการเดิมแล้ว ให้ฝึกอบรมเฉพาะ (3) เท่านั้น\n(ข้อ 8) หลักสูตรฝึกอบรมด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทํางาน สําหรับลูกจ้างเปลี่ยนงาน เปลี่ยนสถานที่ทํางาน หรือเปลี่ยนแปลงเครื่องจักรหรืออุปกรณ์ซึ่งมีปัจจัยเสี่ยง แตกต่างไปจากเดิม มีระยะเวลา\nการฝึกอบรม 3 ชั่วโมง ประกอบด้วยหัวข้อวิชา\n       (1) ปัจจัยเสี่ยงจากการทํางาน ระยะเวลา 1 ชั่วโมง 30 นาที\n       (2) คู่มือว่าด้วยความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทํางานของหน่วยงาน ระยะเวลา 1 ชั่วโมง 30 นาที\n(ข้อ 10) ผู้ผ่านการฝึกอบรมหลักสูตร จป. หัวหน้างานหรือ จป. บริหาร หรือเป็น จป. บริหารตาม พ.ร.บ. ความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554  ให้ถือว่าผู้นั้นผ่านการฝึกอบรมสำหรับลูกจ้าง\nระดับหัวหน้างานหรือระดับบริหารตามประกาศนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":251,"law_id":33,"seq":0,"text":"ข้อ 3 ยกเลิกมาตราฐานผลิตภัณฑ์อุตสาหกรรม เครื่องดับเพลิงยกหิ้วชนิทคาร์บอนไดออกไซด์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":252,"law_id":33,"seq":1,"text":"ข้อ 4 กำหนดมาตราฐานผลิตภัณฑ์อุตสาหกรรม เครื่องดับเพลิงยกหิ้วชนิทคาร์บอนไดออกไซด์ มาตรฐานเลขที่ มอก.881-2567 ขึ้นใหม่","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":259,"law_id":37,"seq":0,"text":"กำหนดค่ามาตรฐานสารมลพิษทางอากาศ เช่น PM2.5, PM10, SO₂, NO₂, CO, O₃ เพื่อควบคุมคุณภาพอากาศให้อยู่ในระดับปลอดภัยต่อสุขภาพประชาชน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":260,"law_id":37,"seq":1,"text":"ข้อ ๓ ให้นายจ้างจัดให้มีข้อบังคับและคู่มือว่าด้วยความปลอดภัยในการทำงานไว้ในสถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":261,"law_id":37,"seq":2,"text":"ข้อ ๔ ให้นายจ้างซึ่งมีผู้รับเหมาชั้นต้นหรือผู้รับเหมาช่วงเข้ามาปฏิบัติงานในสถานประกอบกิจการ จัดให้มีข้อบังคับและคู่มือตามข้อ ๓","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":262,"law_id":37,"seq":3,"text":"ข้อ ๕ ให้นายจ้างจัดการอบรมลูกจ้างให้มีความรู้เกี่ยวกับข้อบังคับและคู่มือตามข้อ ๓ ก่อนการปฏิบัติงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":263,"law_id":37,"seq":4,"text":"ข้อ ๗ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่ยี่สิบคนขึ้นไป แต่งตั้งลูกจ้างระดับหัวหน้างาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":264,"law_id":37,"seq":5,"text":"ข้อ ๑๖ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่หนึ่งร้อยคนขึ้นไป แต่งตั้งลูกจ้างเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพประจำสถานประกอบกิจการอย่างน้อยหนึ่งคน เพื่อปฏิบัติงานเฉพาะด้านความปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":265,"law_id":37,"seq":6,"text":"ข้อ ๑๙ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่ยี่สิบคนขึ้นไป แต่งตั้งลูกจ้างระดับบริหารทุกคนเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับบริหารของสถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":266,"law_id":37,"seq":7,"text":"ข้อ ๒๓ สถานประกอบกิจการที่มีลูกจ้างตั้งแต่หนึ่งร้อยคนขึ้นไปแต่ไม่ถึงห้าร้อยคน ให้มีกรรมการไม่น้อยกว่าเจ็ดคน ประกอบด้วย นายจ้างหรือผู้แทนนายจ้างระดับบริหาร เป็นประธานกรรมการผู้แทนนายจ้างระดับบังคับบัญชาสองคนและผู้แทนลูกจ้างสามคน เป็นกรรมการ โดยมีเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพ เป็นกรรมการและเลขานุการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":267,"law_id":37,"seq":8,"text":"ข้อ ๓๓ ให้นายจ้างในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่สองร้อยคนขึ้นไป จัดให้มีหน่วยงานความปลอดภัยภายในสามร้อยหกสิบวันนับแต่วันที่กฎกระทรวงนี้มีผลใช้บังคับ หรือภายในสามร้อยหกสิบวันนับแต่วันที่มีลูกจ้างครบสองร้อยคน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":268,"law_id":37,"seq":9,"text":"ข้อ ๓๖ ให้นายจ้างแจ้งชื่อเจ้าหน้าที่ความปลอดภัยในการทำงานตามหมวด ๑ เพื่อขึ้นทะเบียนต่อกรมสวัสดิการและคุ้มครองแรงงาน ตามหลักเกณฑ์และวิธีการที่อธิบดีประกาศกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":269,"law_id":37,"seq":10,"text":"ข้อ ๓๗ ให้นายจ้างส่งรายงานผลการดำเนินงานของเจ้าหน้าที่ความปลอดภัยในการทำงานระดับเทคนิคขั้นสูงและระดับวิชาชีพต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายตามแบบที่อธิบดีประกาศกำหนด ทุกสามเดือนตามปีปฏิทิน ทั้งนี้ ภายในเวลาไม่เกินสามสิบวันนับแต่วันที่ครบกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":479,"law_id":97,"seq":0,"text":"เผยแพร่ข้อมูลให้คนในองค์กรณ์ตะหนักถึงการรับมือภัยคุกคามไซเบอร์\nจัดทำแผนรับมือภัยคุกคามทางไซเบอร์\nจัดทำนโยบายการรักษาความมั่นคงปลอดภัยไซเบอร์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":249,"law_id":32,"seq":1,"text":"ข้อ 3 คุณสมบัติเป็นจป.วิชาชีพที่สำเร็จการศึกษาไม่ต่ำกว่าระดับปริญญาตรี สาขาอาชีวอนามัยและความปลอดภัยหรือเทียบเท่า ต้องสำเร็จการศึกษาในหลักสูตรการศึกษาจากกระทรวงการอุดมการศึกษา วิทยาศาสตร์ วิจัยและนวัตกรรม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":250,"law_id":32,"seq":2,"text":"ข้อ 4  ผู้ที่สำเร็จการศึกษาไม่ต่ำกว่าระดับปริญญาตรี สาขาอาชีวอนามัยและความปลอดภัยหรือเทียบเท่าจากกรมสวัสดิการคุ้มครองแรงงาน ก่อนที่ประกาศนี้มีผลใช้บังคับถือเป็นผู้มีคุณสมบัติตามข้อ 2(1) แห่งกฎกระทรวงการจัดให้มีเจ้าหน้าที่ความปลอดภัยในการทำงาน บุคลากร หน่วยงาน หรือคณะบุคคล เพื่อดำเนินการด้านความปลอดภัยในสถานประกอบกิจการตามข้อบังคับพ.ศ. 2565","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":257,"law_id":36,"seq":0,"text":"ข้อ 3 ยกเลิกประกาศกระทรวงสาธารณสุข เรื่อง ชื่อหรืออาการสำคัญของโรคจากสิ่งแวดล้อม พ.ศ. 2563 (ลงวันที่ 29 ธันวาคม 2563) และ3.\tประกาศกระทรวงสาธารณสุข เรื่อง ชื่อหรืออาการสำคัญของโรคจากสิ่งแวดล้อม (ฉบับที่ 2) พ.ศ. 2565 (ลงวันที่ 7 มีนาคม 2565)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":258,"law_id":36,"seq":1,"text":"ข้อ 2 กำหนดให้โรคหรืออาการสำคัญดังต่อไปนี้เป็นโรคจากสิ่งแวดล้อม\n(1) โรคหรืออาการที่เกิดจากตะกั่วหรือสารประกอบของตะกั่ว โดยมีอาการสำคัญที่แตกต่างกันในบุคคลที่มีอายุต่ำกว่าสิบห้าปีบริบูรณ์ และหญิงตั้งครรภ์\n(2) โรคหรืออาการที่เกิดจากการสัมผัสฝุ่นละอองขนาดไม่เกิน ๒.๕ ไมครอน โดยมีอาการสำคัญเกี่ยวข้องกับระบบทางเดินหายใจ หัวใจ ดวงตา และผิวหนัง\n(3) โรคหรืออาการที่เกิดจากรังสีแตกตัวหรือจากรังสีชนิดก่อไอออน โดยมีอาการผิดปกติเฉียบพลัน อาการบาดเจ็บเฉพาะที่ และอาการที่เกิดในระยะยาว ซึ่งรวมถึงความผิดปกติทางร่างกายหรือทางพันธุกรรมในทารกในครรภ์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":293,"law_id":44,"seq":0,"text":"กำหนดให้สาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ เฉพาะสาขาช่างไฟฟ้าภายในอาคาร เป็นสาขาอาชีพที่อาจเป็นอันตรายต่อสาธารณะ ซึ่งต้องดำเนินการโดยผู้ได้รับหนังสือรับรองความรู้ความสามารถตามกฎหมายว่าด้วยการส่งเสริมการพัฒนาฝีมือแรงงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":509,"law_id":147,"seq":0,"text":"ข้อ 2 ยกเลิกประกาศกรมสวัสดิการและคุ้มครองแรงงาน เรื่อง สัญลักษณ์เตือนอันตราย เครื่องหมายเกี่ยวกับความปลอดภัยฯ และข้อความแสดงสิทธิและหน้าที่ของนายจ้างและลูกจ้าง พ.ศ. 2554","status":"met","responsible":"Safety","frequency":"ปีละ 1 ครั้ง และเมื่อกฎหมายเปลี่ยนแปลง","documents":"- แสดงไว้ในคู่มือความปลอดภัย\n- ไซต์สื่อสาร Jastel Safety\n- ไฟล์อบรมอบรมความปลอดภัย","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":510,"law_id":147,"seq":1,"text":"ข้อ 3 นายจ้างต้องติดประกาศข้อความแสดงสิทธิและหน้าที่ของนายจ้างและลูกจ้างด้านความปลอดภัยฯ ในที่ที่เห็นได้ง่าย ณ สถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":378,"law_id":83,"seq":0,"text":"1. นายจ้างต้องจัดให้มีอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่เหมาะสมกับงานนั่งร้านและค้ำยัน  และดูแลให้ลูกจ้าง\nสวมใส่ตลอดระยะเวลาที่ลูกจ้างทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":253,"law_id":34,"seq":0,"text":"ข้อ ๓ การกำหนดแบบฟอร์มการแจ้งและรายงาน\nกำหนดให้ใช้ แบบฟอร์มตามที่แนบท้ายประกาศ สำหรับการดำเนินงานในแต่ละขั้นตอน ได้แก่\n1.แบบการรับแจ้งของพนักงานเจ้าหน้าที่ (ใช้บันทึกข้อมูลที่ได้รับจากนายจ้าง) แบบฟอร์ม บจ ๓๐/๑ บจ ๓๐/๒ หรือ บจ ๓๐/๓\n2.แบบการแจ้งของผู้รับผิดชอบในสถานพยาบาล (ใช้สำหรับแจ้งข้อมูลต่อพนักงานเจ้าหน้าที่)\n3.แบบการรายงานของพนักงานเจ้าหน้าที่ \nใช้รายงานข้อมูลต่อกรมควบคุมโรค และคณะกรรมการควบคุมโรคจากการประกอบอาชีพและโรคจากสิ่งแวดล้อมจังหวัดหรือกรุงเทพมหานคร แบบฟอร์ม บร ๓๑/๑\nแบบทั้งหมดต้องเป็นไปตามรูปแบบที่แนบท้ายประกาศ เพื่อให้เป็นมาตรฐานเดียวกันทั่วประเทศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":254,"law_id":34,"seq":1,"text":"ข้อ ๔ วิธีการแจ้งและรายงานข้อมูล\nนายจ้าง, ผู้รับผิดชอบในสถานพยาบาล และพนักงานเจ้าหน้าที่สามารถแจ้งหรือรายงานข้อมูลได้โดยวิธีการทางอิเล็กทรอนิกส์หรือ ช่องทางดิจิทัล โปรแกรม หรือแอปพลิเคชันช่องทางเหล่านี้ต้องเป็น ระบบที่จัดทำหรือควบคุมโดยกรมควบคุมโรค กระทรวงสาธารณสุข","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":278,"law_id":42,"seq":0,"text":"(๒) ลักษณะที่สอง ได้แก่ สถานที่เก็บน้ํามันชนิดใดชนิดหนึ่งหรือหลายชนิด ดังต่อไปนี้\n (ก) สถานที่เก็บน้ํามันชนิดไวไฟมากที่มีปริมาณเกิน ๔๐ ลิตร แต่ไม่เกิน ๔๕๔ ลิตร\n (ข) สถานที่เก็บน้ํามันชนิดไวไฟปานกลางที่มีปริมาณเกิน ๒๒๗ ลิตร แต่ไม่เกิน ๑,๐๐๐ ลิตร\n (ค) สถานที่เก็บน้ํามันชนิดไวไฟน้อยที่มีปริมาณเกิน ๔๕๔ ลิตร แต่ไม่เกิน ๑๕,๐๐๐ ลิตร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":297,"law_id":46,"seq":0,"text":"เพิ่มความต่อไปนี้เป็นวรรค 4 ของข้อ 2 แห่งประกาศกรมสวัสดิการและคุ้มครองแรงงานเรื่อง หลักเกณฑ์ \nวิธีการ และเงื่อนไขการฝึกอบรมความปลอดภัยในการทำงานเกี่ยวกับไฟฟ้าสำหรับลูกจ้าง ซึ่งปฏิบัติงานเกี่ยวกับ ไฟฟ้า ลงวันที่ 24 ธันวาคม พ.ศ. 2558\n      “ในกรณีที่ลูกจ้างได้รับหนังสือรับรองความรู้ความสามารถ สาขาช่างไฟฟ้าภายในอาคารของกรมพัฒนาฝีมือแรงงาน ให้ถือว่าเป็นผู้ที่ผ่านการฝึกอบรมความปลอดภัยในการทำงานเกี่ยวกับไฟฟ้าตามประกาศฉบับนี้”","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":511,"law_id":147,"seq":2,"text":"ข้อ 4 นายจ้างต้องติดประกาศสัญลักษณ์เตือนอันตรายและเครื่องหมายเกี่ยวกับความปลอดภัยฯ ให้เหมาะสมกับลักษณะและสภาพการทำงาน ในที่ที่เห็นได้ง่าย","status":"met","responsible":null,"frequency":"1 ครั้ง/เดือน หรือพบว่าชำรุด ซีดจาง ถูกบัง หรือไม่ตรงกับความเสี่ยง","documents":"แบบตรวจสอบความปลอดภัย","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":512,"law_id":147,"seq":3,"text":"ข้อ 5 สัญลักษณ์เตือนอันตรายและเครื่องหมายความปลอดภัยต้องเป็นไปตามมาตรฐานผลิตภัณฑ์อุตสาหกรรม หรือมาตรฐานสากล เช่น ISO, EN, AS/NZS, ANSI, JIS, NIOSH, OSHA, KSA หรือมาตรฐานอื่นที่เทียบเท่า","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":273,"law_id":38,"seq":0,"text":"กำหนดให้โรคหรืออาการสำคัญดังต่อไปนี้เป็นโรคจากสิ่งแวดล้อม เพื่อประโยชน์ในการเฝ้าระวัง ป้องกันและควบคุมโรคจากสิ่งแวดล้อม \n     1. โรคจากตะกั่วหรือสารประกอบของตะกั่ว \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":271,"law_id":37,"seq":12,"text":"ข้อ ๔๐ นายจ้างต้องจัดทำสำเนาบันทึก รายงานการดำเนินงาน หรือรายงานการประชุมเกี่ยวกับการดำเนินการของคณะกรรมการและหน่วยงานความปลอดภัย เก็บไว้ในสถานประกอบกิจการเป็นเวลาไม่น้อยกว่าสองปีนับแต่วันจัดทำ และพร้อมที่จะให้พนักงานตรวจแรงงานตรวจสอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":272,"law_id":37,"seq":13,"text":"ข้อ ๔๑ ให้นายจ้างส่งสำเนารายชื่อคณะกรรมการและหน้าที่รับผิดชอบตามข้อ ๓๒ ต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายภายในสิบห้าวันนับแต่วันที่แต่งตั้งหรือเปลี่ยนแปลงกรรมการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":294,"law_id":45,"seq":0,"text":"ข้อ ๒ การจัดฝึกอบรมให้กับลูกจ้างซึ่งปฏิบัติงานเกี่ยวกับไฟฟ้าเข้ารับการฝึกอบรมความปลอดภัยในการทำงานเกี่ยวกับไฟฟ้า ให้นายจ้างจัดทำทะเบียนรายชื่อผู้ที่ผ่านการฝึกอบรม วัน เวลาที่ฝึกอบรมพร้อมรายชื่อวิทยากรเก็บไว้ ณ สถานประกอบกิจการ และให้แจ้งทะเบียนรายชื่อผู้ที่ผ่านการฝึกอบรม วัน เวลาที่ฝึกอบรมพร้อมรายชื่อวิทยากรต่อพนักงานตรวจความปลอดภัยในเขตพื้นที่รับผิดชอบภายในสิบห้าวันนับแต่วันที่เสร็จสิ้นการฝึกอบรม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":295,"law_id":45,"seq":1,"text":"ข้อ ๓ การฝึกอบรมความปลอดภัยในการทำงานเกี่ยวกับไฟฟ้าให้กับลูกจ้างซึ่งปฏิบัติงานเกี่ยวกับไฟฟ้า ต้องมีระยะเวลาการฝึกอบรมไม่น้อยกว่าสามชั่วโมง และอย่างน้อยต้องมีหัวข้อวิชาตามกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":296,"law_id":45,"seq":2,"text":"ข้อ ๕ วิทยากรผู้ทำการฝึกอบรมความปลอดภัยในการทำงานเกี่ยวกับไฟฟ้า ต้องมีคุณสมบัติตามกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":277,"law_id":41,"seq":0,"text":"ใช้บังคับตั้งแต่วันที่ 16 มกราคม 2556 เป็นต้นไป  \n   กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรมเต้าเสียบและเต้ารับสำหรับใช้ในที่อยู่อาศัยและงานทั่วไปที่มีจุดประสงค์คล้ายกัน : เต้าปรับ มาตรฐานเลขที่ มอก. 2431 – 2555 ไว้ ดังนี้\n     1. ขอบข่าย\n     ครอบคลุมเต้าปรับมีตัวปิดช่อง เต้าปรับไม่มีตัวปิดช่อง เต้าปรับมีฟิวส์ และเต้าปรับไม่มีฟิวส์ ทั้งชนิดที่มีและไม่มีขั้วสายดิน และใช้สำหรับไฟฟ้ากระแสสลับที่มีแรงดันไฟฟ้าที่กำหนดเกิน 250 โวลต์ และมีกระแสไฟฟ้าที่กำหนดไม่เกิน 16 แอมแปร์ เหมาะสำหรับใช้ในที่มีอุณหภูมิโดยรอบตามปกติไม่เกิน 40oC\n     ไม่ครอบคลุมถึงเต้าปรับสำหรับแรงดันไฟฟ้าต่ำพิเศษ\nโดยมีการกำหนดเกี่ยวกับ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":275,"law_id":39,"seq":1,"text":"หมวด ๓\nการประกอบกิจการควบคุม\nมาตรา ๑๗ เพื่อให้การควบคุมการประกอบกิจการเป็นไปอย่างมีประสิทธิภาพและเพื่อปกป้องประชาชน\nให้มีความปลอดภัย ให้รัฐมนตรีมีอำนาจออกกฎกระทรวงกำหนดประเภทกิจการควบคุมของการมีน้ำมันเชื้อเพลิง\nไว้ในครอบครอง สถานีบริการน้ำมันเชื้อเพลิง คลังน้ำมันเชื้อเพลิงและการขนส่งน้ำมันเชื้อเพลิง สำหรับน้ำมัน\nเชื้อเพลิงชนิดใดชนิดหนึ่ง หรือทุกชนิดรวมกัน ให้สอดคล้องกับระดับอันตรายที่อาจจะเกิดขึ้น โดยแบ่งเป็น ๓\nประเภท ดังนี้\n(๑) ประเภทที่ ๑ ได้แก่กิจการที่สามารถประกอบการได้ทันทีตามความประสงค์ของผู้ประกอบกิจการ\n(๒) ประเภทที่ ๒ ได้แก่กิจการที่เมื่อจะประกอบการต้องแจ้งให้พนักงานเจ้าหน้าที่ทราบก่อน\n(๓) ประเภทที่ ๓ ได้แก่กิจการที่ต้องได้รับใบอนุญาตจากผู้อนุญาตก่อนจึงจะประกอบการได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":279,"law_id":43,"seq":0,"text":"ข้อ ๓ ให้นายจ้างจัดให้มีข้อบังคับเกี่ยวกับการปฏิบัติงานด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานเกี่ยวกับไฟฟ้า โดยให้มีมาตรฐานไม่ต่ำกว่าที่กำหนดไว้ในกฎกระทรวงนี้เพื่อให้ลูกจ้างปฏิบัติตาม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":280,"law_id":43,"seq":1,"text":"ข้อ ๔ ให้นายจ้างจัดให้มีการฝึกอบรมให้กับลูกจ้างซึ่งปฏิบัติงานเกี่ยวกับไฟฟ้าให้มีความรู้ความเข้าใจ และทักษะที่จำเป็นในการทำงานอย่างปลอดภัยตามหน้าที่ที่ได้รับมอบหมาย ทั้งนี้ตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่อธิบดีประกาศกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":281,"law_id":43,"seq":2,"text":"ข้อ ๕ ให้นายจ้างจัดให้มีและเก็บรักษาแผนผังวงจรไฟฟ้าที่ติดตั้งภายในสถานประกอบกิจการทั้งหมดซึ่งได้รับการรับรองจากวิศวกรหรือการไฟฟ้าประจำ ท้องถิ่นไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบ หากมีการแก้ไขเพิ่มเติมหรือเปลี่ยนแปลงไปจากเดิมต้องดำเนินการแก้ไขแผนผังนั้นให้ถูกต้อง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":282,"law_id":43,"seq":3,"text":"ข้อ ๖ ให้นายจ้างจัดให้มีแผ่นป้ายที่มีตัวอักษรหรือสัญลักษณ์เตือนให้ระวังอันตรายจากไฟฟ้าที่มองเห็นได้ชัดเจนติดตั้งไว้โดยเปิดเผยในบริเวณที่อาจเกิดอันตรายจากกระแสไฟฟ้า ทั้งนี้ให้เป็นไปตามแบบที่กำหนดไว้ในมาตรฐานผลิตภัณฑ์อุตสาหกรรมหรือมาตรฐานอื่นตามที่อธิบดีประกาศกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":283,"law_id":43,"seq":4,"text":"ข้อ ๗ ห้ามนายจ้างให้ลูกจ้างซึ่งปฏิบัติงานเกี่ยวกับไฟฟ้าเข้าใกล้หรือนำสิ่งที่เป็นตัวนำไฟฟ้าที่ไม่มีที่ถือหุ้มด้วยฉนวนไฟฟ้าที่เหมาะสมกับแรงดันไฟฟ้าเข้าใกล้สิ่งที่มีกระแสไฟฟ้าในระยะที่น้อยกว่าระยะห่างตามมาตรฐานของสมาคมวิศวกรรมสถานแห่งประเทศไทย ในพระบรมราชูปถัมภ์ หากยังไม่มีมาตรฐานดังกล่าวให้ใช้มาตรฐานตามที่การไฟฟ้าประจำท้องถิ่นกำหนด เว้นแต่นายจ้างจะได้ดำเนินการดังต่อไปนี้\n(๑) ให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่เป็นฉนวนไฟฟ้าที่เหมาะสมกับแรงดันไฟฟ้า หรือนำฉนวนไฟฟ้าที่สามารถป้องกันแรงดันไฟฟ้านั้นได้มาหุ้มสิ่งที่มีกระแสไฟฟ้า และ\n(๒) จัดให้มีวิศวกร หรือกรณีการไฟฟ้าประจำท้องถิ่นอาจจัดให้ผู้ที่ได้รับการรับรองเป็นผู้ควบคุมงานจากการไฟฟ้าประจำท้องถิ่นดังกล่าว เพื่อควบคุมการปฏิบัติงานของลูกจ้าง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":284,"law_id":43,"seq":5,"text":"ข้อ ๙ ให้นายจ้างดูแลมิให้ลูกจ้างสวมใส่เครื่องนุ่งห่มที่เปียกหรือเป็นสื่อไฟฟ้าปฏิบัติงานเกี่ยวกับสิ่งที่มีกระแสไฟฟ้าที่มีแรงดันไฟฟ้าเกินกว่าห้าสิบโวลต์ โดยไม่มีฉนวนไฟฟ้าปิดกั้น เว้นแต่นายจ้างจะได้จัดให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลหรือใช้อุปกรณ์ป้องกันอันตรายที่เหมาะสมกับแรงดันไฟฟ้าสำหรับการปฏิบัติงานของลูกจ้าง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":285,"law_id":43,"seq":6,"text":"ข้อ ๑๐ ในกรณีที่นายจ้างให้ลูกจ้างทำงานโดยใช้อุปกรณ์ในการปฏิบัติงานเกี่ยวกับกระแสไฟฟ้า หรืออยู่ในบริเวณใกล้เคียงกับสิ่งที่มีกระแสไฟฟ้า ให้นายจ้างจัดหาอุปกรณ์ชนิดที่เป็นฉนวนไฟฟ้า หรือหุ้มด้วยฉนวนไฟฟ้า หรืออุปกรณ์ป้องกันอันตรายที่เหมาะสมกับแรงดันไฟฟ้าสำหรับการปฏิบัติงานของลูกจ้าง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":286,"law_id":43,"seq":7,"text":"ข้อ ๑๑ ให้นายจ้างดูแลบริภัณฑ์ไฟฟ้าและสายไฟฟ้าให้ใช้งานได้โดยปลอดภัย หากพบว่าชำรุด หรือมีกระแสไฟฟ้ารั่ว หรืออาจก่อให้เกิดอันตรายแก่ผู้ใช้งาน ให้ซ่อมแซมหรือดำเนินการให้อยู่ในสภาพที่ใช้งานได้อย่างปลอดภัย และจัดให้มีหลักฐานในการดำเนินการเพื่อให้พนักงานตรวจความปลอดภัยตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":305,"law_id":54,"seq":0,"text":"ข้อ 2 ยกเลิกประกาศกรมฯ เรื่องประกาศกรมสวัสดิการและคุ้มครองแรงงาน เรื่อง หลักเกณฑ์ วิธีการ และเงื่อนไขการจัดทำบันทึกผลการตรวจสอบและรับรองระบบไฟฟ้าและบริภัณฑ์ไฟฟ้า พ.ศ.2558","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":287,"law_id":43,"seq":8,"text":"ข้อ ๑๒ นายจ้างต้องจัดให้มีการตรวจสอบและจัดให้มีการบำรุงรักษาระบบไฟฟ้าและบริภัณฑ์ไฟฟ้าเพื่อให้ใช้งานได้อย่างปลอดภัย และให้บุคคลที่ขึ้นทะเบียนตามมาตรา ๙ หรือนิติบุคคลที่ได้รับใบอนุญาตตามมาตรา ๑๑ แห่งพระราชบัญญัติความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. ๒๕๕๔ แล้วแต่กรณี เป็นผู้จัดทำบันทึกผลการตรวจสอบและรับรองไว้ เพื่อให้พนักงานตรวจความปลอดภัยตรวจสอบ ทั้งนี้ ตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่อธิบดีประกาศกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":288,"law_id":43,"seq":9,"text":"ข้อ ๑๓ ให้นายจ้างจัดให้มีแผ่นภาพพร้อมคำบรรยายติดไว้ในบริเวณที่ทำงานที่ลูกจ้างสามารถมองเห็นได้ชัดเจนในเรื่อง ดังต่อไปนี้\n(๑) วิธีปฏิบัติเมื่อประสบอันตรายจากไฟฟ้า\n(๒) วิธีปฏิบัติเมื่อประสบอันตรายจากไฟฟ้าโดยการผายปอดด้วยวิธีปากเป่าอากาศเข้าทางปากหรือจมูกของผู้ประสบอันตราย และวิธีการนวดหัวใจจากภายนอก","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":289,"law_id":43,"seq":10,"text":"ข้อ ๑๙. การใช้เครื่องกำเนิดไฟฟ้า ให้นายจ้างปฏิบัติ ดังต่อไปนี้\n(1) ติดตั้งในบริเวณพื้นที่กว้างพอที่จะปฏิบัติงานได้\n(2) จัดให้มีการระบายอากาศอย่างเพียงพอ กรณีติดตั้งเครื่องกำเนิดไฟฟ้าภายในห้องหากมีไอเสียจากเครื่องยนต์ให้ต่อท่อไอเสียออกสู่ภายนอก\n(3) จัดให้มีเครื่องป้องกันกระแสไฟฟ้าไหลเกิน\n(4) จัดให้มีเครื่องดับเพลิงชนิดที่ใช้ดับเพลิงที่เกิดจากไฟฟ้าและน้ำมันอย่างเพียงพอ \n(5) ในกรณีที่มีเครื่องกำเนิดไฟฟ้าสำรอง ต้องจัดให้มีเครื่องป้องกันการใช้ผิดหรือสวิตซ์สับโยกสองทาง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":290,"law_id":43,"seq":11,"text":"ข้อ ๒๑ ให้นายจ้างจัดอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่เหมาะสมกับลักษณะงาน เช่น ถุงมือหนัง ถุงมือยาง แขนเสื้อยาง หมวกนิรภัย รองเท้าพื้นยางหุ้มข้อชนิดมีส้นหรือรองเท้าพื้นยางหุ้มส้น ให้ลูกจ้างซึ่งปฏิบัติงานเกี่ยวกับไฟฟ้าสวมใส่ตลอดเวลาที่ปฏิบัติงานและจัดให้มีอุปกรณ์ป้องกันอันตรายจากไฟฟ้าที่เหมาะสมกับลักษณะงาน เช่น แผ่นฉนวนไฟฟ้า ฉนวนหุ้มสาย ฉนวนครอบลูกถ้วย กรงฟาราเดย์ (Faraday Cage) ชุดตัวนำไฟฟ้า (Conductive Suit) ในกรณีที่ลูกจ้างต้องปฏิบัติงานในที่สูงกว่าพื้นตั้งแต่สี่เมตรขึ้นไป ให้นายจ้างจัดให้มีการใช้สายหรือเชือกช่วยชีวิตและเข็มขัดนิรภัยพร้อมอุปกรณ์ หรืออุปกรณ์ที่ป้องกันการตกจากที่สูงได้อย่างมีประสิทธิภาพ และหมวกนิรภัยที่เหมาะสมตามมาตรฐานที่กำหนดสำหรับให้ลูกจ้างสวมใส่ตลอดเวลาที่ปฏิบัติงาน เว้นแต่อุปกรณ์ดังกล่าวจะทำให้ลูกจ้างเสี่ยงต่ออันตรายมากขึ้น ให้นายจ้างจัดให้มีอุปกรณ์เพื่อความปลอดภัยอื่นที่สามารถใช้คุ้มครองความปลอดภัยได้อย่างมีประสิทธิภาพแทน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":291,"law_id":43,"seq":12,"text":"ข้อ ๒๒ อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลและอุปกรณ์ป้องกันอันตรายจากไฟฟ้าต้องเป็นไปตามมาตรฐานที่กำหนดไว้และต้องมีคุณสมบัติ ดังต่อไปนี้\n(๑) อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลและอุปกรณ์ที่ใช้ป้องกันกระแสไฟฟ้าต้องเหมาะสมกับแรงดันไฟฟ้าสูงสุดในบริเวณที่ปฏิบัติงานหรือบริเวณใกล้เคียงที่อาจก่อให้เกิดอันตรายได้\n(๒) ถุงมือยางป้องกันไฟฟ้า ต้องมีลักษณะสวมกับนิ้วมือได้ทุกนิ้ว\n(๓) ถุงมือหนังที่ใช้สวมทับถุงมือยาง ต้องมีความยาวหุ้มถึงข้อมือและมีความคงทนต่อการฉีกขาดได้ดี การใช้ถุงมือยางต้องใช้ร่วมกับถุงมือหนังทุกครั้งที่ปฏิบัติงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":292,"law_id":43,"seq":13,"text":"ข้อ ๒๔ นายจ้างต้องบำรุงรักษาและจัดเก็บอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลและอุปกรณ์ป้องกันอันตรายจากไฟฟ้าให้อยู่ในสภาพที่ใช้งานได้อย่างปลอดภัย รวมทั้งต้องตรวจสอบและทดสอบตามมาตรฐานและวิธีที่ผู้ผลิตกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":298,"law_id":47,"seq":0,"text":"ผู้ที่มีเครื่องกำเนิดไฟฟ้าซึ่งมีกำลังผลิตรวมตั้งแต่ 200กิโลโวลต์แอมแปร์ขึ้นไป อยู่ในครอบครอง เพื่อทำการผลิตไฟฟ้า จะต้อง ขออนุญาต ทำการผลิตพลังงานควบคุม ต่อ กรมพัฒนาและส่งเสริมพลังงาน \n\n\nผู้ยื่นคำขอทำหน้าที่ผู้ตรวจสอบระบบผลิตพลังงานควบคุม สามารถยื่นคำขอผ่านช่องทางอิเล็กทรอนิกส์ (http://eaudit.dede.go.th) ได้ตั้งแต่วันที่ 28 ตุลาคม พ.ศ. 2565 เป็นต้นไป จนถึงวันที่ 30 พฤศจิกายน พ.ศ. 2565)\n-ประกาศกรมพัฒนาพลังงานทดแทนและอนุรักษ์พลังงาน เรื่อง การรับขึ้นทะเบียนผู้ตรวจสอบระบบผลิตพลังงานควบคุม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":299,"law_id":48,"seq":0,"text":"- กำหนดวิธี ระเบียบปฏิบัติในการขออนุญาตพาดสาย\nข้อ 14 ผู้ควบคุมงานและผู้ปฏิบัติงานเกี่ยวกับสายสื่อสารที่ได้รับอนุญาตต้องผ่านการอบรม และทบทวนแนวทางการปฏิบัติจากการไฟฟ้านครหลวงทุก ๒ ปี\nข้อ 15 ผู้ควบคุมงานและผู้ปฏิบัติงานเกี่ยวกับสายสื่อสาร ต้องแสดงบัตรหรือวุฒิบัตร และสำเนาWork Permit ให้เจ้าหน้าที่ของการไฟฟ้านครหลวงตรวจสอบ\n- หมวด 7 ข้อ 13 (4) ผู้ควบคุมงานและผู้ปฏิบัติงานเกี่ยวกับสายสื่อสารที่ไม่มีวุฒิบัตร หรือบัตรผ่านการอบรมตามหมวด ๔ ข้อ๘ (๑๔) การไฟฟ้านครหลวงจะคิดเบี้ยปรับ ๑๐,๐๐๐ บาทต่อคน และสั่งหยุดการปฏิบัติงานบนเสาไฟฟ้าทันที","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":300,"law_id":49,"seq":0,"text":"กำหนดวิธี ระเบียบปฏิบัติในการขออนุญาตพาดสาย\n-ข้อ 10.20 ในระหว่างปฏิบัติงาน ผู้ขออนุญาตต้องมีผู้ควบคุมงานที่ได้รับบัตร อนุญาตทํางานบนเสาไฟฟ้า จากการไฟฟ้าส่วนภูมิภาค พร้อมมีสําเนาใบอนุญาตให้ปฏิบัติงาน Work Pemit ให้เจ้าหน้าที่ของการไฟฟ้าส่วนภูมิภาคตรวจสอบตลอดเวลาทีปฏิบัติงาน\n-ข้อ 14 กําหนดโทษ 14.1 ผู้ควบคุมงานที่ไม่มีบัตรอนุญาตทํางานบนเสาไฟฟ้าของการไฟฟ้าส่วนภูมิภาค หรือไม่สามารถนํามาแสดงให้เจ้าหน้าที่การไฟฟ้าส่วนภูมิภาคตรวจสอบในขณะที่ปฏิบัติงาน หรือไม่ สามารถแสดงสําเนาใบอนุญาต (Work Permit) ให้ปฏิบัติงานได้ เจ้าหน้าที่การไฟฟ้าส่วนภูมิภาค จะสังหยุดงานทันที จนกว่าผู้ขออนุญาตจะปฏิบัติตามข้อ ๑๐.๒๐ ครบถ้วน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":301,"law_id":50,"seq":0,"text":"1. มาตรฐานฝีมือแรงงานแห่งชาติ  สาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ สาขาช่างไฟฟ้าภายในอาคาร ระดับ 1 \n      1.1  อายุไม่ต่ำกว่า 18 ปีบริบูรณ์นับถึงวันสมัครเข้ารับการทดสอบ และ\n      1.2  มีประสบการณ์การทำงานหรือประกอบอาชีพเกี่ยวกับสาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์      สาขาช่างไฟฟ้าภายในอาคารไม่น้อยกว่า 1 ปี หรือ\n     1.3  ผ่านการฝึกอบรมฝีมือแรงงานหรือฝึกอาชีพ ในสาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ \n           สาขาช่างไฟฟ้าภายในอาคารไม่น้อยกว่า 60 ชั่วโมง และมีประสบการณ์ฝึกงานหรือปฏิบัติงานในสาขา\n           ช่างไฟฟ้าภายในอาคารไม่น้อยกว่า 160 ชั่วโมง หรือ \n     1.4  จบการศึกษาไม่ต่ำกว่าระดับประกาศนียบัตรวิชาชีพ ในสาขาที่เกี่ยวข้องกับอาชีพนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":304,"law_id":53,"seq":0,"text":"เพิ่มช่องทางการขออนุญาตตามกฎหมายว่าด้วยการควบคุมน้ำมันเชื้อเพลิงโดยวิธีการทางอิเล็กทรอนิกส์  ผ่านเว็บไซต์https://safety.doeb.go.th \n(เดิม : ยื่นเอกสารกับหน่วยงานท้องถิ่นตามที่ตั้งของสถานประกอบกิจการ)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":755,"law_id":89,"seq":6,"text":"7.  ต้องจัดให้มีผู้ควบคุมงานที่ผ่านการอบรมความปลอดภัยในการทำงานในที่อับอากาศ ประจำในพื้นที่ทำงานตลอดเวลาเพื่อทำหน้าที่ที่กำหนดในกฎกระทรวงนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":313,"law_id":56,"seq":0,"text":"“ให้ทำการทดสอบและตรวจสอบถังเมื่อใช้งานครบหนึ่งปีและสิบปี ตามวิธีการที่กำหนดในกฎกระทรวงว่าด้วยการซ่อมบำรุงถังเก็บน้ำมันและถังขนส่งน้ำมัน”\n“ข้อ ๖๖ ถังเก็บน้ำมันเชื้อเพลิงเหนือพื้นดินขนาดใหญ่ตามแนวตั้ง เมื่อใช้งานครบหนึ่งปีและสิบปีต้องทำการทดสอบและตรวจสอบตามวิธีการที่กำหนดในกฎกระทรวงว่าด้วยการซ่อมบำรุงถังเก็บน้ำมันและถังขนส่งน้ำมัน”\n“ข้อ ๘๑ ระบบท่อน้ำมันเชื้อเพลิงและอุปกรณ์ เมื่อใช้งานครบหนึ่งปีและสิบปี ต้องทำการทดสอบและตรวจสอบตามวิธีการที่กำหนดในกฎกระทรวงว่าด้วยการซ่อมบำรุงถังเก็บน้ำมันและถังขนส่งน้ำมัน”","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":322,"law_id":60,"seq":0,"text":"ข้อ ๒ ให้นายจ้างจัดให้มีระบบป้องกันและระงับอัคคีภัยในสถานประกอบกิจการตามกฎกระทรวงนี้ และต้องดูแลระบบป้องกันและระงับอัคคีภัยให้อยู่ในสภาพพร้อมใช้งานได้อย่างมีประสิทธิภาพและปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":323,"law_id":60,"seq":1,"text":"ข้อ ๓ ในสถานประกอบกิจการทุกแห่ง ให้นายจ้างจัดทำป้ายข้อปฏิบัติเกี่ยวกับการดับเพลิงและการอพยพหนีไฟ และปิดประกาศให้เห็นได้อย่างชัดเจน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":324,"law_id":60,"seq":2,"text":"ข้อ ๔ ในสถานประกอบกิจการที่มีลูกจ้างตั้งแต่สิบคนขึ้นไป นอกจากต้องปฏิบัติตามข้อ ๓ แล้วให้นายจ้างจัดให้มีแผนป้องกันและระงับอัคคีภัย ประกอบด้วยการตรวจตรา การอบรม การรณรงค์ป้องกันอัคคีภัย การดับเพลิง การอพยพหนีไฟ และการบรรเทาทุกข์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":325,"law_id":60,"seq":3,"text":"ข้อ ๕ อาคารที่มีสถานประกอบกิจการหลายแห่งตั้งอยู่รวมกัน ให้นายจ้างทุกรายของสถานประกอบกิจการในอาคารนั้นมีหน้าที่ร่วมกันในการจัดให้มีระบบป้องกันและระงับอัคคีภัย รวมทั้งแผนป้องกันและระงับอัคคีภัยด้วย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":326,"law_id":60,"seq":4,"text":"ข้อ ๖ ในกรณีที่นายจ้างสั่งให้ลูกจ้างทำงานที่มีลักษณะงานหรือไปทำงาน ณ สถานที่ที่เสี่ยงหรืออาจเสี่ยงต่อการเกิดอัคคีภัย ให้นายจ้างแจ้ง\nข้อปฏิบัติเกี่ยวกับความปลอดภัยในการทำงานให้ลูกจ้างทราบก่อนการปฏิบัติงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":327,"law_id":60,"seq":5,"text":"ข้อ ๘ ให้นายจ้างจัดให้มีเส้นทางหนีไฟทุกชั้นของอาคารอย่างน้อยชั้นละสองเส้นทางซึ่งสามารถอพยพลูกจ้างที่ทำงานในเวลาเดียวกันทั้งหมดสู่จุดที่ปลอดภัยได้โดยปลอดภัยภายในเวลาไม่เกินห้านาที\n เส้นทางหนีไฟจากจุดที่ลูกจ้างทำงานไปสู่จุดที่ปลอดภัยต้องปราศจากสิ่งกีดขวาง\n ประตูที่ใช้ในเส้นทางหนีไฟต้องทำด้วยวัสดุทนไฟ ไม่มีธรณีประตูหรือขอบกั้น และเป็นชนิดที่บานประตูเปิดออกไปตามทิศทางของการหนีไฟกับต้องติดอุปกรณ์ที่บังคับให้บานประตูปิดได้เอง ห้ามใช้ประตูเลื่อน ประตูม้วน หรือประตูหมุน และห้ามปิดตาย ใส่กลอน กุญแจ ผูก ล่ามโซ่ หรือทำให้เปิดออกไม่ได้ในขณะที่มีลูกจ้างทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":303,"law_id":52,"seq":0,"text":"หมวด 3 สถานที่เก็บรักษาน้ำมัน ลักษณะที่สอง\nส่วนที่ 1 การเก็บน้ำมันและระยะปลอดภัยภายใน\n8. (ข้อ 14-15) การเก็บภาชนะบรรจุน้ำมันไว้ในอาคาร ต้องมีระยะปลอดภัยตามตารางที่ 1 กรณีเก็บไว้นอกอาคารต้องเป็นไปตามตารางที่ 2 \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":306,"law_id":54,"seq":1,"text":"ข้อ 3 กรณีนายจ้างได้ดำเนินการตรวจสอบและรับรองระบบไฟฟ้าและบริภัณฑ์ไฟฟ้าตามกฎหมายว่าด้วยโรงงานหรือกฎหมายว่าด้วยการควบคุมอาคารแล้ว ให้ถือว่าเป็นการตรวจสอบและรับรองระบบไฟฟ้าและบริภัณฑ์ไฟฟ้าตามประกาศฉบับนี้ ​ (แบบฟอร์มเปลี่ยนใหม่)​","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":307,"law_id":54,"seq":2,"text":"ข้อ 4  เปลี่ยนแปลงวันแจ้งบันทึกผลการตรวจสอบและรับรองระบบไฟฟ้าและบริภัณฑ์ไฟฟ้าต่อสวัสดิการและคุ้มครองแรงงานจังหวัด จากภานใน 15 วันเป็นภายใน 30 วัน นับแต่วันที่ได้ทำการตรวจสอบ ทาง e-Service ของกรมสวัสดิการและคุ้มครองแรงงานเป็นหลัก​","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":315,"law_id":58,"seq":0,"text":"9. เครื่องดับเพลิงแบบมือถือที่ติดตั้งแต่ละเครื่องต้องมีระยะห่างกันไม่เกิน 20 เมตรและให้ส่วนบนสุดอยู่สูงจากพื้นไม่เกิน 1.50 เมตร มีป้ายหรือสัญลักษณ์ที่มองเห็นได้ชัดเจน ไม่มีสิ่งกีดขวาง และต้องสามารถนำมาใช้งานได้สะดวก (ปก.มท 1-1.4 ม.)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":316,"law_id":58,"seq":1,"text":"10. ผู้ประกอบกิจการโรงงานต้องจัดเตรียมน้ำสำหรับดับเพลิงในปริมาณที่เพียงพอ\nที่จะส่งจ่ายน้ำให้กับอุปกรณ์ฉีดน้ำดับเพลิงได้อย่างต่อเนื่องเป็นเวลาไม่น้อยกว่า 30 นาที","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":317,"law_id":58,"seq":2,"text":"22. โรงงานต้องจัดเส้นทางหนีไฟที่อพยพคนงานทั้งหมดออกจากบริเวณที่ทำงานสู่บริเวณที่ปลอดภัย เช่น ถนนหรือสนามนอกอาคารโรงงานได้ภายใน 5 นาที","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":318,"law_id":58,"seq":3,"text":"23. การจัดเก็บวัตถุสิ่งของที่ติดไฟได้ หากเป็นการเก็บกองวัตถุมิได้เก็บในชั้นวางความสูงของกองวัตถุนั้นต้องไม่เกิน 6 เมตร และต้องมีระยะห่างจากโคมไฟไม่น้อยกว่า 60 เซนติเมตร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":319,"law_id":58,"seq":4,"text":"1.2 การทดสอบ ทุก ๆ 5 ปี เครื่องดับเพลิงแบบมือถือจะต้องทดสอบการรับความดัน (hydrostatic test) เพื่อพิจารณาว่ายังสามารถใช้งานได้หรือไม่","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":320,"law_id":58,"seq":5,"text":"2.1 เครื่องสูบน้ำดับเพลิงขับด้วยเครื่องยนต์ดีเซล\n(1) ทดสอบการทำงานของเครื่องสูบน้ำดับเพลิงทุก ๆ สัปดาห์ที่อัตราความเร็วรอบทำงานด้วยระยะเวลาอย่างน้อย 30 นาทีเพื่อให้เครื่องยนต์ร้อนถึงอุณหภูมิทำงาน ตรวจสภาพของเครื่องสูบน้ำ, ชุดควบคุมการทำงานของเครื่องสูบน้ำ\n2.2 เครื่องสูบน้ำดับเพลิงขับด้วยมอเตอร์ไฟฟ้า\n(1) ทดสอบการทำงานของเครื่องสูบน้ำทุก ๆ เดือน\n3.2 หัวรับน้ำดับเพลิงควรจะได้รับการตรวจสอบเดือนละหนึ่งครั้ง\n(2) หัวดับเพลิงในสถานประกอบการควรตรวจสอบเดือนละครั้งว่าอยู่ในสภาพที่เห็นชัดเจนและเข้าถึงได้ง่ายโดยมีฝาครอบปิดอยู่เรียบร้อย\n(1) ทดสอบการทำงานของหัวดับเพลิงอย่างน้อยปีละหนึ่งครั้ง โดยการเปิดและปิดเพื่อให้แน่ใจได้ว่ามีน้ำไหลออกจากหัวดับเพลิง\n5.1 ตรวจสอบระดับน้ำในถังน้ำดับเพลิงเดือนละครั้ง\n6.1 ตรวจสอบตู้เก็บสายฉีดเดือนละหนึ่งครั้งเพื่อให้แน่ใจว่ามีอุปกรณ์ฉีดน้ำดับเพลิงอยู่ครบและอยู่ในสภาพดี\n7.1 หัวกระจายน้ำดับเพลิงจะต้องได้รับการตรวจสอบด้วยสายตาเป็นระยะ ๆ อย่างสม่ำเสมอ สภาพของหัวกระจายน้ำดับเพลิงต้องไม่ผุกร่อน, ถูกทาสีทับหรือชำรุดเสียหาย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":338,"law_id":62,"seq":0,"text":"ใช้บังคับตั้งแต่วันที่ 12 มีนาคม 2556 เป็นต้นไป\nการรายงานผลการฝึกซ้อมดับเพลิงและฝึกซ้อมอพยพหนีไฟให้เป็นไปตามแบบรายงานผลการฝึกซ้อมดับเพลิงและฝึกซ้อมอพยพหนีไฟ ตามท้ายประกาศนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":342,"law_id":66,"seq":0,"text":"กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม ข้อกำหนดในการป้องกันอัคคีภัย เล่ม 8 การติดตั้งระบบส่งน้ำดับเพลิง มาตรฐานเลขที่ มอก. 2541 เล่ม 8 - 2560 ไว้  รายละเอียดตามท้ายประกาศนี้\nขอบข่าย :   ครอบคลุมองค์ประกอบและข้อกำหนดการติดตั้ง การทดสอบ การทำงานเพื่อตรวจรับงาน รวมทั้งการตรวจสอบและทดสอบระบบส่งน้ำดับเพลิง  แหล่งน้ำดับเพลิง ระบบส่งน้ำดับเพลิง  และวัสดุอุปกรณ์ที่ใช้กับอาคารทั่วไปรวมทั้งโรงงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":351,"law_id":70,"seq":0,"text":"ข้อ ๒ ให้นายจ้างจัดให้มีการตรวจวัดและวิเคราะห์สภาวะการทำงานเกี่ยวกับระดับความร้อน แสงสว่าง หรือเสียง ภายในสถานประกอบกิจการในสภาวะที่เป็นจริงของสภาพการทำงานอย่างน้อยปีละหนึ่งครั้ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":357,"law_id":74,"seq":0,"text":"4. วิธีการตรวจวัดระดับเสียงการรบกวน ระดับเสียงเฉลี่ย 24 ชั่วโมง และระดับเสียงสูงสุดที่เกิดจากการประกอบกิจการโรงงาน ให้ดำเนินการดังนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":792,"law_id":109,"seq":8,"text":"9. ผู้ใช้บริการมีสิทธิร้องเรียนเกี่ยวกับการละเมิดข้อมูลส่วนบุคคลผ่าน กสทช.\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":339,"law_id":63,"seq":0,"text":"- การรายงานผลการฝึกซ้อมดับเพลิงและฝึกซ้อมอพยพหนีไฟตามข้อ ๓๐ แห่งกฎกระทรวงฯ การป้องกันและระงับอัคคีภัย พ.ศ. ๒๕๕๕ ต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมาย นายจ้างอาจรายงานทางสื่ออิเล็กทรอนิกส์ตามแบบรายงานผลการฝึกซ้อมดับเพลิงและฝึกซ้อมอพยพหนีไฟทางสื่ออิเล็กทรอนิกส์\n - นายจ้างที่มีความประสงค์จะรายงานผลการฝึกซ้อมดับเพลิงและฝึกซ้อมอพยพหนีไฟทางสื่ออิเล็กทรอนิกส์ตามข้อ ๓ ต้องลงทะเบียนเพื่อขอรหัสผู้ใช้ (User ID) และรหัสผ่าน (Password)\nทางเว็บไซต์ของกรมสวัสดิการและคุ้มครองแรงงาน (http://eservice.labour.go.th)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":343,"law_id":67,"seq":0,"text":"ข้อ ๗ ผู้ประสงค์จะขอขึ้นทะเบียนเป็นผู้ให้บริการด้านความปลอดภัย อาชีวอนามัย\nและสภาพแวดล้อมในการท างานต้องมีคุณสมบัติ ตามที่กฎหมายกำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":352,"law_id":71,"seq":0,"text":"ข้อ ๑๕ ผู้ที่ดำเนินการตรวจวัดและวิเคราะห์สภาวะการทำงานในสถานประกอบกิจการ\nต้องมีคุณสมบัติอย่างหนึ่งอย่างใด ดังต่อไปนี้\n(๑) เป็นบุคคลที่ขึ้นทะเบียนเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานระดับวิชาชีพของสถานประกอบกิจการกับกรมสวัสดิการและคุ้มครองแรงงาน สามารถดำเนินการตรวจวัดและวิเคราะห์สภาวะการทำงานเกี่ยวกับความร้อน แสงสว่าง หรือเสียง ภายในสถานประกอบกิจการของตนเอง\n(๒) เป็นบุคคลที่ผู้สำเร็จการศึกษาไม่ต่ำกว่าปริญญาตรีสาขาอาชีวอนามัยหรือเทียบเท่า\nที่ขึ้นทะเบียนเป็นเจ้าหน้าที่ความปลอดภัยในการทำงานของสถานประกอบกิจการกับกรมสวัสดิการและคุ้มครองแรงงาน สามารถดำเนินการตรวจวัดและวิเคราะห์สภาวะการทำงานเกี่ยวกับความร้อน แสงสว่าง หรือเสียง ภายในสถานประกอบกิจการของตนเอง\n(๓) เป็นบุคคลหรือนิติบุคคลที่ขึ้นทะเบียนตามมาตรา ๙ หรือมาตรา ๑๑ แห่งพระราชบัญญัติความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. ๒๕๕๔ แล้วแต่กรณี","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":367,"law_id":75,"seq":0,"text":"ข้อ ๔ ค่ามาตรฐานมลพิษทางเสียง คือ ค่าระดับเสียงรบกวนอันเกิดจากการประกอบกิจการของสถานประกอบกิจการ ไม่เกิน 10 เดซิเบลเอ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":309,"law_id":55,"seq":1,"text":"ข้อ 15 การเก็บภาชนะบรรจุน้ำมันเชื้อเพลิงไว้นอกอาคารต้องมีระยะปลอดภัยตามที่กำหนดไว้ในตารางที่ 2","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":321,"law_id":59,"seq":0,"text":"กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม การจัดการหน่วยดับเพลิงสำหรับสถานประกอบการ มาตรฐาน\nเลขที่ มอก. 2563-2555\n1. ขอบข่าย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":337,"law_id":61,"seq":0,"text":"ใช้บังคับตั้งแต่วันที่ 12 มีนาคม 2556 เป็นต้นไป\n     1. มาตรฐานเครื่องดับเพลิงแบบเคลื่อนย้ายได้  ได้แก่ \n        1.1 มาตรฐานสมาคมป้องกันอัคคีภัยแห่งชาติ สหรัฐอเมริกา (NFPA) \n        1.2 มาตรฐานสถาบันมาตรฐานแห่งชาติ ประเทศสหรัฐอเมริกา (ANSI) \n        1.3 มาตรฐานประเทศออสเตรเลีย (AS) \n        1.4 มาตรฐานประเทศอังกฤษ (BS)\n        1.5 มาตรฐานองค์การมาตรฐานสากล  (ISO)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":341,"law_id":65,"seq":0,"text":"ข้อ 1 ให้ยกเลิกความใน (1) ของข้อ 11 แห่งกฎกระทรวงกำหนดมาตรฐานในการบริหาร จัดการ และดำเนินการด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานเกี่ยวกับการป้องกัน และระงับอัคคีภัย พ.ศ. 2555 และให้ใช้ความต่อไปนี้แทน\n“(1) ตัวอักษรต้องมีขนาดไม่เล็กกว่าสิบเซนติเมตร และมองเห็นได้อย่ำงชัดเจน”\n[จากเดิม : ข้อ 11 ให้นายจ้างจัดให้มีป้ายบอกทางหนีไฟที่มีลักษณะ ดังต่อไปนี้\n(1) ขนาดของตัวหนังสือต้องสูงไม่น้อยกว่าสิบห้าเซนติเมตร และเห็นได้อย่างชัดเจน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":328,"law_id":60,"seq":6,"text":"ข้อ ๙ สถานประกอบกิจการที่มีอาคารตั้งแต่สองชั้นขึ้นไป หรือมีพื้นที่ประกอบกิจการตั้งแต่สามร้อยตารางเมตรขึ้นไป ให้นายจ้างจัดให้มีระบบสัญญาณแจ้งเหตุเพลิงไหม้ในสถานประกอบกิจการทุกชั้นโดยให้ปฏิบัติ ดังต่อไปนี้\n(๑) ระบบสัญญาณแจ้งเหตุเพลิงไหม้อย่างน้อยต้องประกอบด้วย\n(ก) อุปกรณ์แจ้งเหตุเพลิงไหม้ทั้งที่ใช้ระบบแจ้งเหตุอัตโนมัติและระบบแจ้งเหตุที่ใช้มือเพื่อให้อุปกรณ์ส่งสัญญาณแจ้งเหตุเพลิงไหม้ทำงาน\n(ข) อุปกรณ์ส่งสัญญาณแจ้งเหตุเพลิงไหม้ต้องสามารถส่งเสียงหรือสัญญาณให้ทุกคนภายในอาคารได้ยินหรือทราบอย่างทั่วถึงเพื่อการหนีไฟ\n(๒) อุปกรณ์แจ้งเหตุที่ใช้มือต้องอยู่ในที่เห็นได้อย่างชัดเจน เข้าถึงได้ง่าย หรืออยู่ในเส้นทางหนีไฟโดยติดตั้งห่างจากจุดที่ลูกจ้างทางานไม่เกินสามสิบเมตร\n(๓) เสียงหรือสัญญาณที่ใช้ในการแจ้งเหตุเพลิงไหม้ต้องมีเสียงหรือสัญญาณที่แตกต่างไปจากเสียงหรือสัญญาณที่ใช้ในสถานประกอบกิจกา","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":329,"law_id":60,"seq":7,"text":"ข้อ ๑๑ ให้นายจ้างจัดให้มีป้ายบอกทางหนีไฟที่มีลักษณะ ดังต่อไปนี้\n(๑) ขนาดของตัวหนังสือต้องสูงไม่น้อยกว่าสิบห้าเซนติเมตร และเห็นได้อย่างชัดเจน\n(๒) ป้ายบอกทางหนีไฟต้องมีแสงสว่างในตัวเองหรือใช้ไฟส่องให้เห็นได้อย่างชัดเจนตลอดเวลา\nทั้งนี้ ต้องไม่ใช้สีหรือรูปร่างที่กลมกลืนไปกับการตกแต่งหรือป้ายอื่น ๆ ที่ติดไว้ใกล้เคียง หรือโดยประการใด\nที่ท าให้เห็นป้ายไม่ชัดเจน\nนายจ้างอาจใช้รูปภาพบอกทางหนีไฟตามมาตรฐานของสมาคมวิศวกรรมสถานแห่งประเทศไทย\nในพระบรมราชูปถัมภ์ ได้ ทั้งนี้ ต้องให้เห็นได้อย่างชัดเจน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":330,"law_id":60,"seq":8,"text":"ข้อ ๑๓ ให้นายจ้างจัดให้มีเครื่องดับเพลิงแบบเคลื่อนย้ายได้ โดยต้องปฏิบัติ ดังต่อไปนี้\n(๑) จัดให้มีเครื่องดับเพลิงแบบเคลื่อนย้ายได้ตามประเภทของเพลิง ซึ่งเป็นไปตามมาตรฐาน\n(๒) เครื่องดับเพลิงแบบเคลื่อนย้ายได้ทุกเครื่อง ต้องจัดให้มีเครื่องหมายหรือสัญลักษณ์\nแสดงว่าเป็นชนิดใด ใช้ดับเพลิงประเภทใด และเครื่องหมายหรือสัญลักษณ์นั้นต้องมีขนาดที่มองเห็นได้อย่างชัดเจนในระยะไม่น้อยกว่าหนึ่งเมตรห้าสิบเซนติเมตร\n(๓) ห้ามใช้เครื่องดับเพลิงแบบเคลื่อนย้ายได้ที่อาจเกิดไอระเหยของสารพิษ เช่น\nคาร์บอนเตตราคลอไรด์\n(๔) จัดให้มีเครื่องดับเพลิงแบบเคลื่อนย้ายได้ตามจำนวน ความสามารถของเครื่องดับเพลิง\n(๕) จัดให้มีการดูแลรักษาและตรวจสอบเครื่องดับเพลิงให้อยู่ในสภาพที่ใช้งานได้ดี โดยการตรวจสอบ ต้องไม่น้อยกว่าหกเดือนต่อหนึ่งครั้ง พร้อมกับติดป้ายแสดงผลการตรวจสอบและวันที่ทำการตรวจสอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":331,"law_id":60,"seq":9,"text":"ข้อ ๑๔ กรณีที่นายจ้างจัดให้มีระบบดับเพลิงอัตโนมัติ ให้ปฏิบัติ ดังต่อไปนี้\n(๑) ระบบดับเพลิงอัตโนมัติต้องเป็นไปตามมาตรฐานของสมาคมวิศวกรรมสถานแห่งประเทศไทยในพระบรมราชูปถัมภ์\n(๒) ต้องเปิดวาล์วประธานที่ควบคุมระบบจ่ายน้ำเข้าหรือสารดับเพลิงอื่นอยู่ตลอดเวลา และจัดให้มีผู้ควบคุมดูแลให้ใช้งานได้ตลอดเวลา\n(๓) ต้องติดตั้งสัญญาณเพื่อเตือนภัยในขณะที่ระบบดับเพลิงอัตโนมัติกำลังทำงาน\n(๔) ต้องไม่มีสิ่งกีดขวางทางน้ำหรือสารดับเพลิงอื่นจากหัวฉีดดับเพลิงโดยรอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":332,"law_id":60,"seq":10,"text":"ข้อ ๑๖ ให้นายจ้างปฏิบัติเกี่ยวกับอุปกรณ์ดับเพลิง ดังต่อไปนี้ (๑) ติดตั้งป้ายแสดงจุดติดตั้งอุปกรณ์ดับเพลิงที่เห็นได้อย่างชัดเจน (๒) ติดตั้งอุปกรณ์ดับเพลิงในที่เห็นได้อย่างชัดเจน ไม่มีสิ่งกีดขวาง และสามารถนำมาใช้งาน ได้โดยสะดวกตลอดเวลา (๓) จัดให้มีการดูแลรักษาและตรวจสอบอุปกรณ์ดับเพลิงให้อยู่ในสภาพที่ใช้งานได้ดี โดยในการตรวจสอบนั้นต้องไม่น้อยกว่าเดือนละหนึ่งครั้งหรือตามระยะเวลาที่ผู้ผลิตกำหนด พร้อมกับติดป้าย แสดงผลการตรวจสอบและวันที่ทำการตรวจสอบครั้งสุดท้ายไว้ที่อุปกรณ์ดังกล่าว และเก็บผลการตรวจสอบ ไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบได้ตลอดเวลา","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":333,"law_id":60,"seq":11,"text":"ข้อ ๑๘ ให้นายจ้างป้องกันอัคคีภัยจากแหล่งก่อเกิดการกระจายตัวของความร้อน ดังต่อไปนี้\n(๑) กระแสไฟฟ้าลัดวงจร ให้เป็นไปตามกฎหมายเกี่ยวกับความปลอดภัยในการทำงาน\nเกี่ยวกับไฟฟ้า\n(๕) การสะสมของไฟฟ้าสถิต โดยต่อสายดินกับถังหรือท่อน้ำมันเชื้อเพลิง สารเคมี หรือ\nของเหลวไวไฟ ทั้งนี้ ให้เป็นไปตามกฎหมายเกี่ยวกับความปลอดภัยในการทำงานเกี่ยวกับไฟฟ้า","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":334,"law_id":60,"seq":12,"text":"ข้อ ๒๕ ให้นายจ้างจัดให้มีระบบป้องกันอันตรายจากฟ้าผ่าสำหรับอาคารหรือสิ่งก่อสร้าง\n๑) อาคารที่มีวัตถุไวไฟหรือวัตถุระเบิด\n(๒) สิ่งก่อสร้างที่มีความสูง ประเภท ปล่องควัน หอคอย เสาธง ถังเก็บน้ำหรือสารเคมี\nหรือสิ่งก่อสร้างอื่นใดที่มีความสูงในทำนองเดียวกัน\nข้อ ๒๖ ให้นายจ้างจัดให้มีมาตรการป้องกันผลกระทบจากฟ้าผ่าเข้าสู่ระบบไฟฟ้าของอาคาร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":335,"law_id":60,"seq":13,"text":"ข้อ ๒๗ ให้นายจ้างจัดให้ลูกจ้างไม่น้อยกว่าร้อยละสี่สิบของจำนวนลูกจ้างในแต่ละหน่วยงานของสถานประกอบกิจการรับการฝึกอบรมการดับเพลิงขั้นต้น โดยให้ผู้ที่ได้รับใบอนุญาตจากกรมสวัสดิการและคุ้มครองแรงงานเป็นผู้ดาเนินการฝึกอบรม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":336,"law_id":60,"seq":14,"text":"ข้อ ๓๐ ให้นายจ้างจัดให้ลูกจ้างทุกคนฝึกซ้อมดับเพลิงและฝึกซ้อมอพยพหนีไฟพร้อมกันอย่างน้อยปีละหนึ่งครั้ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":344,"law_id":68,"seq":0,"text":"ข้อ ๒๘ อาคารสูงต้องจัดให้มีช่องทางเฉพาะสาหรับบุคคลภายนอกเข้าไปบรรเทาสาธารณภัย\nที่เกิดในอาคารได้ทุกชั้น ช่องทางเฉพาะนี้จะเป็นลิฟต์ดับเพลิงหรือช่องบันไดหนีไฟก็ได้และทุกชั้น\nต้องจัดให้มีห้องว่างที่มีพื้นที่ไม่น้อยกว่า ๖.๐๐ ตารางเมตร มีด้านแคบที่สุดไม่น้อยกว่า ๒.๕๐ เมตร\nข้อ ๒๙/๑ อาคารสูงหรืออาคารขนาดใหญ่พิเศษต้องจัดให้มีพื้นที่สาหรับยานพาหนะ รถดับเพลิง อย่างน้อย 1 คัน และรถพยาบาล อย่างน้อย 1 คน \n-เจ้าของอาคารหรือผู้ครอบครองอาคารต้องดูแลพื้นที่ปฏิบัติการตามวรรคหนึ่ง ให้รถดับเพลิง รถพยาบาลหรือรถปฏิบัติการฉุกเฉินสามารถเข้าถึงได้สะดวกตลอดเวลาโดยไม่มีสิ่งกีดขวาง\n-รูปแบบ สัญลักษณ์ และรายละเอียดเกี่ยวกับพื้นที่สาหรับยานพาหนะตามวรรคหนึ่ง\nให้เป็นไปตามที่กาหนดท้ายกฎกระทรวงนี้\nข้อ ๔๓ ลิฟต์โดยสารที่ใช้กับอาคารสูงให้มีขนาดมวลบรรทุกไม่น้อยกว่า ๖๓๐ กิโลกรัม\nข้อ ๔๔ อาคารสูงต้องจัดให้มีลิฟต์ดับเพลิงอย่างน้อยหนึ่งชุด\nข้อ ๒๙/๒ อาคารสูงหรืออาคารขนาดใหญ่พิเศษ ที่เป็นอาคารสาธารณะต้องจัดให้มีพื้นที่\nหรือตำแหน่งเพื่อติดตั้งเครื่องฟื้นคืนคลื่นหัวใจด้วยไฟฟ้าแบบอัตโนมัติ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":353,"law_id":72,"seq":0,"text":"ข้อ ๒ ให้นายจ้างจัดทำมาตรการอนุรักษ์การได้ยินในสถานประกอบกิจการเป็นลายลักษณ์อักษรในกรณีที่สภาวะการทำงานในสถานประกอบกิจการมีระดับเสียงที่ลูกจ้างได้รับเฉลี่ยตลอดระยะเวลาการทำงานแปดชั่วโมงตั้งแต่แปดสิบห้าเดซิเบลเอขึ้นไป\nให้นายจ้างประกาศมาตรการอนุรักษ์การได้ยินในสถานประกอบกิจการให้ลูกจ้างทราบ\nข้อ ๓ ให้นายจ้างจัดให้มีการเฝ้าระวังเสียงดัง โดยการสำรวจและตรวจวัดระดับเสียง\nการศึกษาระยะเวลาสัมผัสเสียงดัง และการประเมินการสัมผัสเสียงดังของลูกจ้างในสถานประกอบกิจการแล้วแจ้งผลให้ลูกจ้างทราบ\nข้อ ๔ ให้นายจ้างจัดให้มีการเฝ้าระวังการได้ยินโดยให้ดำเนินการ ดังนี้\n(๑) ทดสอบสมรรถภาพการได้ยิน (Audiometric sting) แก่ลูกจ้างที่สัมผัสเสียงดังที่ได้ รับเฉลี่ยตลอดระยะเวลาการทำงานแปดชั่วโมงตั้งแต่แปดสิบห้าเดซิเบลเอขึ้นไป และให้ทดสอบสมรรถภาพการได้ยินของลูกจ้างครั้งต่อไปอย่างน้อยปีละหนึ่งครั้ง\n(๒) แจ้งผลการทดสอบสมรรถภาพการได้ยินให้ลูกจ้างทราบภายในเจ็ดวันนับแต่วันที่นายจ้างทราบผลการทดสอบ\n(๓) ทดสอบสมรรถภาพการได้ยินของลูกจ้างซ้ำอีกครั้งภายในสามสิบวันนับแต่วันที่นายจ้างทราบผลการทดสอบ กรณีพบว่าลูกจ้างมีสมรรถภาพการสูญเสียการได้ยิน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":354,"law_id":72,"seq":1,"text":"- การทดสอบสมรรถภาพการได้ยินครั้งแรกของลูกจ้างที่ความถี่ ๕๐๐ ๑๐๐๐ ๒๐๐๐ ๓๐๐๐ ๔๐๐๐ และ ๖๐๐๐ เฮิรตซ์ ของหูทั้งสองข้างเป็นข้อมูลพื้นฐาน (Baseline Audiogram)\nข้อ ๖ หากผลการทดสอบสมรรถภาพการได้ยิน พบว่าลูกจ้างสูญเสียการได้ยินที่หูข้างใดข้างหนึ่งตั้งแต่สิบห้าเดซิเบลขึ้นไปที่ความถี่ใดความถี่หนึ่ง ให้นายจ้างจัดให้มีมาตรการป้องกันอันตรายอย่างหนึ่งอย่างใดแก่ลูกจ้าง ดังนี้\n(๑) จัดให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่สามารถลดระดับเสียงที่ลูกจ้างได้รับเฉลี่ยตลอดระยะเวลาการทำงานแปดชั่วโมงน้อยกว่าแปดสิบห้าเดซิเบลเอ\n(๒) เปลี่ยนงานให้ลูกจ้าง หรือหมุนเวียนสลับหน้าที่ระหว่างลูกจ้างด้วยกันเพื่อให้ระดับเสียงที่ลูกจ้างได้รับเฉลี่ยตลอดระยะเวลาการทำงานแปดชั่วโมงน้อยกว่าแปดสิบห้าเดซิเบลเอ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":355,"law_id":72,"seq":2,"text":"ข้อ ๗ ให้นายจ้างจัดทำและติดแผนผังแสดงระดับเสียง (Noise Contour Map) ในแต่ละพื้นที่เกี่ยวกับผลการตรวจวัดระดับเสียง ติดป้ายบอกระดับเสียงและเตือนให้ระวังอันตรายจากเสียงดังรวมถึงจัดให้มีเครื่องหมายเตือนให้ใช้อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลในแต่ละพื้นที่ที่มีความเสี่ยงจากเสียงดังและทุกพื้นที่ที่มีระดับเสียงดังตั้งแต่แปดสิบห้าเดซิเบลเอขึ้นไป ตามประกาศกำหนด\nข้อ ๘ ให้นายจ้างอบรมให้ความรู้ความเข้าใจเกี่ยวกับมาตรการอนุรักษ์การได้ยินแก่ลูกจ้างที่ทำงานในบริเวณที่มีระดับเสียงดังที่ได้รับเฉลี่ยตลอดระยะเวลาการทำงานแปดชั่วโมงตั้งแต่แปดสิบห้าเดซิเบลเอขึ้นไป และลูกจ้างที่เกี่ยวข้องในสถานประกอบกิจการ\nข้อ ๙ ให้นายจ้างประเมินผลและทบทวนการจัดการมาตรการอนุรักษ์การได้ยินในสถาน\nประกอบกิจการไม่น้อยกว่าปีละหนึ่งครั้ง\nข้อ ๑๐ ให้นายจ้างบันทึกข้อมูลและจัดทำเอกสารการดำเนินการ เก็บไว้ในสถานประกอบกิจการไม่น้อยกว่าห้าปี พร้อมที่จะให้พนักงานตรวจความปลอดภัยตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":368,"law_id":76,"seq":0,"text":"1. กำหนดให้สถานประกอบกิจการมีความเข้มของแสงสว่างไม่ต่ำกว่ามาตรฐานที่กำหนดไว้ในตารางแนบท้ายประกาศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":356,"law_id":73,"seq":0,"text":"1.ค่าระดับการรบกวนที่เกิดจากการประกอบกิจการไม่เกิน 10 เดซิเบลเอ\n2.ค่าระดับเสียงเฉลี่ย 24 ชม ที่เกิดจากการประกอบกิจการไม่เกิน 70  เดซิเบลเอ\n3.ค่าระดับเสียงสูงสุด ที่เกิดจากการประกอบกิจการไม่เกิน 115  เดซิเบลเอ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":369,"law_id":77,"seq":0,"text":"1. การคํานวณระดับเสียงที่สัมผัสในหูเมื่อสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล ที่สอดคล้องกับข้อมูลการลดเสียงของผู้ผลิตอย่างหนึ่งอย่างใด  ดังนี้\n(1) การคำนวณโดยใช้ค่า Noise Reduction Rating (NRR) ที่ระบุไว้บนผลิตภัณฑ์กับค่าตรวจวัดระดับเสียงเฉลี่ย\nตลอดระยะเวลาการทำงาน\nProtected dBA = Sound Level dBC – NRRadj หรือ\nProtected dBA = Sound Level dBA – [NRRadj – 7]\n(2) การคำนวณโดยใช้ค่า Single Number Rating (SNR) ที่ระบุไว้บนผลิตภัณฑ์กับค่าตรวจวัดระดับเสียงเฉลี่ยตลอดระยะเวลาการทำงาน\n                    L’AX = (LC – SNRx) + 4\n(3) การคำนวณระดับเสียงที่สัมผัสในหูเมื่อสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลนอกเหนือ\nจาก (1) และ (2)  ให้ใช้วิธีการคำนวนตามที่กำหนดไว้ในประกาศกระทรวงอุตสาหกรรม ฉบับที่ 4456 \n(พ.ศ. 2555) ออกตามความพระราชบัญญัติผลิตภัณฑ์อุตสาหกรรม พ.ศ. 2511 เรื่อง กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรมข้อแนะนำในการเลือก การใช้ การดูแล และการบำรุงรักษาอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล เล่ม 1 อุปกรณ์การปกป้องการได้ยิน ข้อ 4 หลักเกณฑ์การเลือกอุปกรณ์ปกป้องการได้ยิน ลงวันที่ 28 สิงหาคม พ.ศ. 2555","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":370,"law_id":77,"seq":1,"text":"2. กรณีที่ฉลากหรืออุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลมีการระบุค่าการลดเสียงมากกว่า 1 ค่า ให้นายจ้างใช้ค่าที่ลดเสียงที่สัมผัสในหูเมื่อสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่ได้จากการคำนวณน้อยที่สุดเป็นหลักในการพิจารณาลดระดับความดังเสียงจากสภาพแวดล้อมในการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":376,"law_id":81,"seq":0,"text":"กำหนดชนิดของโรคซึ่งเกิดขึ้นตามลักษณะหรือสภาพของงานหรือเนื่องจากการทำงาน \n\n กลุ่มโรคเฝ้าระวังที่อาจมีโอกาสเกิด \n(2.3) โรคและความผิดปกติในระบบกระดูก กล้ามเนื้อ เอ็นและข้อ : \n(2.4) ความผิดปกติทางจิตและพฤติกรรม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":398,"law_id":86,"seq":10,"text":"ข้อ ๑๕ ให้นายจ้างจัดให้มีเครื่องดับเพลิงที่มีประสิทธิภาพและจำนวนเพียงพอที่จะใช้ได้ทันทีเมื่อมีการทำงานที่อาจก่อให้เกิดการลุกไหม้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":358,"law_id":74,"seq":1,"text":"(1) การเตรียมเครื่องมือก่อนการตรวจวัด ให้ปรับเทียบมาตรระดับเสียงด้วยเครื่องกำเนิดเสียง มาตรฐาน เช่น พิสตันโฟน (Piston Phone) หรืออะคูสติคคาลิเบรเตอร์ (Acoustic Calibrator) เป็นต้น หรือตรวจสอบตามคู่มือการใช้งานหรือวิธีการที่ผู้ผลิตมาตรระดับเสียงกำหนดไว้ โดยต้อง   ปรับเทียบมาตรระดับเสียงทุกครั้งก่อนที่จะตรวจวัดระดับเสียงพื้นฐาน ระดับเสียงขณะไม่มีการรบกวน ระดับเสียงขณะมีการรบกวน ระดับเสียงเฉลี่ย 24 ชั่วโมง และระดับเสียงสูงสุด โดยต้องปรับมาตร ระดับเสียงไว้ที่วงจรถ่วงน้ำหนัก “A” (WeigRAing Network “A”) และลักษณะความไวตอบรับเสียง “Fast” (Dynamic Characteristics “Fast”)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":359,"law_id":74,"seq":2,"text":"(2) การตั้งไมโครโฟนของมาตรระดับเสียงในการตรวจวัดระดับเสียงพื้นฐาน ระดับเสียงขณะไม่มีการรบกวน ระดับเสียงขณะมีการรบกวน ระดับเสียงเฉลี่ย 24 ชั่วโมง และระดับเสียงสูงสุดให้เป็นไปตามหลักเกณฑ์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":360,"law_id":74,"seq":3,"text":"(3) การตรวจวัดระดับเสียงการรบกวน ให้ดำเนินการดังนี้  (3.1) การตรวจวัดระดับเสียงพื้นฐานและระดับเสียงขณะไม่มีการรบกวน ให้ตรวจวัดเป็นเวลาไม่น้อยกว่า 5 นาที ในขณะที่ไม่มีเสียงจากการประกอบกิจการโรงงานในช่วงเวลาใดเวลาหนึ่ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":361,"law_id":74,"seq":4,"text":"(4) การตรวจวัดระดับเสียงเฉลี่ย 24 ชั่วโมง ให้ใช้มาตรระดับเสียงตรวจวัดระดับเสียงอย่างต่อเนื่องตลอดเวลา 24 ชั่วโมงใด ๆ เป็นค่าระดับเสียงเฉลี่ย 24 ชั่วโมง (LAeq, 24 hr)              (5) การตรวจวัดระดับเสียงสูงสุด ให้ใช้มาตรระดับเสียงตรวจวัดระดับเสียงสูงสุดที่เกิดขึ้นในขณะใดขณะหนึ่งระหว่างการตรวจวัดเสียง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":362,"law_id":74,"seq":5,"text":"(6) การบันทึกการตรวจวัดเสียง ให้ผู้ตรวจวัดบันทึกการตรวจวัดเสียง โดยมีรายละเอียดอย่างน้อย ดังต่อไปนี้    (6.1) ชื่อ ชื่อสกุล ตำแหน่งและสังกัดของผู้ตรวจวัด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":363,"law_id":74,"seq":6,"text":"(6.2) ลักษณะเสียงและช่วงเวลาการเกิดเสียงจากการประกอบกิจการโรงงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":364,"law_id":74,"seq":7,"text":"(6.3) สถานที่ ตำแหน่งที่ตรวจวัด วัน และเวลาการตรวจวัดเสียง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":365,"law_id":74,"seq":8,"text":"(6.4) ผลการตรวจวัดระดับเสียงพื้นฐาน ระดับเสียงขณะไม่มีการรบกวน ระดับเสียงขณะมีการรบกวน ระดับเสียงเฉลี่ย 24 ชั่วโมง หรือระดับเสียงสูงสุด แล้วแต่กรณี","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":366,"law_id":74,"seq":9,"text":"(7) การรายงานผลการตรวจวัดระดับเสียงพื้นฐาน ระดับเสียงขณะมีการรบกวน ค่าระดับการรบกวน ระดับเสียงเฉลี่ย 24 ชั่วโมงและระดับเสียงสูงสุด ให้รายงานที่ทศนิยม 1 ตำแหน่ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":399,"law_id":86,"seq":11,"text":"ข้อ ๑๖ ห้ามนายจ้างอนุญาตให้ลูกจ้างทำงานที่ก่อให้เกิดความร้อน หรือประกายไฟในที่อับอากาศ เช่น การเชื่อม การเผาไหม้ การย้ำหมุด การเจาะ หรือการขัด เว้นแต่จะได้จัดให้มีมาตรการความปลอดภัยที่เหมาะสมตามหมวดนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":409,"law_id":87,"seq":0,"text":"เพื่อปฏิบัติการให้เป็นไปตามประกาศคณะกรรมการรัฐวิสาหกิจสัมพันธ์ เรื่อง ความปลอดภัยในการทำงานในสถานที่อับอากาศ ลงวันที่ 12 กันยายน พ.ศ. 2534 ข้อ 3 (4) ซึ่งกำหนดให้รัฐวิสาหกิจจัดให้มีใบอนุญาตให้พนักงานเข้าทำงานในสถานที่อับอากาศทุกครั้งตามแบบที่อธิบดีกรมแรงงานกำหนด ประกอบด้วยพระราชบัญญัติโอนอำนาจหน้าที่และกิจการบริหารบางส่วนของกระทรวงมหาดไทยไปเป็นของกระทรวงแรงงานและสวัสดิการสังคม พ.ศ. 2536 มาตรา 10 อธิบดีกรมสวัสดิการและคุ้มครองแรงงานจึงออกประกาศไว้ดังต่อไปนี้\nใบอนุญาตให้พนักงานเข้าทำงานในสถานที่อับอากาศให้เป็นไปตามแบบ อร.1 ท้ายประกาศนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":374,"law_id":79,"seq":4,"text":"ปฏิบัติตามสิทิ์ประกันพระราชบัญญัติเงินทดแทนกรณีผู้ประกันตนประสบอันตรายเจ็บป่วยจากการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":410,"law_id":88,"seq":0,"text":"ข้อ ๒ ประกาศนี้ให้ใช้บังคับตั้งแต่วันประกาศเป็นต้นไป\nข้อ ๓ อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลสำหรับการทำงานในที่อับอากาศต้องเป็นไป\nตามมาตรฐานผลิตภัณฑ์อุตสาหกรรม หรือมาตรฐานอื่นที่กรมสวัสดิการและคุ้มครองแรงงานยอมรับ\nข้อ ๔ อุปกรณ์ช่วยเหลือและช่วยชีวิตสำหรับการทำงานในที่อับอากาศต้องเป็นไปตามมาตรฐานผลิตภัณฑ์อุตสาหกรรม หรือมาตรฐานอื่นที่กรมสวัสดิการและคุ้มครองแรงงานยอมรับ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":793,"law_id":109,"seq":9,"text":"10. กสทช. มีอำนาจขอให้ผู้รับใบอนุญาตส่งข้อมูลส่วนบุคคลของผู้ใช้บริการมาให้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":422,"law_id":94,"seq":0,"text":"มาตรา 96 กําหนดให้นายจ้างที่มีลูกจ้างตั้งแต่ 50 คน ขึ้นไป ต้องจัดให้มีคณะกรรมการสวัสดิการในสถานประกอบกิจการ ประกอบด้วยผู้แทนฝ่ายลูกจ้างแต่เพียงฝ่ายเดียวอย่างน้อย 5 คน เพื่อเป็นตัวแทนของลูกจ้างร่วมปรึกษาหารือกับนายจ้างเพื่อการจัดสวัสดิการภายในสถานประกอบกิจการให้แก่ลูกจ้าง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":423,"law_id":94,"seq":1,"text":"มาตรา 97 คณะกรรมการสวัสดิการมีอำนาจหน้าที่ดังนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":714,"law_id":83,"seq":1,"text":"2. นายจ้างต้องจัดให้มีข้อบังคับและขั้นตอนการปฏิบัติงานเพื่อความปลอดภัยในการทำงานกับนั่งร้านหรือค้ำยัน รวมทั้ง\nต้องอบรมหรือชี้แจงให้ลูกจ้างทราบก่อนปฏิบัติงานอย่างเคร่งครัด และต้องมีสำเนาเอกสารเพื่อให้พนักงานตรวจสอบได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":388,"law_id":86,"seq":0,"text":"หมวด ๑ บททั่วไป\nข้อ ๓ ให้นายจ้างจัดทำป้ายแจ้งข้อความว่า “ที่อับอากาศ อันตราย ห้ามเข้า” ให้มีขนาดมองเห็นได้ชัดเจน ติดตั้งไว้โดยเปิดเผยบริเวณทางเข้าออกของที่อับอากาศทุกแห่ง\nข้อ ๔ ห้ามนายจ้างให้ลูกจ้างหรือบุคคลใดเข้าไปในที่อับอากาศ เว้นแต่นายจ้างได้ดำเนินการให้มีความปลอดภัยตามกฎกระทรวงนี้แล้ว และลูกจ้างหรือบุคคลนั้นได้รับอนุญาตจากผู้มีหน้าที่รับผิดชอบในการอนุญาตตามข้อ ๑๘ และเป็นผู้ผ่านการอบรมตามข้อ ๒๑\nข้อ ๕ ห้ามนายจ้างอนุญาตให้ลูกจ้างหรือบุคคลใดเข้าไปในที่อับอากาศหากนายจ้างรู้หรือควรรู้ว่าลูกจ้างหรือบุคคลนั้นเป็นโรคเกี่ยวกับทางเดินหายใจ โรคหัวใจ หรือโรคอื่นซึ่งแพทย์เห็นว่าการเข้าไปในที่อับอากาศอาจเป็นอันตรายต่อบุคคลดังกล่าว","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":389,"law_id":86,"seq":1,"text":"หมวด ๒ มาตรการความปลอดภัย\nข้อ ๖ ให้นายจ้างจัดให้มีการตรวจวัด บันทึกผลการตรวจวัด และประเมินสภาพอากาศในที่อับอากาศว่ามีบรรยากาศอันตรายหรือไม่ โดยให้ดำเนินการทั้งก่อนให้ลูกจ้างเข้าไปทำงานและในระหว่างที่ลูกจ้างทำงานในที่อับอากาศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":390,"law_id":86,"seq":2,"text":"ข้อ ๗ กรณีที่นายจ้างให้ลูกจ้างทำงานในที่อับอากาศให้นายจ้างแต่งตั้งลูกจ้างที่มีความรู้ความสามารถและได้รับการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามข้อ ๒๑ ให้เป็นผู้ควบคุมงานคนหนึ่งหรือหลายคนตามความจำเป็น","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":391,"law_id":86,"seq":3,"text":"ข้อ ๘ ให้นายจ้างจัดให้ลูกจ้างซึ่งได้รับการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามข้อ ๒๑ คนหนึ่งหรือหลายคนตามความจำเป็น เป็นผู้ช่วยเหลือ พร้อมด้วยอุปกรณ์ช่วยเหลือและช่วยชีวิตที่เหมาะสมกับลักษณะงาน คอยเฝ้าดูแลบริเวณทางเข้าออกที่อับอากาศโดยให้สามารถติดต่อสื่อสารกับลูกจ้างที่ทำงานในที่อับอากาศได้ตลอดเวลา เพื่อช่วยเหลือลูกจ้างออกจากที่อับอากาศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":392,"law_id":86,"seq":4,"text":"ข้อ ๙ ให้นายจ้างจัดให้มีอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล อุปกรณ์ช่วยเหลือและช่วยชีวิตที่เหมาะสมกับลักษณะงานตามมาตรฐานที่อธิบดีประกาศกำหนด และนายจ้างต้องควบคุมดูแลให้ลูกจ้างซึ่งทำงานในที่อับอากาศและผู้ช่วยเหลือสวมใส่หรือใช้อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลและอุปกรณ์ช่วยเหลือและช่วยชีวิตนั้น","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":393,"law_id":86,"seq":5,"text":"ข้อ ๑๐ ให้นายจ้างจัดให้มีสิ่งปิดกั้นมิให้บุคคลใดเข้าหรือตกลงไปในที่อับอากาศที่มีลักษณะเป็นช่อง โพรง หลุม ถังเปิด หรือที่มีลักษณะคล้ายกัน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":394,"law_id":86,"seq":6,"text":"ข้อ ๑๑ ให้นายจ้างปิด กั้น หรือกระทำโดยวิธีการอื่นใดที่มีผลในการป้องกันมิให้พลังงานสาร หรือสิ่งที่เป็นอันตรายเข้าสู่บริเวณที่อับอากาศในระหว่างที่ลูกจ้างกำลังทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":395,"law_id":86,"seq":7,"text":"ข้อ ๑๒ ให้นายจ้างจัดบริเวณทางเดินหรือทางเข้าออกที่อับอากาศให้มีความสะดวกและปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":396,"law_id":86,"seq":8,"text":"ข้อ ๑๓ ให้นายจ้างประกาศห้ามลูกจ้างสูบบุหรี่ หรือพกพาอุปกรณ์สำหรับจุดไฟหรือ ติดไฟ ที่ไม่เกี่ยวข้องกับการทำงานเข้าไปในที่อับอากาศปิดไว้บริเวณทางเข้าออกที่อับอากาศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":397,"law_id":86,"seq":9,"text":"ข้อ ๑๔ ให้นายจ้างจัดให้มีอุปกรณ์ไฟฟ้าที่เหมาะสมในการใช้งานในที่อับอากาศ และตรวจสอบให้อุปกรณ์ไฟฟ้านั้นมีสภาพสมบูรณ์และปลอดภัยพร้อมใช้งาน ถ้าที่อับอากาศนั้นมีบรรยากาศที่ไวไฟหรือระเบิดได้ ต้องเป็นอุปกรณ์ไฟฟ้าชนิดที่สามารถป้องกันมิให้ติดไฟหรือระเบิดได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":402,"law_id":86,"seq":14,"text":"ข้อ ๑๘ ให้นายจ้างเป็นผู้มีหน้าที่รับผิดชอบในการอนุญาตให้ลูกจ้างทำงานในที่อับอากาศ ในการนี้นายจ้างจะมอบหมายเป็นหนังสือให้ลูกจ้างซึ่งได้รับการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามข้อ ๒๑ คนหนึ่งหรือหลายคนตามความจำเป็น เป็นผู้มีหน้าที่รับผิดชอบในการอนุญาตแทนก็ได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":403,"law_id":86,"seq":15,"text":"ให้นายจ้างเก็บหนังสือมอบหมายไว้ ณ สถานประกอบกิจการพร้อมที่จะให้พนักงานตรวจแรงงานตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":404,"law_id":86,"seq":16,"text":"ข้อ ๑๙ ให้นายจ้างจัดให้มีหนังสืออนุญาตให้ลูกจ้างทำงานในที่อับอากาศทุกครั้ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":405,"law_id":86,"seq":17,"text":"ข้อ ๒๐ ให้นายจ้างเก็บหนังสืออนุญาตให้ลูกจ้างทำงานในที่อับอากาศตามข้อ ๑๙ ไว้ ณ สถานที่ประกอบกิจการพร้อมที่จะให้พนักงานตรวจแรงงานตรวจสอบได้ และให้ปิดสำเนาหนังสือดังกล่าวไว้ที่บริเวณทางเข้าที่อับอากาศให้เห็นชัดเจนตลอดเวลาที่ลูกจ้างทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":406,"law_id":86,"seq":18,"text":"หมวด ๔ การฝึกอบรม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":407,"law_id":86,"seq":19,"text":"ข้อ ๒๑ ให้นายจ้างจัดให้มีการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามหลักเกณฑ์ วิธีการ และหลักสูตรที่อธิบดีประกาศกำหนดแก่ลูกจ้างทุกคนที่ทำงานในที่อับอากาศ รวมทั้งผู้ที่เกี่ยวข้องให้มีความรู้ความเข้าใจทักษะที่จำเป็นในการทำงานอย่างปลอดภัย ตามหน้าที่ที่ได้รับมอบหมาย พร้อมทั้งวิธีการและขั้นตอนในการปฏิบัติงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":408,"law_id":86,"seq":20,"text":"ข้อ ๒๒ ให้นายจ้างเก็บหลักฐานการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามข้อ ๒๑ ไว้พร้อมที่จะให้พนักงานตรวจแรงงานตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":415,"law_id":90,"seq":0,"text":"มาตรฐานการตรวจสอบและรับรองแห่งชาตินี้ ระบุแนวทางในการทำงานในที่อับอากาศอย่างปลอดภัย ซึ่งประกอบด้วย\nข้อปฏิบัติทั่วไป ขั้นตอนการเข้าปฏิบัติงานในที่อับอากาศ ระบบการขออนุญาต เอกสารการขออนุญาต การฝึกอบรม และหน้าที่ความรับผิดชอบ มาตรฐานการตรวจสอบและรับรองแห่งชาตินี้เป็นข้อกำหนดทั่วไป ซึ่งใช้ได้กับสถานประกอบ\nกิจการทุกขนาดและทุกประเภท สามารถประยุกต์ใช้ให้เหมาะสมกับสภาพการดำเนินงาน และความซับซ้อนของงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":429,"law_id":100,"seq":0,"text":"จัดให้มีการขึ้นทะเบียน  Software ที่ใช้ในงาน O&M ของ  Co-Location โดยถูกควบคุมจุดใช้งานเสมือนเป็นเอกสารต้นฉบับตามระบบควบคุมเอกสารข้อมูล PD-01","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":430,"law_id":100,"seq":1,"text":"ให้แผนก IT ระบุ Licensed ของ Software ที่ติดตั้งลงในเครื่องคอมพิวเตอร์ที่ให้บริการแก่   Co-Location","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":431,"law_id":100,"seq":2,"text":"กำหนดกฎระเบียบความปลอดภัยของข้อมูลสารสนเทศ (P-02)  ห้ามใช้ Software ที่ละเมิดลิขสิทธิ์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":432,"law_id":100,"seq":3,"text":"กำหนดให้เครื่องคอมพิวเตอร์ที่ใช้ในงาน O&M ไม่สามารถติดตั้ง Software โดยไม่ได้รับอนุญาต","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":447,"law_id":106,"seq":0,"text":"จัดมาตรการ takedown notice เป็นลายลักษณ์อักษรเพื่อระงับการแพร่หลายหรือลบข้อมูลคอมพิวเตอร์ที่ผิดกฎหมายออกจากระบบคอมพิวเตอร์ที่อยู่ในความควบคุมดูแลของตน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":448,"law_id":106,"seq":1,"text":"กรณีมีการร้องเรียนจากผู้ร้องเรียนโดยตรง _ กำหนดระยะเวลาการนำข้อมูลผิดกฎหมายออกจากระบบ กรณีที่มีผู้ใช้บริการหรือบุคคลทั่วไปร้องเรียนเป็นไม่เกินกว่า 24 ชั่วโมง นับแต่ได้รับข้อร้องเรียน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":728,"law_id":84,"seq":6,"text":"3. กรณีที่มีการขนย้ายดินที่ขุดออกจากเขตก่อสร้าง ต้องจัดให้มีสถานที่เก็บกองดินที่จะขนย้ายที่เหมาะสมและต้องกำหนดมาตรการป้องกันอันตรายอันเกิดจากการเก็บกองดินนั้น รวมทั้งการฟุ้งกระจายของฝุ่นอันเกิดจากดินดังกล่าว\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":433,"law_id":103,"seq":0,"text":"จัดส่งแผนรักษา ความมั่นคงปลอดภัยไซเบอร์และแผนการคุ้มครองข้อมูลส่วนบุคคลตามข้อ  ๑๔  ของเงื่อนไข ในการอนุญาตให้สำนักงาน กสทช. พร้อมการนำส่งรายงานผลประกอบการประจำปี  ในปี   พ.ศ.  ๒๕๖๕","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":454,"law_id":111,"seq":0,"text":"ผู้ให้บริการโทรคมนาคมต้องเปิดเผยข้อมูลการลงทะเบียนผู้ใช้งานหรือข้อมูลจราจรทางคอมพิวเตอร์ตามคำสั่งของหน่วยงานผู้มีอำนาจหน้าที่ตามพระราชบัญญัตินี้ เท่าที่จำเป็น โดยการเปิดเผย การแลกเปลี่ยน การเข้าถึง การเก็บ การรวบรวม หรือการใช้ข้อมูลตามกฎหมายนี้จะไม่อยู่ภายใต้บังคับกฎหมายคุ้มครองข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":459,"law_id":115,"seq":0,"text":"การโอนข้อมูลส่วนบุคคลไปให้นิติบุคคลต่างประเทศที่อยู่ในเครือกิจการหรือธุรกิจเดียวกัน สามารกระทำได้ หากมีนโยบายในการคุ้มครองข้อมูลส่วนบุคคลในเครือกิจการหรือเครือธุรกิจเดียวกัน (binding corporate rules: \"BCR\") ที่ได้รับการรับรองและตรวจสอบจากสำนักงานคณะกรรมการคุ้มครองข้อมูลส่วนบุคคลแล้ว","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":467,"law_id":123,"seq":0,"text":"เป็นการสร้างมาตรฐานเกี่ยวกับการรักษาความมั่นคงปลอดภัยของระบบคลาวด์ โดยมีการเพิ่มนิยาม ดังต่อไปนี้\n\"บริการคลาวด์\" หมายความว่า กลุ่มของบริการคลาวด์ที่มีคุณสมบัติร่วมกันบางอย่าง โดยมีรูปแบบ ดังนี้\n(1) การให้บริการโครงสร้างพื้นฐานเป็นหลัก (Infrastructure as a Service) ประกอบด้วยระบบประมวลผลข้อมูล ระบบการจัดเก็บข้อมูล ระบบเครือข่าย และทรัพยากรอื่นๆ ที่เกี่ยวข้องกับระบบประมวลผล โดยผู้ใช้บริการไม่ต้องบริหารจัดการโครงสร้างพื้นฐานที่จำเป็นด้วยตนเอง\n(2) การให้บริการแพลตฟอร์ม (Platform as a Service) ประกอบด้วยระบบโปรแกรมงานคอมพิวเตอร์ ระบบฐานข้อมูล และระบบจัดการหรืองานบริการจากคอมพิวเตอร์ ผู้ใช้บริการสามารถพัฒนา ติดตั้ง แลัะปรับแต่งซอฟต์แวร์ได้ โดยไม่ต้องบริหารจัดการในส่วนที่เกี่ยวข้องกับโครงสร้างพื้นฐาน เครือข่าย ระบบปฏิบัติการ และระบบจัดการฐานข้อมูล\n(3) การให้บริการซอฟต์แวร์ (Software as a Service) ผู้ให้บริการจัดเตรียมซอฟต์แวร์สำเร็จรูปแล้ว โดยผู้ใช้บริการสามารถกำหนดค่าความต้องการ พารามิเตอร์ ปริมาณหน่วย ประมวลผลข้อมูล หน่วยเก็บข้อมูล และบริหารจัดการเพื่อให้ได้บริการตามวัตถุประสงค์ หรือ\n(4) การให้บริการตาม (1)-(3) หรือบริการอื่นตามที่สำนักงานประกาศกำหนด\n\"ผู้ให้บริการคลาวด์ (Cloud Service Provider : CSP)\" หมายความว่า หน่วยงานรัฐหรือเอกชนที่ทำให้บริการคลาวด์ใช้ได้กับผู้ใช้บริการคลาวด์\nทั้งนี้ ผู้ใช้บริการคลาวด์ หมายความถึง หน่วยงาน (รัฐ) ที่มีข้อตกลงอย่างเป็นทางการในการใช้บริการคลาวด์ที่ให้บริการโดยผู้ให้บริการคลาวด์\nหน่วยงานควบคุมหรือกำกับดูแลต้องจัดส่งผลสรุปรายงานการดำเนินการต่อสำนักงานภายใน 30 วันนับแต่วันที่ดำเนินการแล้วเสร็จ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":471,"law_id":127,"seq":0,"text":"มาตรฐานเลขที่ มอก. 60793 เล่ม 1 (32) – 2567 \n-\tมีจุดมุ่งหมายหลักเพื่อทดสอบเส้นใยแก้วทั้งที่ผลิตจากโรงงานหรือเส้นใยนำแสงที่ต่อมาถูกเคลือบเพิ่มเติม (tight buffered) ด้วยพอลิเมอร์ชนิดต่างๆ การทดสอบนี้สามารถใช้กับเส้นใยนำแสงทั้งหลังการผลิตหรือหลังจากเส้นใยนำแสงอยู่ในภาวะแวดล้อมต่างๆ แล้ว\n-\tสามารถใช้วิธีนี้กับเส้นใยนำแสงประเภท A1 ประเภท A2 ประเภท A3 ประเภทชั้น B และประเภทชั้น C ที่แก้วมีมิติระบุเป็น 125 µm\n-\tวัตถุประสงค์ของมาตรฐานนี้คือ กำหนดคุณลักษณะที่ต้องการสำหรับลักษณะเฉพาะทางกลเรื่องความสามารถในการลอกของสารเคลือบ การทดสอบนี้เพื่อหาปริมาณแรงที่ต้องใช้ในการลอกของสารเคลือบป้องกันออกจากเส้นใยนำแสงตามแนวยาว\n-\tการทดสอบนี้ไม่มีจุดมุ่งหมายเพื่อเพิ่มความแข็งแรงของเส้นใยนำแสงหลังลอกสารเคลือบรวมทั้งไม่มีเจตนาระบุภาวะที่ดีที่สุดในการลอกสารเคลือบ\n-\tการทดสอบนี้ออกแบบไว้สำหรับเส้นใยนำแสงที่มีการเคลือบพอลิเมอร์ ซึ่งมีเส้นผ่านศูนย์กลางภายนอกระบุอยู่ในช่วงพิสัย 200 µm ถึง 900 µm","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":434,"law_id":104,"seq":0,"text":"แผนรับมือภัยคุกคามไซเบอร์ต้องประกอบไปด้วยรายละเอียดในประกาศนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":451,"law_id":108,"seq":0,"text":"บริษัทฯ ในฐานะผู้ประมวลผลข้อมูลส่วนบุคคล (processor) ต้องจัดทำรายการกิจกรรมการประมวลผลข้อมูลส่วนบุคคล (ROPA) เป็นลายลักษณ์อักษร (ทางอิเล็กทรอนิกส์ก็ได้) โดยมีรายการต่อไปนี้\n(1) ชื่อและข้อมูลเกี่ยวกับผู้ประมวลผลข้อมูลส่วนบุคคล  และตัวแทน (ถ้ามี)\n(2) ชื่อและข้อมูลเกี่ยวกับผู้ควบคุมข้อมูลส่วนบุคคล และตัวแทน (ถ้ามี) \n(3) ชื่อและข้อมูลเกี่ยวกับ DPO  รวมถึงสถานที่ติดต่อและวิธีการติดต่อ\n(4) ประเภทหรือลักษณะของการเก็บรวบรวม  ใช้  หรือเปิดเผยข้อมูลส่วนบุคคล \nรวมถึงวัตถุประสงค์ของการเก็บรวบรวม  ใช้  หรือเปิดเผยข้อมูลส่วนบุคคล\n(5) ประเภทหน่วยงานที่ได้รับข้อมูลส่วนบุคคล  ในกรณีที่โอนข้อมูลส่วนบุคคลไปยังต่างประเทศ \n(6) คำอธิบายเกี่ยวกับมาตรการรักษาความมั่นคงปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":455,"law_id":112,"seq":0,"text":"กำหนดแนวทางปฏิบัติเกี่ยวกับการรายงานเหตุภัยคุกคามทางไซเบอร์ โดยกำหนดรายการข้อมูลที่ต้องแจ้งเป็นแบบฟอร์มตามเอกสารแนบท้ายประกาศ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":754,"law_id":89,"seq":5,"text":"6.  หากดำเนินการตามข้อ 6 แล้ว แต่ยังมีบรรยากาศอันตรายอยู่และจำเป็นต้องเข้าไปในที่อับอากาศ  ต้องให้บุคคลนั้นๆ สวมใส่หรือใช้อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่เหมาะสม และใช้อุปกรณ์การทำงานที่ปลอดภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":424,"law_id":94,"seq":2,"text":"(1) ร่วมหารือกับนายจ้างเพื่อจัดสวัสดิการแก่ลูกจ้าง \n(2) ห้คำปรึกษาหารือและเสนอแนะความเห็นแก่นายจ้างในการจัดสวัสดิการสำหรับลูกจ้าง \n(3) ตรวจตรา ควบคุม ดูแล การจัดสวัสดิการที่นายจ้างจัดให้แก่ลูกจ้าง \n(4)เสนอข้อคิดเห็นและแนวทางในการจัดสวัสดิการที่เป็นประโยชน์สำหรับลูกจ้างต่อคณะกรรมการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":425,"law_id":94,"seq":3,"text":"มาตรา 98 นายจ้างต้องจัดให้มีการประชุมหารือกับคณะกรรมการสวัสดิการในสถานประกอบกิจการอย่างน้อย 3 เดือน ต่อ  1 ครั้ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":426,"law_id":94,"seq":4,"text":"มาตรา 99 ให้นายจ้างปิดประกาศการจัดสวัสดิการตามกฎกระทรวงให้ลูกจ้างได้รับทราบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":427,"law_id":94,"seq":5,"text":"ข้อ 4 ให้นายจ้างจัดให้มีคณะกรรมการสวัสดิการภายใน 30 วัน นับตั้งแต่วันที่มีลูกจ้างครบ 50 คน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":428,"law_id":94,"seq":6,"text":"ข้อ 6","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":435,"law_id":105,"seq":0,"text":"(1) มาตรการรักษาความมั่นคงปลอดภัยดังกล่าว จะต้องครอบคลุมการเก็บรวบรวม ใช้\nและเปิดเผยข้อมูลส่วนบุคคล ตามกฎหมายว่าด้วยการคุ้มครองข้อมูลส่วนบุคคล ไม่ว่าข้อมูลส่วนบุคคลดังกล่าวจะอยู่ในรูปแบบเอกสารหรือในรูปแบบอิเล็กทรอนิกส์ หรือรูปแบบอื่นใดก็ตาม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":436,"law_id":105,"seq":1,"text":"(2) มาตรการรักษาความมั่นคงปลอดภัยดังกล่าว จะต้องประกอบด้วยมาตรการเชิงองค์กร\n(organizational measures) และมาตรการเชิงเทคนิค (technical measures) ที่เหมาะสม ซึ่งอาจ\nรวมถึงมาตรการทางกายภาพ (physical measures) ที่จำเป็นด้วย โดยคำนึงถึงระดับความเสี่ยง\nตามลักษณะและวัตถุประสงค์ของการเก็บรวบรวม ใช้ และเปิดเผยข้อมูลส่วนบุคคล ตลอดจนโอกาสเกิดและผลกระทบจากเหตุการละเมิดข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":437,"law_id":105,"seq":2,"text":"(3) มาตรการรักษาความมั่นคงปลอดภัย ระบุความเสี่ยงที่สำคัญที่อาจจะเกิดขึ้นกับทรัพย์สินสารสนเทศ (information assets) ที่สำคัญการป้องกันความเสี่ยงที่สำคัญที่อาจจะเกิดขึ้น การตรวจสอบและเฝ้าระวังภัยคุกคามและเหตุการละเมิดข้อมูลส่วนบุคคล การเผชิญเหตุเมื่อมีการตรวจพบภัยคุกคามและเหตุการละเมิดข้อมูลส่วนบุคคล และการรักษาและฟื้นฟูความเสียหายที่เกิดจากภัยคุกคามหรือเหตุการละเมิดข้อมูลส่วนบุคคลด้วย ทั้งนี้ เท่าที่จำเป็นเหมาะสม และเป็นไปได้ตามระดับความเสี่ยง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":438,"law_id":105,"seq":3,"text":"(4) มาตรการรักษาความมั่นคงปลอดภัยดังกล่าว จะต้องคำนึงถึงความสามารถในการธำรงไว้\nซึ่งความลับ (confidentiality) ความถูกต้องครบถ้วน (integrity) และสภาพพร้อมใช้งาน (availability)ของข้อมูลส่วนบุคคลไว้ได้อย่างเหมาะสมตามระดับความเสี่ยง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":439,"law_id":105,"seq":4,"text":"(5) สำหรับการเก็บรวบรวม ใช้ และเปิดเผยข้อมูลส่วนบุคคลในรูปแบบอิเล็กทรอนิกส์\nมาตรการรักษาความมั่นคงปลอดภัย จะต้องครอบคลุมส่วนประกอบต่างๆ ของระบบ\nสารสนเทศที่เกี่ยวข้องกับการเก็บรวบรวม ใช้ และเปิดเผยข้อมูลส่วนบุคคล เช่น ระบบแลอุปกรณ์จัดเก็บข้อมูลส่วนบุคคล เครื่องคอมพิวเตอร์แม่ข่าย(servers) เครื่องคอมพิวเตอร์ลูกข่าย(clients)และอุปกรณ์ต่างๆ ที่ใช้ ระบบเครือข่าย ซอฟต์แวร์และแอปพลิเคชัน อย่างเหมาะสมตามระดับความเสี่ยง โดยคำนึงถึงหลักการป้องกันเชิงลึก(defense in depth) ที่ควรประกอบด้วยมาตรการป้องกันหลายชั้น(multiple layers of security controls) เพื่อลดความเสี่ยงในกรณีที่มาตรการบางมาตรการมีข้อจ ากัดในการป้องกันความมั่นคงปลอดภัยในบางสถานการณ์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":729,"law_id":84,"seq":7,"text":"4. กรณีที่ลูกจ้างทำงานก่อสร้างบนพื้นต่างระดับที่มีความสูงตั้งแต่ 1.50 เมตรขึ้นไป ต้องจัดให้มีบันไดหรือทางลาดพร้อมทั้งติดตั้งราวกันตกตามมาตรฐานสมาคมวิศวกรรมสถานแห่งประเทศไทยฯ หรือมาตรการอื่นใดเพื่อความปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":440,"law_id":105,"seq":5,"text":"(ก) การควบคุมการเข้าถึงข้อมูลส่วนบุคคลและส่วนประกอบของระบบสารสนเทศที่สำคัญ (access control) ที่มีการพิสูจน์และยืนยันตัวตน (identity proofing and authentication) และการอนุญาตหรือการกำหนดสิทธิในการเข้าถึงและใช้งาน(authorization) ที่เหมาะสม โดยคำนึงถึงหลักการให้สิทธิเท่าที่จำเป็น (need-to-know basis) ตามหลักการให้สิทธิที่น้อยที่สุดเท่าที่จำเป็น(principle of least privilege)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":441,"law_id":105,"seq":6,"text":"(ข) การบริหารจัดการการเข้าถึงของผู้ใช้งาน (user access management) ที่เหมาะสม\nซึ่งอาจรวมถึงการลงทะเบียนและการถอนสิทธิผู้ใช้งาน(user registration and de-registration)\nการจัดการสิทธิการเข้าถึงของผู้ใช้งาน(user access provisioning) การบริหารจัดการสิทธิการเข้าถึงตามสิทธิ (management of privileged access rights) การบริหารจัดการข้อมูลความลับสำหรับการพิสูจน์ตัวตนของผู้ใช้งาน (management of secret authentication information of users)การทบทวนสิทธิการเข้าถึงของผู้ใช้งาน (review of user access rights) และการถอดถอนหรือปรับปรุงสิทธิการเข้าถึง (removal or adjustment of access rights)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":442,"law_id":105,"seq":7,"text":"(ค) การกำหนดหน้าที่ความรับผิดชอบของผู้ใช้งาน (user responsibilities) เพื่อป้องกัน\nการเข้าถึง ใช้ เปลี่ยนแปลง แก้ไข ลบ หรือเปิดเผยข้อมูลส่วนบุคคลโดยปราศจากอำนาจหรือโดยมิชอบซึ่งรวมถึงกรณีที่เป็นการกระท านอกเหนือบทบาทหน้าที่ที่ได้รับมอบหมาย ตลอดจนการลักลอบทำสำเนาข้อมูลส่วนบุคคลโดยปราศจากอำนาจหรือโดยมิชอบ และการลักขโมยอุปกรณ์จัดเก็บหรือประมวลผลข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":443,"law_id":105,"seq":8,"text":"(ง) การจัดให้มีวิธีการเพื่อให้สามารถตรวจสอบย้อนหลังเกี่ยวกับการเข้าถึง เปลี่ยนแปลง\nแก้ไข หรือลบข้อมูลส่วนบุคคล (audit trails) ที่เหมาะสมกับวิธีการและสื่อที่ใช้ในการเก็บรวบรวม ใช้หรือเปิดเผยข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":444,"law_id":105,"seq":9,"text":"(7) ต้องรวมถึงการสร้างเสริมความตระหนักรู้ด้านความสำคัญของการคุ้มครองข้อมูลส่วนบุคคลและการรักษาความมั่นคงปลอดภัย (privacy and security awareness)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":445,"law_id":105,"seq":10,"text":"ข้อ 5 ผู้ควบคุมข้อมูลส่วนบุคคลต้องทบทวนมาตรการรักษาความมั่นคงปลอดภัยตามข้อ 4 เมื่อมีความจำเป็นหรือเมื่อเทคโนโลยีเปลี่ยนแปลงไป","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":446,"law_id":105,"seq":11,"text":"ข้อ 6 ในการจัดให้มีข้อตกลงระหว่างผู้ควบคุมข้อมูลส่วนบุคคลและผู้ประมวลผลข้อมูล\nส่วนบุคคล ให้ผู้ควบคุมข้อมูลส่วนบุคคลพิจารณากำหนดให้ผู้ประมวลผลข้อมูลส่วนบุคคลจัดให้มาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสม เพื่อป้องกันการสูญหาย เข้าถึง ใช้ เปลี่ยนแปลงแก้ไข หรือเปิดเผยข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":484,"law_id":102,"seq":0,"text":"ผู้ให้บริการต้องจัดให้มีระบบการพิสูจน์และยืนยันตัวตนทางดิจิทัลสาหรับผู้ใช้บริการทุกคน\nโดยใช้เทคโนโลยีที่สอดคล้องกับเงื่อนไขและมาตรฐานขั้นต่าในระดับความน่าเชื่อถือและสื่ออิเล็กทรอนิกส์ที่ใช้ยืนยันตัวตนตามที่สานักงานพัฒนาธุรกรรมทางอิเล็กทรอนิกส์กาหนดในหมวด ๓/๑ เรื่องระบบการพิสูจน์ยืนยันตัวตนทางดิจิทัลของพระราชบัญญัติว่าด้วยธุรกรรมทางอิเล็กทรอนิกส์ พ.ศ. ๒๕๔๔","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":449,"law_id":106,"seq":2,"text":"กรณีมีคำสั่งจากเจ้าหน้าที่ _ กำหนดระยะเวลาการในการระงับการทำให้แพร่หลายหรือนำข้อมูลออกจากระบบคอมพิวเตอร์ โดยหลักจะต้องทำทันที เว้นแต่มีเหตุสุดวิสัย ให้ดำเนินการภายหลังเหตุสิ้นสุด แต่ต้องไม่เกินระยะเวลาดังนี้\n- ข้อมูลทุจริต หรือ หลอกลวง ประเภท 1  ไม่เกิน 7 วันนับแต่ได้รับคำสั่ง\n- ข้อมูลกระทบต่อความมั่นคง ประเภท 2 3  ไม่เกิน 24 ชั่วโมงนับแต่ได้รับคำสั่ง\n- ข้อมูลที่มีลักษณะลามก ประเภท 4  ไม่เกิน 3 วัน นับแต่ได้รับคำสั่ง\n- ข้อมูลที่เป็นภาพลามกอนาจารเด็ก  ไม่เกิน 24 ชั่วโมงนับแต่ได้รับคำสั่ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":457,"law_id":114,"seq":0,"text":"1. การส่งข้อมูลส่วนบุคคลไปยังต่างประเทศ มีเงื่อนไขว่าประเทศปลายทางต้องมีมาตรฐานการคุ้มครองข้อมูลส่วนบุคคลที่เพียงพอตามข้อ 5 แห่งประกาศ กล่าวคือ \n(1) ประเทศปลายทาง (ผู้รับโอนข้อมูล) ต้องมีมาตรการหรือกลไกทางกฎหมายที่สอดคล้องกับ PDPA ของไทย โดยอย่างน้อยที่สุด \n- มีการกำหนดหน้าที่ในการรักษาความมั่นคงปลอดภัย\n- มีกลไกบังคับตามสิทธิและเยียวยาเจ้าของข้อมูล\n(2) มีหน่วยงานหรือองค์กรบังคับใช้กฎหมาย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":458,"law_id":114,"seq":1,"text":"2. ข้อยกเว้นการส่งข้อมูลส่วนบุคคลไปยังต่างประเทศได้ แม้ประเทศปลายทางมีมาตรฐานการคุ้มครองข้อมูลส่วนบุคคลไม่เพียงพอ\n(1) เป็นการปฏิบัติตามกฎหมาย\n(2) ได้รับความยินยอมจากเจ้าของข้อมูล\n(3) เป็นการปฏิบัติตามสัญญา","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":462,"law_id":118,"seq":0,"text":"กำหนดคุณลักษณะของข้อมูล/ระบบสารสนเทศ โดยพิจารณาตาม CIA (วัตถุประสงค์ด้านความมั่นคงปลอดภัยไซเบอร์) และระดับผลกระทบ แบ่งเป็น (1) ระดับต่ำ (2) ระดับกลาง (3) ระดับสูง โดยพิจารณาผลกระทบในด้าน\n- ความเสียหายทางการเงิน ทรัพย์สิน ชื่อเสียง\n- จำนวนผู้ใช้บริการ บุคลากร หรือประชาชนที่จะได้รับความเสียหาย\n- ผลกระทบต่อการดำเนินงานของหน่วยงาน\n- ผลกระทบต่อความมั่นคงและความสงบเรียบร้อยของประเทศ\nหมายเหตุ: ให้มีการทบทวนทุก 3 ปี เป็นอย่างน้อย หรือเมื่อข้อมูล/ระบบสารสนเทศหรือหน้าที่ของหน่วยงานเปลี่ยนแปลงอย่างมีนัยสำคัญ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":470,"law_id":126,"seq":0,"text":"มาตรฐานเลขที่ มอก. 60793 เล่ม  1 (31) - 2567\n-\tระบุค่าความต้านแรงดึงภายใต้การโหลดเชิงพลวัติของตัวอย่างเส้นใยนำแสง โดยวิธีนี้จะทดสอบความยาวแต่ละส่วนของเส้นใยนำแสงที่ไม่เป็นสายเคเบิ้ลและไม่เป็นกลุ่มเส้นใยนำแสง การทำให้เส้นใยนำแสงเสียหายเกิดจากการควบคุมการเพิ่มขึ้นของค่าความเค้นและความเครียดอย่างสม่ำเสมอตลอดความยาวเส้นใยและส่วนหน้าตัด ค่าความเค้นและค่าความเครียดจะเพิ่มขึ้นในอัตราคงที่จนกระทั่งเส้นใยขาด\n-\tการกระจายของค่าความต้านแรงดึงของเส้นใยนำแสงที่ให้ไว้ขึ้นอยู่กับความยาวของตัวอย่างทดสอบ ความเร็วของโหลด และภาวะแวดล้อม การทดสอบสามารถใช้ตรวจสอบหากต้องการข้อมูลทางสถิติของความแข็งแรงเส้นใย ผลการทดสอบให้รายงานในรูปแบบของการกระจายเชิงสถิติของการควบคุมคุณภาพ โดยปกติควรดำเนินการทดสอบหลังการปรับสภาวะอุณหภูมิและความชื้นของตัวอย่างทดสอบ อย่างไรก็ตามบางกรณีอาจทำการทดสอบภายใต้ภาวะอุณหภูมิและความชื้นโดยรอบก็ได้\n-\tสามารถใช้วิธีนี้กับเส้นใยนำแสงประเภท A1 ประเภท A2 ประเภท A3 ประเภทชั้น B และประเภทชั้น C\n-\tวัตถุประสงค์ของมาตรฐานนี้คือ กำหนดคุณลักษณะที่ต้องการสำหรับลักษณะเฉพาะทางกลเรื่องความต้านแรงดึง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":474,"law_id":96,"seq":0,"text":"แต่งตั้ง Data Protection Officer","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":475,"law_id":96,"seq":1,"text":"จัดนโยบายข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":476,"law_id":96,"seq":2,"text":"จัดแก้ไขเพิ่มเติมสัญญามาตรฐานให้สอดคล้องกฎหมายข้อมูลส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":477,"law_id":96,"seq":3,"text":"สร้างความตระหนักรู้ในกฎหมายดังกล่าวต่อคนในองค์กร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":461,"law_id":117,"seq":0,"text":"ผู้ให้บริการด้านการรักษาความมั่นคงปลอดภัยไซเบอร์ สามารถขอการรับรองคุณภาพบริการได้ \nโดยแบ่งเป็น 3 ระดับ คือ ขั้นต้น ขั้นก้าวหน้า ขั้นสูง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":465,"law_id":121,"seq":0,"text":"กำหนดหน้าที่ของหน่วยงานโครงสร้างพื้นฐานสำคัญทางสารสนเทศ (ข้อ 4)\n(1) ป้องกัน รับมือ ลดความเสี่ยงจากภัยคุกคามไซเบอร์\n(2) จัดทำเอกสาร\n- ประมวลแนวทางปฏิบัติ: แผนการตรวจสอบด้านการรักษาความมั่นคงปลอดภัยไซเบอร์ + การประเมินความเสี่ยง + แผนการรับมือภัยคุกคามไซเบอร์\n- กรอบมาตรฐานการรักษาความมั่นคงปลอดภัยไซเบอร์: การระบุความเสี่ยง มาตรการป้องกัน มาตรการตรวจสอบเฝ้าระวัง มาตรการเผชิญเหตุ มาตรการรักษาและฟื้นฟูความเสียหาย\n(3) ทวนเอกสารปีละ 1 ครั้ง หรือเมื่อมีการเปลี่ยนแปลงอย่างมีนัยสำคัญ\n(4) ให้ความร่วมมือและมีส่วนร่วมในการฝึกซ้อมรับมือภัยคุกคาม\n(5) แจ้งรายชื่อเจ้าหน้าที่ระดับบริหารและระดับปฏิบัติการ พร้อมด้วยข้อมูลการติดต่อที่สามารถติดต่อได้ในกรณีมีเหตุฉุกเฉินภายในระยะเวลา 60 นาที (หากมีการเปลี่ยนแปลง ต้องแจ้งภายใน 15 วัน นับแต่เปลี่ยนแปลง)\n(6) แจ้งรายชื่อหน่วยงานภายในหรือบุคคลที่เป็นเจ้าของกรรมสิทธิ์ ผู้ครอบครองคอมพิวเตอร์\nและผู้ดูแลระบบคอมพิวเตอร์ พร้อมด้วยข้อมูลการติดต่อที่สามารถติดต่อในกรณีมีเหตุฉุกเฉินภายในระยะเวลา 60 นาที (หากมีการเปลี่ยนแปลง ต้องแจ้งภายใน 7 วัน นับแต่เปลี่ยนแปลง เว้นแต่มีเหตุจำเป็นอันมิอาจก้าวล่วงได้ ให้แจ้งภายใน 15 วัน)\n(7)-(8) ดำเนินการตามนโยบายบริหารจัดการที่เกี่ยวกับการรักษาความมั่นคงปลอดภัยไซเบอร์ และทบทวนอย่างน้อยปีละครั้ง\n(9) จัดให้มีการประเมินความเสี่ยงด้านการรักษาความมั่นคงปลอดภัยไซเบอร์ อย่างน้อยปีละครั้ง และจัดทำผลสรุปรายงานการดำเนินการ (แยกต่างหาก) และส่งสรุปรายงานการดำเนินการภายใน 30 วัน นับแต่ดำเนินการเสร็จ แต่ไม่เกินวันที่ 31 มกราคม ของปีถัดไป\n(10) จัดให้มีการตรวจสอบด้านความมั่นคงปลอดภัยไซเบอร์ อย่างน้อยปีละครั้ง และจัดทำผลสรุปรายงานการดำเนินการ (แยก","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":469,"law_id":125,"seq":0,"text":"มาตรฐานเลขที่ มอก. 60793 เล่ม 1 (1) - 2567\n-\tระบุรายการและให้ข้อแนะนำในการใช้เอกสารที่ระบุคุณลักษณะที่ต้องสำหรับการวัดและทดสอบเส้นใยนำแสง ซึ่งจะช่วยในการตรวจสอบเส้นใยนำแสงและเคเบิ้ลเพื่อจุดประสงค์เชิงพาณิชย์\n-\tวิธีการวัดและทดสอบแต่ละวิธีจะอธิบายไว้ในเล่มต่างๆ ของอนุกรม IEC 60793 โดยมีการระบุตาม IEC 60793-1-X โดยที่ X จะเป็นหมายเลขที่ระบุถึงเอกสารเล่มย่อยต่างๆ ในอนุกรม IEC 60793-1\n-\tโดยทั่วไปวิธีการวัดและทดสอบใช้ได้กับเส้นใยนำแสงแบบหลายโหมด ทุกประเภท A และเส้นใยนำแสงแบบโหมดเดี่ยวประเภทชั้น B และประเภทชั้น C ซึ่งครอบคลุมตามอนุกรม IEC 60793-2 ที่เกี่ยวกับข้อกำหนดคุณลักษณะผลิตภัณฑ์แต่อาจมีข้อยกเว้นในบางกรณี ในข้อ 1. ของแต่ละเล่มในอนุกรม IEC 60793 กล่าวถึงขอบข่ายสำหรับแต่ละคุณลักษณะเฉพาะตัวไว้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":473,"law_id":95,"seq":0,"text":"สำหรับกิจการที่มีโครงข่ายที่ไม่มีการใช้คลื่นความถี่ในการให้บริการกำหนดให้มีวิศวกรควบคุมงาน 1 คน\n“วิศวกรควบคุมงาน” หมายความว่า วิศวกรผู้รับผิดชอบงานด้านการกากับดูแลการดำเนินบริการโทรคมนาคม การออกแบบและควบคุมการติดตั้ง ควบคุมการตรวจสอบและสั่งการแก้ไขความเสียหายของโครงข่ายโทรคมนาคมทั้งหมด และหน้าที่ที่เกี่ยวข้องอื่นใดโดยปฏิบัติหน้าที่ประจาศูนย์ปฏิบัติการโครงข่าย (Network Operation Center)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":482,"law_id":99,"seq":0,"text":"เมื่อได้รับคำสั่งให้ระงับการทำให้แพร่หลายของข้อมูล ต้องดำเนินการระงับในทันทีหรือต้องไม่เกินกว่าระยะเวลาที่ระบุในคำสั่ง เว้นแต่มีเหตุสมควรที่เจ้าพนักงานสั่งได้ ทั้งนี้ห้ามเกิน 15 วัน ในการระงับนี้ ให้ดำเนินการด้วยมาตรการทางเทคนิคใดๆ (Technical Measure) ที่ได้มาตรฐาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":493,"law_id":131,"seq":0,"text":"เดิมกฎหมายกำหนดให้คนต่างด้าวต้องมารับใบอนุญาตทำงานที่นายทะเบียนออกให้ด้วยตัวเองเท่านั้น แต่กฎหมายฉบับนี้แก้ไขให้คนต่างด้าวจะมารับด้วยตนเองก็ได้ หรือโดยวิธีการอื่นตามที่อธิบดีประกาศกำหนดก็ได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":382,"law_id":84,"seq":8,"text":"5. นายจ้างต้องไม่ให้ลูกจ้างทำงานก่อสร้างในขณะที่เกิดภัยธรรมชาติ หรือมีเหตุอื่นใดที่อาจจะทำให้เกิดความไม่ปลอดภัยในการทำงานของลูกจ้าง  \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":472,"law_id":128,"seq":0,"text":"มาตรฐานเลขที่ มอก. 60793 เล่ม 1 (34) – 2567\n-\tกำหนดคุณลักษณะที่ต้องการสำหรับลักษณะเฉพาะทางกลเรื่องความคดเส้นใยหรือความคดแฝงในเส้นใยที่ไม่มีการเคลือบ เช่น ความยาวที่ระบุของเส้นใยที่ลอกสารเคลือบออกแล้ว ความคดเส้นใยเป็นพารามิเตอร์ที่สำคัญสำหรับการลดความสูญเสียของการเชื่อมเส้นใยนำแสง (splicing) เมื่อใช้เครื่องเชื่อมเส้นใยนำแสงแบบพาสซีฟ (passive alignment fusion splicer)\n-\tวิธีการวัดที่ใช้ในการวัดความคดเส้นใยในเส้นใยที่ไม่มีการเคลือบมี 2 วิธี คือ\no\tวิธี A : การใช้กล้องจุลทรรศน์แบบมุมมองด้านข้าง (side view microscopy)\no\tวิธี B : การกระเจิงของลำแสงแลเซอร์ (laser beam scattering)\n-\tวิธีการวัดทั้งสองวิธีใช้วัดรัศมีความคดของเส้นใยที่ไม่มีการเคลือบ ซึ่งหากได้จากค่าความเบี่ยงเบนที่เกิดขึ้นตรงจุดปลายเส้นใยนำแสงที่หมุนรอบแกนของเส้นใยนำแสงอย่างอิสระ วิธี A ใช้วีดิทัศน์แบบภาพหรือแบบดิจิทัลเพื่อหาความเบี่ยงเบนของเส้นใย ในขณะที่วิธี B ใช้เซนเซอร์แบบตรวจจับเส้นเพื่อวัดความเบี่ยงเบนสูงสุดของลำแสงเลเซอร์เทียบกับลำแสงเลเซอร์อ้างอิง\n-\tจากการวัดพฤติกรรมการเบี่ยงเบนของเส้นใยขณะหมุนรอบแกนของเส้นใยนำแสงและการพิจารณารูปร่างเรขาคณิตของอุปกรณ์วัดพบว่า รัศมีความคดของเส้นใยสามารถคำนวณได้จากแบบจำลองทรงอย่างง่ายซึ่งการเบี่ยงเบนให้ไว้ในภาคผนวก C\n-\tวิธีการวัดทั้งสองวิธีสามารถใช้ได้กับเส้นใยนำแสงประเภทชั้น B ตามที่อธิบายไว้ใน IEC 60793 (ทุกเล่ม)\n-\tวิธี A ใช้เป็นวิธีทดสอบอ้างอิงซึ่งใช้แก้ไขข้อพิพาท","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":480,"law_id":98,"seq":0,"text":"บริษัทต้องเก็บรักษาข้อมูลจราจรคอมพิวเตอร์ไว้ไม่น้อยกว่า 90 วันนับแต่วันที่ข้อมูลนั้นเข้าสู่ระบบคอมพิวเตอร์","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":481,"law_id":98,"seq":1,"text":"บริษัทจะต้องเก็บรักษาข้อมูลของผู้ใช้บริการเท่าที่จําเป็นเพื่อให้สามารถระบุตัวผู้ใช้บริการนับตั้งแต่เริ่มใช้บริการและต้องเก็บรักษาไว้เป็นเวลาไม่น้อยกว่า 90 วันนับตั้งแต่การใช้บริการสิ้นสุดลง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":520,"law_id":151,"seq":0,"text":"ข้อ 3 เพิ่ม “โรคติดเชื้อไวรัสฮันตา (Hantavirus Disease)” เป็นลำดับที่ 14 ของโรคติดต่ออันตราย\n\nอาการสำคัญของโรคติดเชื้อไวรัสฮันตา\nมีอาการไข้ หนาวสั่น ปวดศีรษะ ปวดกล้ามเนื้อ อ่อนเพลีย และอาจมีอาการทางระบบทางเดินอาหาร เช่น ปวดท้อง คลื่นไส้ อาเจียน หรือถ่ายเหลว\n\nอาการรุนแรงของโรค\nในรายที่มีอาการรุนแรง อาจมีไอ หายใจลำบาก ปอดอักเสบ มีของเหลวคั่งในปอด ช็อก ความดันโลหิตต่ำ เลือดออกจากส่วนต่าง ๆ ของร่างกาย ไตวายเฉียบพลัน ระบบทางเดินหายใจล้มเหลว และอาจเสียชีวิต","status":"met","responsible":"Safety","frequency":"ปีละ 1 ครั้ง หรือเมื่อมีการเปลี่ยนแปลงพื้นที่ / พบการระบาด / พบหนูในพื้นที่","documents":"- Risk Assessment,\n- รายงานผลการทบทวนแผนและซ้อมแผน\n- ใช้ร่วมกับแผนรับมือโรคระบาดหรือโรคติดต่ออื่น","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":730,"law_id":84,"seq":9,"text":"6. นายจ้างต้องติดตั้งป้าย ดังนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":485,"law_id":102,"seq":1,"text":"ผู้ให้บริการต้องจัดให้มีมาตรการรักษาความมั่นคงปลอดภัยของข้อมูลในระบบการพิสูจน์และยืนยันตัวตนซึ่งควรครอบคลุมถึงมาตรการป้องกันด้านการบริหารจัดการ (administrative safeguard) มาตรการป้องกันด้านเทคนิค (technical safeguard)และมาตรการป้องกันทางกายภาพ (physical safeguard) ในเรื่องการเข้าถึงหรือควบคุมการใช้งานข้อมูลในระบบการพิสูจน์และยืนยันตัวตน (access control)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":486,"law_id":102,"seq":2,"text":"การเก็บรักษาข้อมูลจราจรทางคอมพิวเตอร์ ผู้ให้บริการต้องใช้วิธีการที่มั่นคงปลอดภัย ตามรายละเอียดของกฎหมาย ข้อ 9","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":487,"law_id":102,"seq":3,"text":"ผู้ให้บริการยังคงมีหน้าที่ตามกฎหมายที่ต้องเก็บรักษาทำสำเนาข้อมูลจราจรคอมพิวเตอร์ และครอบครองไว้ซึ่งข้อมูลสำเนาที่เกี่ยวข้องกับข้อมูลจราจรคอมพิวเตอร์ซึ่งสามารถระบุตัวตนได้ กรณีที่ผู้ให้บริการมีข้อตกลง สัญญา หรือมีการว่าจ้างบุคคลภายนอกที่ไม่ใช่ผู้ให้บริการให้ทาหน้าที่หรือเกี่ยวข้องกับการเก็บรักษาข้อมูลจราจรคอมพิวเตอร์แทนหน้าที่ของตนเอง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":488,"law_id":102,"seq":4,"text":"ผู้ให้บริการต้องตั้งนาฬิกาของอุปกรณ์บริการทุกชนิดให้ตรงกับเวลาอ้างอิงสากล (Stratum 0) ให้ตรงกับอุปกรณ์คอมพิวเตอร์ที่เกี่ยวข้อง (Clock Synchronization) และมาตรฐานการเก็บรักษาข้อมูลจราจรคอมพิวเตอร์ต้องเป็นไปตามมาตรฐานสากลตามที่กาหนดไว้ในภาคผนวกท้ายประกาศฉบับนี้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":489,"law_id":102,"seq":5,"text":"ผู้ให้บริการต้องเก็บรักษาข้อมูลจราจรคอมพิวเตอร์ตามกำหนดระยะเวลา ดังต่อไปนี้\n(๑) กรณีทั่วไป ให้ผู้ให้บริการเก็บรักษาข้อมูลจราจรคอมพิวเตอร์ไว้ไม่น้อยกว่าเก้าสิบวัน\nนับแต่วันที่ข้อมูลนั้นเข้าสู่ระบบคอมพิวเตอร์\n(2) กรณีพนักงานเจ้าหน้าที่มีคำสั่งให้ผู้ให้บริการผู้ใดเก็บรักษาข้อมูลจราจรคอมพิวเตอร์ของผู้ใช้บริการเป็นกรณีพิเศษเฉพาะรายต่อไปอีกคราวละไม่เกินหกเดือนต่อเนื่องกัน แต่ต้องไม่เกินสองปี\nหมายเหตุ: ข้อมูลจราจรคอมพิวเตอร์ให้จัดเก็บตามภาคผนวก ข แนบท้ายประกาศกระทรวงดิจิทัลเพื่อเศรษฐกิจและสังคม เรื่อง หลักเกณฑ์การเก็บรักษาข้อมูลจราจรทางคอมพิวเตอร์ของผู้ให้บริการ พ.ศ. ๒๕๖๔","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":521,"law_id":152,"seq":0,"text":"ผู้รับใบอนุญาตที่ให้บริการโทรคมนาคมระหว่างประเทศ ต้องไม่นำ IP Address ที่จดทะเบียนในไทยไปให้บริการในต่างประเทศ","status":"met","responsible":"Legal / Sales","frequency":"เมื่อมีการซื้อขาย","documents":"WI-76 การปฎิบัติกรณีรับเอกสารระงับ IP Address Rev.1","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":513,"law_id":148,"seq":0,"text":"ข้อ 2 แบบคำขอรับใบอนุญาต ใบแทนใบอนุญาต หรือการต่ออายุใบอนุญาตเป็นผู้ชำนาญการฯ ต้องเป็นไปตามแบบ กภ.คบญ.33 ท้ายประกาศ","status":"unmet","responsible":"Safety","frequency":"ปีละ 1 ครั้ง และเมื่อกฎหมายเปลี่ยนแปลง","documents":"- แบบ กภ.คบญ.33, สำเนาบัตรประชาชน, เอกสารคุณสมบัติ, \n- หลักฐานการยื่นคำขอย","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":514,"law_id":148,"seq":1,"text":"ข้อ 3 ใบรับคำขอเป็นผู้ชำนาญการฯ ต้องเป็นไปตามแบบ กภ.รบญ.33 ท้ายประกาศ","status":"unmet","responsible":null,"frequency":null,"documents":"- ใบรับคำขอ กภ.รบญ.33\n- หลักฐานการยื่น, เลขรับคำขอ, Email หรือหลักฐานจากระบบราชการ  ระบบ e-Service","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":515,"law_id":148,"seq":2,"text":"ข้อ 4 ใบอนุญาตเป็นผู้ชำนาญการด้านความปลอดภัยฯ ต้องเป็นไปตามแบบ กภ.บญ.33-1 และ กภ.บญ.33-2 ท้ายประกาศ","status":"unmet","responsible":null,"frequency":"ปีละ 1 ครั้ง","documents":"- ใบอนุญาต กภ.บญ.33-1, กภ.บญ.33-2, \n- รายชื่อผู้ชำนาญการ","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":516,"law_id":148,"seq":3,"text":"ข้อ 5 ใบแทนใบอนุญาตเป็นผู้ชำนาญการฯ ต้องเป็นไปตามแบบ กภ.บทญ.33-1 และ กภ.บทญ.33-2 ท้ายประกาศ","status":"unmet","responsible":null,"frequency":"กรณีใบอนุญาตสูญหาย ชำรุด","documents":"- แบบคำขอ, ใบแทนใบอนุญาต, \n- หลักฐานการแจ้งสูญหายหรือชำรุด\n- ใบรับคำขอ","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":517,"law_id":149,"seq":0,"text":"ข้อ 2 ผู้ที่มีคุณสมบัติตามกฎกระทรวงและประสงค์ขอรับใบอนุญาต ต้องเข้ารับการฝึกอบรมหลักสูตรผู้ชำนาญการจากกรมสวัสดิการและคุ้มครองแรงงานหรือผู้ให้บริการฝึกอบรม เพื่อพัฒนาศักยภาพในการปฏิบัติหน้าที่ไม่น้อยกว่า 6 ชั่วโมงต่อปี และต้องผ่านเกณฑ์การประเมินโดยวิธีการทดสอบตามตารางแนบท้ายประกาศ","status":"unmet","responsible":"Safety","frequency":"เมื่อมีบุคลากรจะขอใบอนุญาต หรือทบทวนปีละ 1 ครั้ง","documents":"- รายชื่อบุคลากร,\n- แผนอบรม\n- หลักฐานการอบรม,\n- หลักฐานการประเมิน","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":518,"law_id":150,"seq":0,"text":"ข้อ 2 กำหนดให้แบบแจ้งกำหนดการ พร้อมรายชื่อสถานประกอบกิจการที่เข้าดำเนินการ และรายชื่อผู้ชำนาญการ ต้องเป็นไปตามแบบท้ายประกาศ","status":"unmet","responsible":"Safety","frequency":"ทุกครั้งก่อนการเข้าปฏิบัติงาน","documents":"- หลักฐานการส่งแบบแจ้ง, Email, ระบบ e-Serviceย","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":519,"law_id":150,"seq":1,"text":"ข้อ 3 กำหนดให้แบบรายงานสรุปผลการปฏิบัติงานของผู้ชำนาญการ ต้องเป็นไปตามแบบท้ายประกาศ","status":"unmet","responsible":null,"frequency":"ทุกครั้งหลังเสร็จสิ้นการปฏิบัติงาน","documents":"- หลักฐานการส่งรายงาน, Email, ใบนำส่ง, ระบบ e-Service ถ้ามี, รายงานฉบับสมบูรณ์","note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":183,"law_id":4,"seq":0,"text":"1. การแจ้งการเกิดอุบัติภัยร้ายแรง หรือลูกจ้างประสบอันตรายจากการทำงาน\nและการส่งสำเนาหนังสือแจ้งการประสบอันตรายหรือเจ็บป่วยต่อสำนักงานประกันสังคมตามกฎหมาย\nว่าด้วยเงินทดแทน ตามมาตรา ๓๔ แห่งพระราชบัญญัติความปลอดภัย อาชีวอนามัย และสภาพแวดล้อม\nในการทำงาน พ.ศ. ๒๕๕๔ นายจ้างอาจดำเนินการแจ้งหรือส่งโดยใช้แบบการแจ้งทางสื่ออิเล็กทรอนิกส์\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":645,"law_id":4,"seq":1,"text":"2. กรณีมีความประสงค์จะแจ้งการเกิดอุบัติภัยร้ายแรง หรือลูกจ้างประสบอันตราย\nจากการทำงาน และส่งสำเนาหนังสือแจ้งการประสบอันตรายหรือเจ็บป่วยต่อสำนักงานประกันสังคม\nตามกฎหมายว่าด้วยเงินทดแทนทางสื่ออิเล็กทรอนิกส์ตามข้อ ๓ ต้องลงทะเบียนเพื่อขอรหัสผู้ใช้ (User ID)\nและรหัสผ่าน (Password) ทางเว็บไซต์ของกรมสวัสดิการและคุ้มครองแรงงาน (http://eservice.labour.go.th)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":187,"law_id":6,"seq":0,"text":"สถานประกอบกิจการตามที่ระบุไว้ในบัญชีท้ายกฎกระทรวงนี้\nมีลูกจ้าง 50 คนขึ้นไปต้องจัดให้มีระบบการจัดการความปลอดภัย\nระบบการจัดการความปลอดภัย อย่างน้อยต้องประกอบด้วย\n1.  นโยบายด้านความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":646,"law_id":6,"seq":1,"text":"2.  การจัดองค์กรด้านความปลอดภัยฯ\n3.แผนงานด้านความปลอดภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":647,"law_id":6,"seq":2,"text":"4. การประเมินผลทบทวน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":648,"law_id":6,"seq":3,"text":"5. การปรับปรุงและพัฒนาระบบการจัดการด้านความปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":649,"law_id":14,"seq":1,"text":"2. งานที่อาจเป็นอันตรายต่อสุขภาพและความปลอดภัยของลูกจ้าง ได้แก่  \n(1) งานที่ต้องทำใต้ดิน ใต้น้ำ ในถ้ำ อุโมงค์ หรือในที่อับอากาศ  \n(3) งานเชื่อมโลหะ\n(6) งานที่ต้องทำด้วยเครื่องมือหรือเครื่องจักรซึ่งผู้ทำได้รับความสั่นสะเทือน อันอาจเป็นอันตราย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":650,"law_id":18,"seq":1,"text":"2. บทนิยาม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":651,"law_id":18,"seq":2,"text":"3. หลักการ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":652,"law_id":18,"seq":3,"text":"4. กรอบงาน\n ทั่วไป\n ข้อบังคับและความมุ่งมั่นของผู้บริหาร\n การกำหนดกรอบการบริหารความเสี่ยง\n การนำการบริหารความเสี่ยงไปปฏิบัติ\n การเฝ้าติดตามและการทบทวนกรอบการบริหารความเสี่ยง\n การปรับปรุงกรอบการบริหารความเสี่ยงอย่างต่อเนื่อง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":230,"law_id":18,"seq":4,"text":"5. กระบวนการ\n ทั่วไป\n การสื่อสารและการปรึกษา\n  การกำหนดบริบท\n  การประเมินความเสี่ยง\n  การจัดการความเสี่ยง\n  การติดตามตรวจสอบและการทบทวน\n  การบันทึกกระบวนการบริหารความเสี่ยง\nภาคผนวก ก. คุณลักษณะในการส่งเสริมการบริหารความเสี่ยง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":731,"law_id":84,"seq":10,"text":"1) ติดป้ายเตือนอันตราย สัญญาณแสงสีส้ม ณ ทางเข้าออกของยานพาหนะทุกแห่ง และจัดให้มีผู้ให้สัญญาณในขณะที่มียานพาหนะเข้าออกเขตก่อสร้าง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":240,"law_id":24,"seq":0,"text":"ให้นายจ้างนำรายชื่อ จป. ระดับหัวหน้างาน ระดับบริหาร ระดับเทคนิค ระดับเทคนิคขั้นสูง หรือระดับวิชาชีพ และผู้บริหารหน่วยงานความปลอดภัยไปแจ้งเพื่อขึ้นทะเบียนภายใน 30 วันนับแต่วันที่นายจ้างแต่งตั้งบุคคลดังกล่าว  พร้อมเอกสารหรือหลักฐานดังนี้\n     1) สำเนาเอกสารการแต่งตั้งเป็นเจ้าหน้าที่ความปลอดภัยในการทำงาน และผู้บริหารหน่วยงานความปลอดภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":653,"law_id":24,"seq":1,"text":"2) สำเนาใบรับรองผ่านการฝึกอบรมหลักสูตรเจ้าหน้าที่ความปลอดภัยในการทำงาน และผู้บริหารหน่วยงานความปลอดภัย หรือสำเนาวุฒิการศึกษาในกรณีที่มีคุณสมบัติโดยใช้วุฒิการศึกษา\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":654,"law_id":24,"seq":2,"text":"3) สำเนาหนังสือเดินทางหรือสำเนาใบอนุญาตทำงาน กรณีบุคคลซึ่งไม่มีสัญชาติไทย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":655,"law_id":24,"seq":3,"text":"4) สำเนาเอกสารหรือหลักฐานการขึ้นทะเบียน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":662,"law_id":38,"seq":1,"text":"2. โรคหรืออาการที่เกิดจากการสัมผัสฝุ่นละอองขนาดไม่เกิน 2.5 ไมครอน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":276,"law_id":40,"seq":0,"text":"1. กำหนดวิธีการทดสอบมาตรฐานฝีมือแรงงานแห่งชาติ สาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ \nสาขาช่างไฟฟ้าภายในอาคาร ระดับ 1 แบ่งเป็น\n     1.1 การทดสอบความรู้ ความเข้าใจ\n     1.2 การทดสอบความสามารถ\n      ส่วนรายละเอียดวิธีการทดสอบให้เป็นไปตามที่คณะกรรมการประกาศกำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":663,"law_id":40,"seq":1,"text":"2. การออกหนังสือรับรองว่าเป็นผู้ผ่านการทดสอบมาตรฐานฝีมือแรงงาน สาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ สาขาช่างไฟฟ้าภายในอาคาร ระดับ 1 จะออกให้แก่ผู้ผ่านการทดสอบทั้งภาคความรู้ ความเข้าใจ \nและภาคความสามารถ  โดยผู้เข้ารับการทดสอบต้องได้คะแนนไม่น้อยกว่าร้อยละ 70 ของคะแนนทั้งหมด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":664,"law_id":41,"seq":1,"text":"2. เอกสารอ้างอิง  \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":665,"law_id":41,"seq":2,"text":"3. บทนิยาม   \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":302,"law_id":51,"seq":0,"text":"1. กำหนดวิธีการทดสอบมาตรฐานฝีมือแรงงานแห่งชาติ สาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ \nสาขาช่างไฟฟ้าภายในอาคาร ระดับ 2 ดังนี้\n       (1) การทดสอบความรู้  โดยผู้เข้ารับการทดสอบต้องได้คะแนนไม่น้อยกว่าร้อยละ 60 ของคะแนนภาคความรู้ \n            จึงมีสิทธิเข้ารับการทดสอบภาคความสามารถ\n       (2) การทดสอบความสามารถ  \n       (3) รายละเอียดวิธีการทดสอบให้เป็นไปตามที่คณะกรรมการกำหนด \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":669,"law_id":51,"seq":1,"text":"\n2. การออกหนังสือรับรองว่าเป็นผู้ผ่านการทดสอบมาตรฐานฝีมือแรงงานแห่งชาติ สาขาอาชีพช่างไฟฟ้า อิเล็กทรอนิกส์และคอมพิวเตอร์ สาขาช่างไฟฟ้าภายในอาคาร ระดับ 2 จะออกให้แก่ผู้ผ่านการทดสอบทั้งภาคความรู้และภาคความสามารถ และต้องทดสอบได้คะแนนไม่น้อยกว่าร้อยละ 70 ของคะแนนทั้งหมด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":670,"law_id":52,"seq":1,"text":"9. (ข้อ 16) ห้ามเก็บภาชนะบรรจุน้ำมันไว้ต่ำกว่าระดับพื้นดิน เว้นแต่ภาชนะบรรจุน้ำมันนั้นเก็บน้ำมันชนิดไวไฟน้อยที่มีจุดวาบไฟเกิน 93 องศาเชลเซียสขึ้นไปและอยู่ภายในอาคาร\nส่วนที่ 2 ลักษณะของแผนผังและแบบก่อสร้าง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":671,"law_id":52,"seq":2,"text":"10. (ข้อ 17-19) สถานที่เก็บรักษาน้ำมัน ลักษณะที่สอง ต้องมีแผนผังและแบบก่อสร้างตามที่กำหนด \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":672,"law_id":52,"seq":3,"text":"1)\tต้องมีแผนผังโดยสังเขปแสดงตำแหน่งที่ตั้งของสถานที่เก็บรักษาน้ำมัน พร้อมสิ่งก่อสร้างต่างๆ โดยรอบ ในระยะไม่น้อยกว่า 50 เมตร\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":673,"law_id":52,"seq":4,"text":"2)\tต้องมีแผนผังบริเวณแสดงเขตสถานที่เก็บรักษาน้ำมัน ภาชนะบรรจุน้ำมัน แนวท่อน้ำมัน และอาคารเก็บภาชนะบรรจุน้ำมัน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":674,"law_id":52,"seq":5,"text":"3)\tกรณีถังเก็บน้ำมันขนาดใหญ่ที่มีปริมาณความจุเกิน 2,500 ลิตรขึ้นไป แบบก่อสร้างต้องมีรายละเอียดเพิ่มเติม เช่น แปลนส่วนบน แปลนส่วนราก แปลนฐานราก รายละเอียดการก่อสร้าง และการติดตั้ง เป็นต้น \nส่วนที่ 3 ถังเก็บน้ำมัน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":675,"law_id":52,"seq":6,"text":"11. (ข้อ 20-21) ถังเก็บน้ำมันใต้พื้นดินและเหนือพื้นดิน สำหรับสถานที่เก็บรักษาน้ำมัน ลักษณะที่สอง ต้องมีลักษณะ และวิธีการติดตั้งตามที่กฎกระทรวงนี้กำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":676,"law_id":52,"seq":7,"text":"\n12. (ข้อ 22) เมื่อติดตั้งถังเก็บน้ำมันใต้พื้นดินและเหนือพื้นดินแล้ว ต้องทำการทดสอบและตรวจสอบตามหลักเกณฑ์ และวิธีการที่รัฐมนตรีประกาศกำหนด และให้ทำการทดสอบและตรวจสอบถังเก็บน้ำมันทุก 1 ปีและ 10 ปีตามวิธีการ ที่กำหนดในกฎกระทรวงว่าด้วยการซ่อมบำรุงถังเก็บน้ำมันและถังขนส่งน้ำมันที่ออกตามมาตรา 7","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":308,"law_id":55,"seq":0,"text":"หมวด 3\nสถานที่เก็บรักษาน้ำมันเชื้อเพลิง ลักษณะที่สอง\nส่วนที่ 1 การเก็บน้ำมันเชื้อเพลิงและระยะปลอดภัยภายใน\nข้อ 14 การเก็บภาชนะบรรจุน้ำมันเชื้อเพลิงไว้ในอาคารต้องมีระยะปลอดภัยตามที่กำหนดไว้ในตารางที่ 1\nตารางที่ 1 ระยะปลอดภัยในการเก็บภาชนะบรรจุน้ำมันเชื้อเพลิงไว้ในอาคาร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":310,"law_id":55,"seq":2,"text":"ข้อ 16 การเก็บภาชนะบรรจุน้ำมันเชื้อเพลิงให้ปฏิบัติตามที่กำหนดไว้ในข้อ 7 \n    ข้อ 7 ห้ามเก็บภาชนะบรรจุน้ำมันเชื้อเพลิงไว้ต่ำกว่าระดับพื้นดิน เว้นแต่เก็บอยู่ภายในอาคารที่มีพื้นที่ต่ำกว่าระดับพื้นดิน และภาชนะบรรจุน้ำมันเชื้อเพลิงดังกล่าวเก็บน้ำมันเชื้อเพลิงชนิดไวไฟน้อยที่มีจุดวาบไฟเกิน 93 องศาเซลเซียสขึ้นไป","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":732,"law_id":84,"seq":11,"text":"2) ติดป้ายแสดงหมายเลขโทรศัพท์ของหน่วยงานที่เกี่ยวข้อง เพื่อขอความช่วยเหลือในยามฉุกเฉิน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":311,"law_id":55,"seq":3,"text":"ส่วนที่ 5  การป้องกันและระงับอัคคีภัย\nข้อ 26 การป้องกันและระงับอัคคีภัยในสถานที่เก็บรักษาน้ำมันเชื้อเพลิง ลักษณะที่สอง ให้ปฏิบัติตามที่กำหนดไว้ในข้อ 9 ข้อ 10 ข้อ 11 และข้อ 13\n          ข้อ 9 ภาชนะบรรจุน้ำมันเชื้อเพลิงต้องปิดฝาไว้ตลอดเวลาที่ไม่ใช้งาน\n         ข้อ 10 ห้ามทำการถ่ายเท หรือแบ่งบรรจุน้ำมันเชื้อเพลิงภายในบริเวณที่มีการจำหน่าย หรือขายน้ำมันเชื้อเพลิง\n         ข้อ 11 ห้ามต่อท่อน้ำมันเชื้อเพลิงระหว่างถังน้ำมันเชื้อเพลิงเข้าด้วยกัน\n  ข้อ 13 บริเวณที่ตั้งภาชนะบรรจุน้ำมันเชื้อเพลิงเพื่อการจำหน่ายต้องจัดให้มีป้ายเตือนโดยมีข้อความ ลักษณะ และที่ตั้ง ดังต่อไปนี้\n(1) ป้ายต้องมีข้อความอย่างน้อย ดังต่อไปนี้\n“อันตราย\n1. ห้ามสูบบุหรี่\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":677,"law_id":55,"seq":4,"text":"2. ห้ามก่อประกายไฟ”\n(2) ข้อความในป้ายต้องมองเห็นได้ชัดเจนและอ่านได้ง่าย โดยมีความสูงของอักษรไม่น้อยกว่า 2.50 เซนติเมตร\n(3) ป้ายต้องตั้งอยู่ห่างจากบริเวณที่ตั้งภาชนะบรรจุน้ำมันเชื้อเพลิงระยะไม่เกิน 2.00 เมตร และต้องติดตั้งไว้ในที่ที่เห็นได้ง่าย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":312,"law_id":55,"seq":5,"text":"ข้อ 27 การเก็บน้ำมันเชื้อเพลิงชนิดไวไฟมาก ชนิดไวไฟปานกลาง หรือชนิดไวไฟน้อยที่มีจุดวาบไฟไม่เกิน 93 องศาเซลเซียสเพื่อการจำหน่าย บริเวณที่ตั้งภาชนะบรรจุน้ำมันเชื้อเพลิงต้องจัดให้มีอุปกรณ์ป้องกันและระงับอัคคีภัย ดังต่อไปนี้\n       (1) เครื่องดับเพลิงชนิดผงเคมีแห้งหรือน้ำยาดับเพลิงขนาดบรรจุไม่น้อยกว่า 6.80 กิโลกรัม มีความสามารถในการดับเพลิงไม่น้อยกว่า 3A 40B ตามมาตรฐานระบบป้องกันอัคคีภัยของวิศวกรรมสถานแห่งประเทศไทยในพระบรมราชูปถัมภ์หรือมาตรฐานอื่นที่เทียบเท่าตามที่รัฐมนตรีกำหนดโดยประกาศในราชกิจจานุเบกษา จำนวนไม่น้อยกว่าสองเครื่อง\n(2) เครื่องดับเพลิงต้องอยู่ในสภาพที่ใช้งานได้ดี และผู้ประกอบกิจการควบคุมต้องตรวจสอบและบำรุงรักษาทุกหกเดือน โดยมีหลักฐานการตรวจสอบติดหรือแขวนไว้ที่เครื่องดับเพลิง\n(3) ทรายในปริมาณไม่น้อยกว่า 200 ลิตร และสามารถนำมาใช้ได้สะดวกตลอดเวลา","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":314,"law_id":57,"seq":0,"text":"1. ให้จัดทำการบันทึกผลการตรวจสอบและบำรุงรักษาระบบไฟฟ้าและบริภัณฑ์ไฟฟ้าประจำปี ตามแบบท้ายประกาศนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":678,"law_id":57,"seq":1,"text":"2. กรณีตรวจสอบและรับรองตามกฎหมายว่าด้วยโรงงานหรือควบคุมอาคาร โดยมีวิศวกรไฟฟ้าเป็นผู้บันทึกผลการตรวจสอบให้ถือว่าเป็นการตรวจสอบและรับรองตามประกาศฉบับนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":679,"law_id":57,"seq":2,"text":"3. ผู้จัดทำบันทึกผลการตรวจสอบต้องขึ้นทะเบียนตามมาตรา 9 หรือเป็นนิติบุคคลที่ได้รับใบอนุญาตตามมาตรา 11 แห่ง พ.ร.บ. ความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554 แล้วแต่กรณี\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":680,"law_id":57,"seq":3,"text":"4. จัดส่งผลการตรวจสอบและรับรองระบบไฟฟ้าและบริภัณฑ์ไฟฟ้าต่อพนักงานตรวจความปลอดภัยในเขตพื้นที่รับผิดชอบภายใน 15 วันนับ แต่วันที่ตรวจสอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":681,"law_id":59,"seq":1,"text":"2. บทนิยาม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":682,"law_id":59,"seq":2,"text":"3. ข้อกำหนดการจัดการหน่วยดับเพลิงสำหรับสถานประกอบการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":340,"law_id":64,"seq":0,"text":"กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรม ข้อกำหนดในการป้องกันอัคคีภัย เล่ม 7 ศูนย์สั่งการดับเพลิงในอาคาร มาตรฐานเลขที่ มอก.2541 เล่ม 7 – 2559 ไว้ดังมีรายละเอียดต่อท้ายประกาศนี้\nโดยหัวข้อมีดังนี้ \n1. ขอบข่าย\n          มาตรฐานผลิตภัณฑ์อุตสาหกรรมนี้ ครอบคลุมหลักปฏิบัติของศูนย์สั่งการดับเพลิงในอาคารเป็นมาตรฐาน\nเพื่อใช้สำหรับอาคารสูง อาคารชุมนุมคน อาคารขนาดใหญ่พิเศษ และอาคารสาธารณะ ใช้เป็นแนวทางในการจัดการ\nด้านความปลอดภัยและปฏิบัติการตอบโต้ภาวะฉุกเฉินที่อาจเกิดขึ้นกับอาคารเหล่านั้น\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":683,"law_id":64,"seq":1,"text":"2. บทนิยาม\n             กำหนดความหมายของคำที่ใช้ในมาตรฐานผลิตภัณฑ์อุตสาหกรรมนี้ ยกตัวอย่างเช่น ศูนย์สั่งการดับเพลิง  แผนปฏิบัติการฉุกเฉิน  เป็นต้น\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":684,"law_id":64,"seq":2,"text":"3. ข้อกำหนดของศูนย์สั่งการดับเพลิงในอาคาร\nภาคผนวก ก. แผนบัญชาการศูนย์สั่งการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":345,"law_id":69,"seq":0,"text":"หมวด 1 ความร้อน\n1. ให้นายจ้างควบคุมและรักษาระดับความร้อนภายในสถานประกอบกิจการที่มีลูกจ้างทำงานอยู่มิให้เกินมาตรฐาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":685,"law_id":69,"seq":1,"text":"2.  กรณีสถานประกอบกิจการมีแหล่งความร้อนที่อาจเป็นอันตราย ให้นายจ้างดำเนินการดังนี้\no ติดป้ายหรือประกาศเตือนอันตรายในบริเวณดังกล่าวให้มองเห็นได้ชัดเจน\no กรณีมีระดับความร้อนเกินกว่าที่มาตรฐานกำหนด  ให้ปรับปรุงหรือแก้ไขสภาวะการทำงานทางด้าน\nวิศวกรรม   และปิดประกาศการปรับปรุงหรือแก้ไขดังกล่าวไว้ด้วย\no กรณีที่ไม่สามารถปรับปรุงหรือแก้ไขสภาวะการทำงานดังกล่าวได้  ต้องจัดให้มีมาตรการควบคุมหรือลดภาระงาน และให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลตลอดเวลาที่ทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":346,"law_id":69,"seq":2,"text":"หมวด 2 แสงสว่าง\n3. นายจ้างต้องจัดให้สถานประกอบกิจการมีความเข้มของแสงสว่างไม่ต่ำกว่ามาตรฐานกำหนด 4. ต้องใช้หรือจัดให้มีฉาก แผ่นฟิล์มกรองแสง หรือมาตรการอื่นที่เหมาะสมและเพียงพอเพื่อป้องกันมิให้แสงตรงหรือ\nแสงสะท้อนจากแหล่งกำเนิดแสงหรือดวงอาทิตย์ที่มีแสงจ้าส่องเข้านัยน์ตาลูกจ้างโดยตรงในขณะทำงาน    กรณีไม่อาจป้องกันได้  ต้องจัดให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลตลอดเวลาที่ทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":686,"law_id":69,"seq":3,"text":"5. ทำงานในที่มืด ทึบ และคับแคบ  ต้องจัดให้มีอุปกรณ์ส่องแสงสว่าง โดยอาจเป็นชนิดติดอยู่ในพื้นที่ทำงานหรือติดตัวบุคคลก็ได้  หากไม่สามารถทำได้ต้องจัดให้มีอุปกรณ์ป้องกันอันตรายส่วนบุคคลตลอดเวลาที่ทำงานหมวด 3 เสียง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":687,"law_id":69,"seq":4,"text":"6.  ต้องควบคุมระดับเสียงมิให้ลูกจ้างได้รับสัมผัสเสียงที่มีระดับเสียงสูงสุดของเสียงกระทบหรือเสียงกระแทกเกิน 140 เดซิเบล หรือได้รับสัมผัสเสียงที่มีระดับเสียงดังต่อเนื่องแบบคงที่เกินกว่า 115 เดซิเบลเอ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":347,"law_id":69,"seq":5,"text":"7.  ต้องควบคุมระดับเสียงที่ลูกจ้างได้รับเฉลี่ยตลอดเวลาการทำงานในแต่ \nละวันไม่ให้เกินมาตรฐานที่กำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":688,"law_id":69,"seq":6,"text":"8. หากในสถานประกอบกิจการมีระดับเสียงเกินมาตรฐานที่กำหนด ให้นายจ้างดำเนินการดังนี้\no ให้ลูกจ้างหยุดทำงานจนกว่าจะได้ปรับปรุงให้ระดับเสียงเป็นไปตามมาตรฐานที่กำหนด โดยให้ปรับปรุงหรือแก้ไขทางด้านวิศวกรรม \no ปิดประกาศในการปรับปรุงหรือแก้ไขระดับเสียงที่เกินมาตรฐาน\no กรณีที่ไม่สามารถปรับปรุงหรือแก้ไขสภาวะการทำงานดังกล่าวได้ ต้องจัดให้ลูกจ้างสวมใส่อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลตลอดเวลาที่ทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":689,"law_id":69,"seq":7,"text":"9. ในบริเวณที่มีระดับเสียงเกินมาตรฐานที่กำหนด ต้องจัดให้มีเครื่องหมายเตือนให้ใช้อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลติดไว้ให้ลูกจ้างเห็นได้โดยชัดเจน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":690,"law_id":69,"seq":8,"text":"10.  กรณีมีระดับเสียงเฉลี่ยตลอดระยะเวลาการทำงาน 8 ชั่วโมงตั้งแต่ 85 เดซิเบลเอขึ้นไป ให้จัดให้มีมาตรการอนุรักษ์การได้ยินในสถานประกอบกิจการตามหลักเกณฑ์และวิธีการที่กำหนด\nหมวด 4 อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":348,"law_id":69,"seq":9,"text":"11. นายจ้างต้องจัดให้มีและดูแลให้ลูกจ้างใช้อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล และต้องบำรุงรักษาอุปกรณ์ให้อยู่ในสภาพที่ใช้งานได้อย่างปลอดภัย \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":691,"law_id":69,"seq":10,"text":"12. จัดให้ลูกจ้างได้รับการฝึกอบรมเกี่ยวกับวิธีการใช้และบำรุงรักษาอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล พร้อมเก็บหลักฐานการฝึกอบรมไว้ ณ สถานประกอบกิจการ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":733,"law_id":84,"seq":12,"text":"3) ติดหรือตั้งป้ายสัญลักษณ์เตือนอันตรายและเครื่องหมายป้ายบังคับเกี่ยวกับความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงานที่เหมาะสมกับลักษณะงาน \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":349,"law_id":69,"seq":11,"text":"หมวด 5 การตรวจวัดและวิเคราะห์สภาวะการทำงาน และการรายงานผล\n13. นายจ้างต้องจัดให้มีการตรวจวัดและวิเคราะห์สภาวะการทำงานเกี่ยวกับระดับความร้อน แสงสว่าง หรือเสียงภายในสถานประกอบกิจการตามหลักเกณฑ์และวิธีการที่กำหนด  14. กรณีไม่สามารถตรวจวัดและวิเคราะห์สภาวะการทำงานเองได้  ต้องให้ผู้ที่ขึ้นทะเบียนตามมาตรา 9 หรือนิติบุคคลที่ได้รับใบอนุญาตตามมาตรา 11 แห่ง พ.ร.บ. ความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554 \nเป็นผู้ตรวจวัดแทน 15. จัดทำรายงานผลการตรวจวัดและวิเคราะห์สภาวะการทำงานตามแบบที่กำหนด  พร้อมส่งรายงานผลดังกล่าวต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมายภายใน 30 วันนับแต่วันที่เสร็จสิ้นการตรวจวัด พร้อมเก็บรายงานผลการตรวจวัดและวิเคราะห์สภาวะการทำงานดังกล่าวด้วย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":350,"law_id":69,"seq":12,"text":"หมวด 6 การตรวจสุขภาพและการรายงานผล\n16. ให้ตรวจสุขภาพลูกจ้างที่ทำงานในสภาวะการทำงานที่อาจได้รับอันตรายจากความร้อน แสงสว่าง หรือเสียง และรายงานผล รวมทั้งดำเนินการที่เกี่ยวข้องกับการตรวจสุขภาพของลูกจ้างตาม พ.ร.บ. ความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน พ.ศ. 2554","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":371,"law_id":78,"seq":0,"text":"กำหนดมาตรฐานผลิตภัณฑ์อุตสาหกรรมการติดตั้งระบบการให้แสงสว่างฉุกเฉิน มาตรฐานเลขที่ มอก. 2690 – 2558 ไว้ ดังมีรายละเอียดต่อท้ายประกาศนี้\n1. ขอบข่าย\n     มาตรฐานนี้ ครอบคลุมคุณลักษณะที่ต้องการสำหรับการติดตั้ง ระบบการให้แสงสว่างฉุกเฉินสำหรับภายในอาคาร โดยครอบคลุมการออกแบบ การติดตั้งใหม่ การเปลี่ยนแปลง และการตรวจสอบภาคสนามสำหรับงานติดตั้งและบำรุงรักษาระบบการให้แสงสว่างฉุกเฉิน เพื่อให้บุคคลออกจากพื้นที่ได้อย่างรวดเร็วจนถึงทางออกที่ปลอดภัย\n     และครอบคลุมข้อกาหนดการติดตั้งการตรวจสอบ ใบรับรองและสมุดบันทึก\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":692,"law_id":78,"seq":1,"text":"2. บทนิยาม กำหนดความหมายของคำที่ใช้ในมาตรฐานนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":693,"law_id":78,"seq":2,"text":"3. การให้แสงสว่างฉุกเฉิน โดยแบ่งเป็นการให้แสงสว่างเพื่อการหนีภัย และการให้แสงสว่างสำรอง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":694,"law_id":78,"seq":3,"text":"4. ความสว่างเพื่อการหนีภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":695,"law_id":78,"seq":4,"text":"5. การออกแบบการให้แสงสว่างฉุกเฉิน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":696,"law_id":78,"seq":5,"text":"6. การติดตั้งระบบการให้แสงสว่างฉุกเฉิน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":697,"law_id":78,"seq":6,"text":"7. ข้อกำหนดการติดตั้ง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":698,"law_id":78,"seq":7,"text":"8. การตรวจสอบและการทดสอบ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":699,"law_id":78,"seq":8,"text":"9. ใบรับรองและสมุดบันทึก\nภาคผนวก ก. ตัวอย่างใบรับรองการทำงานแล้วเสร็จ\nภาคผนวก ข. ตารางระยะห่างสูงสุดระหว่างโคมไฟแสงสว่างฉุกเฉิน ชนิดติดตั้งกับฝ้าเพดาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":372,"law_id":79,"seq":0,"text":"1. นายจ้างต้องแจ้งข้อมูลที่จำเป็นเกี่ยวกับการเฝ้าระวัง การป้องกัน และ\nการควบคุมโรคจากการประกอบอาชีพดังต่อไปนี้ ให้ลูกจ้างทราบ\n(1) ปัจจัยเสี่ยงหรือพฤติกรรมเสี่ยงทางสุขภาพที่ก่อให้เกิดโรคจากการประกอบอาชีพ\n(2) วิธีการป้องกันตนเองจากโรคจากการประกอบอาชีพ\n(3) อาการสำคัญหรืออาการแสดงของโรคจากการประกอบอาชีพ\n(4) มาตรการในการเฝ้าระวัง การป้องกัน และการควบคุมโรคจากการประกอบอาชีพ รวมถึงการบริการอาชีวเวชกรรมที่เกี่ยวข้องซึ่งสถานประกอบกิจการจัดให้กับลูกจ้าง\n(5) สิทธิของลูกจ้างตามพระราชบัญญัติควบคุมโรคจากการประกอบอาชีพและโรคจากสิ่งแวดล้อม พ.ศ. 2562\n(6) ข้อมูลเกี่ยวกับการสวมอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคล หรือข้อมูลอื่น ๆ เกี่ยวกับการเฝ้าระวัง การป้องกันหรือการควบคุมโรค\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":700,"law_id":79,"seq":1,"text":"2. กรณีนายจ้างเป็นนายจ้างตามกฎหมายว่าด้วยการคุ้มครองแรงงาน และนายจ้างตามกฎหมายว่าด้วยความปลอดภัย อาชีวอนามัย และสภาพแวดล้อมในการทำงาน ให้แจ้งข้อมูลให้ลูกจ้างทราบก่อนที่ลูกจ้างจะเข้าทำงาน หรือเปลี่ยนลักษณะงาน หรือเปลี่ยนสภาพแวดล้อมในการทำงานที่มีความเสี่ยงหรือ\nอันตรายที่แตกต่างไปจากเดิม โดยให้จัดเก็บหลักฐานในการแจ้งข้อมูลและหลักฐานในการรับทราบข้อมูลนั้นของลูกจ้าง เพื่อให้พนักงานเจ้าหน้าที่ใช้ในการตรวจสอบ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":373,"law_id":79,"seq":2,"text":"3. กรณีนายจ้างเป็นผู้จ้างงานตามกฎหมายว่าด้วยการคุ้มครองผู้รับงานไปทำที่บ้าน ให้แจ้งข้อมูลเมื่อมีการจ้างงาน โดยให้จัดเก็บหลักฐานในการแจ้งข้อมูลและหลักฐานในการรับทราบข้อมูลนั้นของลูกจ้าง เพื่อให้พนักงานเจ้าหน้าที่ใช้ในการตรวจสอบ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":701,"law_id":79,"seq":3,"text":"4. การแจ้งให้ลูกจ้างทราบให้ดำเนินการแจ้งตามวิธีการหนึ่งวิธีการใด ดังต่อไปนี้\n(1) แจ้งโดยตรงต่อลูกจ้าง\n(2) แจ้งเป็นหนังสือ\n(3) แจ้งผ่านสื่ออิเล็กทรอนิกส์ที่สามารถระบุการรับทราบข้อมูลได้\n(4) แจ้งผ่านการฝึกอบรมที่นายจ้างจัดอบรมให้แก่ลูกจ้าง\n(5) วิธีการอื่นใดที่อธิบดีกรมควบคุมโรคประกาศกำหนดเพิ่มเติม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":375,"law_id":80,"seq":0,"text":"กำหนดงานที่มีลักษณะอาจเป็นอันตรายต่อสุขภาพและความปลอดภัยของหญิงมีครรภ์หรือเด็กซึ่งมีอายุต่ำกว่า 15 ปี ตาม พ.ร.บ. คุ้มครองผู้รับงานไปทำที่บ้าน พ.ศ. 2553 ดังนี้\n1. งานที่เป็นอันตรายต่อสุขภาพและความปลอดภัยของหญิงมีครรภ์ ได้แก่\n(1) งานเกี่ยวกับเครื่องจักรหรือเครื่องยนต์อันอาจเกิดอันตรายจากความสั่นสะเทือน\n(2) งานยก แบก หาบ หาม ทูน ลาก หรือเข็นของหนักเกิน 15 กิโลกรัม\n(3) งานที่ต้องสัมผัสละออง ไอ ก๊าซ จากวัตถุดิบหรือกระบวนการผลิตอันอาจเป็นอันตรายต่อสุขภาพ เช่น งานพ่นสี งานฟอกย้อม\n(4) งานที่ต้องสัมผัสกับฝุ่น ฟูม เส้นใย จากวัตถุดิบหรือกระบวนการผลิตอันอาจเป็นอันตรายต่อสุขภาพ เช่น งานเชื่อมโลหะ หลอมโลหะ งานขัด เจียโลหะ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":702,"law_id":80,"seq":1,"text":"2. งานที่เป็นอันตรายต่อสุขภาพและความปลอดภัยของเด็กซึ่งมีอายุต่ำกว่า 15 ปี ได้แก่\n(1) งานเกี่ยวกับเครื่องจักร เครื่องมือ หรืออุปกรณ์ซึ่งอาจก่อให้เกิดอันตรายจากเครื่องจักรเครื่องมือ หรือ อุปกรณ์นั้น\n(2) งานยก แบก หาบ หาม ทูน ลาก หรือเข็นของหนักเกินสิบห้ากิโลกรัม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":377,"law_id":82,"seq":0,"text":"ข้อ ๑ ให้ยกเลิกประกาศกระทรวงแรงงานและสวัสดิการสังคม เรื่อง กำหนดชนิดของโรคซึ่งเกิดขึ้นตามลักษณะหรือสภาพของงานหรือเนื่องจากการทำงาน ลงวันที่ ๒ กุมภาพันธ์ พ.ศ. ๒๕๓๘ บังคับใช้\nข้อ ๒ ประกาศฉบับนี้ให้ใช้บังคับตั้งแต่วันถัดจากวันประกาศในราชกิจจานุเบกษาเป็นต้นไปข้อ ๓ กำหนดชนิดของโรคซึ่งเกิดขึ้นตามลักษณะหรือสภาพของงานหรือเนื่องจากการทำงานไว้ดังต่อไปนี้\n(๑) โรคที่เกิดขึ้นจากสารเคมีดังต่อไปนี้\n๑) เบริลเลียมหรือสารประกอบของเบริลเลียม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":703,"law_id":82,"seq":1,"text":"๒) แคดเมียม หรือสารประกอบของแคดเมียม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":704,"law_id":82,"seq":2,"text":"๓) ฟอสฟอรัส หรือสารประกอบของฟอสฟอรัส\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":705,"law_id":82,"seq":3,"text":"๔) โครเมียม หรือสารประกอบของโครเมียม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":706,"law_id":82,"seq":4,"text":"๕) แมงกานีส หรือสารประกอบของแมงกานีส\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":707,"law_id":82,"seq":5,"text":"๖) สารหนู หรือสารประกอบของสารหนู\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":708,"law_id":82,"seq":6,"text":"๗) ปรอท หรือสารประกอบของปรอท\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":709,"law_id":82,"seq":7,"text":"๘) ตะกั่ว หรือสารประกอบของตะกั่ว\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":710,"law_id":82,"seq":8,"text":"๙) ฟลูออรีน หรือสารประกอบของฟลูออรีน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":715,"law_id":83,"seq":2,"text":"3. นายจ้างต้องกำหนดเขตอันตรายในบริเวณพื้นที่ที่มีการติดตั้ง การใช้ การเคลื่อนย้ายและการรื้อถอนนั่งร้านหรือ\nค้ำยัน  และจัดทำรั้วหรือกั้นเขต   และมีป้าย “เขตอันตราย” แสดงให้เห็นได้ชัดเจน   \n   เวลากลางคืนต้องจัดให้มีสัญญาณไฟสีส้มตลอดเวลา และห้ามให้บุคคลซึ่งไม่เกี่ยวข้องเข้าไปในเขตอันตราย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":716,"law_id":83,"seq":3,"text":"4. นายจ้างต้องติดหรือตั้งป้ายสัญลักษณ์เตือนอันตรายและเครื่องหมายป้ายบังคับเกี่ยวกับความปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":379,"law_id":83,"seq":4,"text":"5. ในการสร้าง ประกอบ ติดตั้ง ทดสอบ ตรวจสอบ ใช้ เคลื่อนย้าย และรื้อถอนนั่งร้านและค้ำยัน นายจ้างต้องปฏิบัติ\nตามรายละเอียดคุณลักษณะและคู่มือการใช้งานที่ผู้ผลิตกำหนดไว้   หากไม่มีรายละเอียดคุณลักษณะและคู่มือการใช้งาน ต้องให้วิศวกรจัดทำรายละเอียดคุณลักษณะและคู่มือการใช้งานเป็นหนังสือ และต้องมีสำเนาเอกสารเพื่อให้พนักงานตรวจสอบได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":717,"law_id":83,"seq":5,"text":"6. นายจ้างต้องจัดให้มีการคำนวณออกแบบและควบคุมการใช้นั่งร้านโดยวิศวกรตามหลักเกณฑ์ วิธีการ และเงื่อนไข\nที่กำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":718,"law_id":83,"seq":6,"text":"7. นายจ้างต้องไม่ให้ลูกจ้างทำงานบนนั่งร้านที่มีพื้นลื่น  ชำรุดหรือมีสภาพที่อาจก่อให้เกิดอันตราย  และนั่งร้านที่อยู่ภายนอกอาคารหรือส่วนอื่นที่อาจเกิดอันตรายในขณะที่มีพายุ ลมแรง ฝนตก หรือฟ้าคะนอง 8. นายจ้างต้องจัดให้มีมาตรการป้องกันวัสดุร่วงหล่น สำหรับการทำงานบนนั่งร้านหลายชั้นพร้อมกัน \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":719,"law_id":83,"seq":7,"text":"9. นายจ้างต้องตรวจสอบนั่งร้านทุกครั้งก่อนการใช้งานและทำรายงานผลการตรวจสอบ และต้องมีสำเนาเอกสารเพื่อให้พนักงานตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":380,"law_id":83,"seq":8,"text":"10. การสร้าง ประกอบ หรือติดตั้งค้ำยัน นายจ้างต้องจัดให้มีการคำนวณ ออกแบบ และควบคุมโดยวิศวกร ตามรายละเอียดที่กำหนดในกฎกระทรวงนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":720,"law_id":83,"seq":9,"text":"11. นายจ้างต้องจัดให้มีการตรวจสอบส่วนประกอบของค้ำยันและที่รองรับค้ำยันทุกครั้งก่อนการใช้งานและระหว่างใช้งาน หากพบว่าไม่มั่นคงแข็งแรงและปลอดภัย  \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":721,"law_id":83,"seq":10,"text":"12.  กรณีที่ใช้ค้ำยันรองรับการเทคอนกรีต อุปกรณ์ เครื่องจักร หรือรองรับสิ่งอื่นใดที่มีลักษณะคล้ายกัน นายจ้างต้องควบคุมดูแลมิให้บุคคลที่ไม่เกี่ยวข้องเข้าไปอยู่ในหรือใต้บริเวณนั้น   \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":722,"law_id":83,"seq":11,"text":"13. สำเนาเอกสารที่กำหนดให้ทำเป็นหนังสือ สามารถอยู่ในรูปแบบอิเล็กทรอนิกส์ได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":381,"law_id":84,"seq":0,"text":"1. ให้นายจ้างแจ้งข้อมูลงานก่อสร้างดังต่อไปนี้   ก่อนเริ่มงานไม่น้อยกว่า 15 วัน ต่ออธิบดีหรือผู้ซึ่งอธิบดีมอบหมาย \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":723,"law_id":84,"seq":1,"text":"2. ให้นายจ้างที่มีการดำเนินงานเกี่ยวกับงานก่อสร้างต้องปฏิบัติ ดังนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":724,"law_id":84,"seq":2,"text":"1) พื้นที่ทำงานก่อสร้างต้องมีความมั่นคงแข็งแรง สามารถรองรับน้ำหนักเครื่องจักร อุปกรณ์ และวัสดุในงานก่อสร้างได้อย่างปลอดภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":725,"law_id":84,"seq":3,"text":"2) จัดให้มีผู้ควบคุมงานทำหน้าที่ตรวจความปลอดภัยในการทำงาน  ก่อนการทำงานและขณะทำงานทุกขั้นตอน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":726,"law_id":84,"seq":4,"text":"3) รักษาความสะอาดในบริเวณเขตก่อสร้าง  แยกขยะที่อันตรายและไม่อันตราย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":727,"law_id":84,"seq":5,"text":"4) จัดให้มีแสงสว่างฉุกเฉินในเขตก่อสร้างให้เพียงพอเพื่อใช้ในเวลาที่ไฟฟ้าดับ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":743,"law_id":85,"seq":8,"text":"9. นายจ้างต้องไม่ให้ลูกจ้างทำงานในที่สูงนอกอาคารหรือพื้นที่เปิดโล่ง ในขณะที่มีพายุลมแรง ฝนตกหรือฟ้าคะนอง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":734,"law_id":84,"seq":13,"text":"4) กรณีมีทางร่วมหรือทางแยกในเขตก่อสร้าง ต้องติดตั้งป้ายสัญลักษณ์เตือนหรือบังคับ และสัญญาณแสงสีส้ม \nเพื่อแสดงว่าข้างหน้าเป็นทางร่วมหรือทางแยก และต้องติดตั้งกระจกนูนขนาดเส้นผ่านศูนย์กลางไม่น้อยกว่า \n50 เซนติเมตร บริเวณทางขนส่งที่เลี้ยวโค้งหรือหัก","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":383,"law_id":84,"seq":14,"text":"7. กำหนดบริเวณเขตก่อสร้าง โดยทำรั้วสูงไม่น้อยกว่า 2 เมตร ที่มั่นคงแข็งแรงไว้ตลอดแนวเขตก่อสร้าง และมีป้าย \n“เขตก่อสร้าง” และห้ามให้บุคคลซึ่งไม่เกี่ยวข้องเข้าไปในเขตก่อสร้าง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":735,"law_id":84,"seq":15,"text":"8. กำหนดเขตอันตรายในเขตก่อสร้าง โดยจัดทำรั้วหรือกั้นเขตด้วยวัสดุที่เหมาะสมกับอันตรายนั้น และมีป้าย “เขตอันตราย” และในเวลากลางคืนต้องจัดให้มีสัญญาณไฟสีส้มตลอดเวลา และห้ามให้บุคคลซึ่งไม่เกี่ยวข้องเข้าไปในเขตอันตราย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":736,"law_id":84,"seq":16,"text":"10. นายจ้างต้องจัดและดูแลให้ลูกจ้างใช้อุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลตลอดเวลาที่ทำงานก่อสร้าง\nงานเจาะและงานขุด\nงานก่อสร้างที่มีเสาเข็มและกำแพงพืด\nลิฟต์ชั่วคราวที่ใช้ในงานก่อสร้าง\nเชือก ลวดสลิง และรอก\nทางเดินชั่วคราวยกระดับสูง\nงานอุโมงค์\nงานก่อสร้างในน้ำ\nงานรื้อถอนหรือทำลายสิ่งก่อสร้าง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":384,"law_id":85,"seq":0,"text":"“ทำงานในที่สูง” หมายความว่า การทำงานในพื้นที่ปฏิบัติงานที่สูงจากพื้นดิน หรือจากพื้นอาคารตั้งแต่ 2 เมตรขึ้นไป \nซึ่งลูกจ้างอาจพลัดตกลงมาได้\n1. จัดให้มีข้อบังคับและขั้นตอนการปฏิบัติงานเพื่อความปลอดภัยในที่สูง ที่ลาดชัน ที่อาจมีการกระเด็น ตกหล่นหรือพังทลายของวัสดุสิ่งของ และที่อาจทำให้ลูกจ้างพลัดตกลงไปในภาชนะเก็บหรือรองรับวัสดุ  รวมทั้งต้องอบรมหรือชี้แจงให้ลูกจ้างทราบก่อนเริ่มปฏิบัติงาน  และเก็บสำเนาเอกสารดังกล่าวไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบได้  \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":737,"law_id":85,"seq":1,"text":"2. ให้ปฏิบัติตามรายละเอียดคุณลักษณะ และคู่มือการใช้งานที่ผู้ผลิตกำหนดไว้   หากไม่มี ต้องดำเนินการให้วิศวกรเป็นผู้จัดทำรายละเอียดขึ้นเป็นหนังสือ และต้องมีสำเนาเอกสารไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":738,"law_id":85,"seq":2,"text":"3. จัดให้มีอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลที่มีมาตรฐานเหมาะสมกับการทำงาน และลักษณะของอันตรายที่อาจเกิดขึ้นได้ตลอดเวลาที่ลูกจ้างทำงาน  และจัดให้มีการตรวจสอบสภาพก่อนการใช้งานทุกครั้ง และต้องมีสำเนาเอกสารดังกล่าวไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":385,"law_id":85,"seq":3,"text":"4. ราวกั้นหรือรั้วกันตกต้องมีความสูงไม่น้อยกว่า 90 เซนติเมตร แต่ไม่เกิน 1.10 เมตร   ในกรณีที่ใช้แผงทึบแทนราวกั้นหรือรั้วกันตก แผงทึบต้องมีความสูงไม่น้อยกว่า 90 เซนติเมตร\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":739,"law_id":85,"seq":4,"text":"5. สำเนาเอกสารสามารถอยู่ในรูปแบบอิเล็กทรอนิกส์ได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":740,"law_id":85,"seq":5,"text":"6. การทำงานในที่สูง  นายจ้างต้องจัดให้มีนั่งร้านหรือวิธีการอื่นที่เหมาะสมกับสภาพของการทำงานในที่สูง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":741,"law_id":85,"seq":6,"text":"7. การทำงานในที่สูงตั้งแต่ 4 เมตรขึ้นไป นายจ้างต้องจัดทำราวกั้นหรือรั้วกันตก ตาข่ายนิรภัย หรืออุปกรณ์ป้องกันอื่น\nที่เหมาะสมกับสภาพของการทำงาน ทั้งนี้ ต้องจัดให้มีการใช้เข็มขัดนิรภัยและเชือกนิรภัยหรือสายช่วยชีวิตตลอดระยะเวลาการทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":742,"law_id":85,"seq":7,"text":"8. กรณีที่มีปล่องหรือช่องเปิดต่าง ๆ ซึ่งอาจทำให้ลูกจ้างพลัดตกลงไปได้ ต้องจัดทำฝาปิดที่แข็งแรง ราวกั้น รั้วกันตก หรือแผงทึบ พร้อมทั้งติดป้ายเตือนอันตรายให้ชัดเจน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":386,"law_id":85,"seq":10,"text":"11. การทำงานบนที่ลาดชัน  และมีความสูงของพื้นระดับที่เอียงตั้งแต่ 2 เมตรขึ้นไป  นายจ้างต้องจัดให้มีนั่งร้าน เข็มขัดนิรภัยและเชือกนิรภัย หรือสายช่วยชีวิต หรือมาตรการป้องกันการพลัดตก ทั้งนี้ ขึ้นอยู่กับความเหมาะสมและสภาพของการทำงาน   \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":745,"law_id":85,"seq":11,"text":"12. การลำเลียงวัสดุสิ่งของบนที่สูง ต้องจัดให้มีราง ปล่อง เครื่องจักร หรืออุปกรณ์ที่เหมาะสมในการลำเลียง \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":746,"law_id":85,"seq":12,"text":"13. กำหนดเขตอันตรายในบริเวณพื้นที่ที่อาจมีการกระเด็น ตกหล่น หรือพังทลายของวัสดุสิ่งของ และติดป้ายเตือนอันตรายบริเวณพื้นที่ดังกล่าว พร้อมทั้งจัดให้มีมาตรการควบคุมดูแลเพื่อให้เกิดความปลอดภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":747,"law_id":85,"seq":13,"text":"14. กรณีที่มีวัสดุสิ่งของอยู่บนที่สูงที่อาจกระเด็น ตกหล่น หรือพังทลายลงมาได้ ให้นายจ้างดำเนินการ ดังนี้\n     O จัดทำขอบกันของตกหรือมาตรการป้องกันที่เหมาะสม\n     O จัดให้มีมาตรการควบคุมดูแลเพื่อให้เกิดความปลอดภัยแก่ลูกจ้างตลอดระยะเวลาการทำงาน\n     O จัดเรียงวัสดุสิ่งของให้เกิดความมั่นคงปลอดภัย ทำผนังกั้น   ในกรณีที่มีการเคลื่อนย้ายวัสดุสิ่งของ ให้จัดให้มีมาตรการป้องกันอันตรายจากการตกหล่น หรือพังทลายของวัสดุสิ่งของที่จะทำการเคลื่อนย้ายนั้นด้วย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":387,"law_id":85,"seq":14,"text":"15. กรณีที่มีการทำงานในท่อ ช่อง โพรง บ่อ ที่อาจเกิดการพังทลายได้ ให้จัดทำผนังกั้น ค้ำยัน ที่สามารถป้องกันอันตรายที่อาจเกิดขึ้น\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":748,"law_id":85,"seq":15,"text":"16. กรณีที่ลูกจ้างทำงานที่อาจได้รับอันตรายจากการพลัดตกลงไปในภาชนะเก็บหรือรองรับวัสดุ นายจ้างต้องจัดให้มี\nสิ่งปิดกั้น จัดทำราวกั้นหรือรั้วกันตกที่มั่นคงแข็งแรงล้อมรอบภาชนะนั้น   หากไม่อาจดำเนินการได้ นายจ้างต้องจัดให้ลูกจ้างสวมใส่เข็มขัดนิรภัยและเชือกนิรภัยหรือสายช่วยชีวิตตลอดระยะเวลาการทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":749,"law_id":85,"seq":16,"text":"17. กรณีที่ลูกจ้างทำงานบนภาชนะเก็บหรือรองรับวัสดุที่มีความสูงตั้งแต่ 4 เมตรขึ้นไป นายจ้างต้องจัดให้มีสิ่งปิดกั้น จัดทำราวกั้นหรือรั้วกันตกที่มั่นคงแข็งแรงเหมาะสมกับสภาพของการทำงาน และต้องให้ลูกจ้างสวมใส่เข็มขัดนิรภัยและเชือกนิรภัยหรือสายช่วยชีวิตตลอดระยะเวลาการทำงานด้วย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":411,"law_id":89,"seq":0,"text":"1. จัดทำป้ายแจ้งข้อความว่า “ที่อับอากาศ อันตราย ห้ามเข้า” ให้มีขนาด\nมองเห็นได้ชัดเจน ติดตั้งไว้โดยเปิดเผยบริเวณทางเข้าออกของที่อับอากาศทุกแห่ง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":750,"law_id":89,"seq":1,"text":"2. ห้ามให้ลูกจ้างหรือบุคคลใดเข้าไปในที่อับอากาศ  ยกเว้นว่าจะได้รับอนุญาตจากผู้มีหน้าที่ในการอนุญาตก่อน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":751,"law_id":89,"seq":2,"text":"3. ห้ามอนุญาตให้ลูกจ้างหรือบุคคลใดเข้าไปในที่อับอากาศ  หากรู้หรือควรรู้ว่าลูกจ้างหรือบุคคลนั้นเป็นโรคเกี่ยวกับทางเดินหายใจ  โรคหัวใจ หรือโรคอื่นซึ่งแพทย์เห็นว่าการเข้าไปในที่อับอากาศอาจเป็นอันตราย   \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":752,"law_id":89,"seq":3,"text":"4.  ให้ประเมินสภาพอันตรายในที่อับอากาศ  หากพบว่ามีสภาพอันตรายต้องจัดให้มีมาตรการควบคุมสภาพอันตรายเพื่อให้เกิดความปลอดภัยต่อลูกจ้าง  \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":753,"law_id":89,"seq":4,"text":"5. ต้องจัดให้มีการตรวจวัด บันทึกผลการตรวจวัด และประเมินสภาพอากาศในที่อับอากาศก่อนเข้าไปทำงานและในระหว่างทำงานในที่อับอากาศ  หากพบว่ามีสภาวะที่เป็นบรรยากาศอันตรายให้ดำเนินการตามที่กำหนด และต้องจัดเก็บผลดังกล่าวไว้อย่างน้อย 1 ปี\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":412,"law_id":89,"seq":7,"text":"8. ให้นายจ้างดำเนินการต่างๆ ได้แก่ \no จัดให้มีอุปกรณ์ PPE อุปกรณ์ช่วยเหลือ และช่วยชีวิตที่เหมาะสมกับงาน\no จัดให้ลูกจ้างที่ผ่านการอบรมความปลอดภัยในที่อับอากาศเป็นผู้ช่วยเหลือ และทำหน้าที่เป็นผู้ช่วยเหลือพร้อมให้จัดให้มีอุปกรณ์ช่วยเหลือและช่วยชีวิต\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":756,"law_id":89,"seq":8,"text":"9. จัดให้มีสิ่งที่ปิดกั้นเพื่อป้องกันไม่ให้บุคคลใดเข้าไปหรือตกลงไปในที่อับอากาศ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":757,"law_id":89,"seq":9,"text":"10. หากที่อับอากาศที่ให้ลูกจ้างทำงานมีผนังต่อหรืออาจมีพลังงาน สาร หรือสิ่งที่เป็นอันตรายซึ่งจะรั่วไหลเข้าสู่บริเวณที่อับอากาศที่ทำงานอยู่  ให้นายจ้างปิดกั้นหรือกระทำการใดที่จะป้องกันไม่ให้พลังงาน สาร หรือสิ่งที่เป็นอันตรายเข้าสู่บริเวณที่อับอากาศในระหว่างที่ลูกจ้างกำลังทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":758,"law_id":89,"seq":10,"text":"11. จัดบริเวณทางเดินหรือทางเข้าออกที่อับอากาศให้มีความสะดวกและปลอดภัย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":759,"law_id":89,"seq":11,"text":"12. ประกาศห้ามลูกจ้างหรือบุคคลใดสูบบุหรี่  หรือพกอุปกรณ์สำหรับจุดไฟหรือติดไฟที่ไม่เกี่ยวข้องกับงานเข้าไปในที่อับอากาศ   โดยให้ปิดป้ายประกาศห้ามไว้บริเวณทางเข้า-ออกที่อับอากาศ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":760,"law_id":89,"seq":12,"text":"13. จัดให้มีอุปกรณ์ไฟฟ้าที่เหมาะสมในการใช้งานในที่อับอากาศ และตรวจสอบให้มีสภาพสมบูรณ์พร้อมใช้งาน  กรณีที่อับอากาศมีบรรยากาศอันตรายที่ไวไฟหรือระเบิดได้  ต้องเป็นอุปกรณ์ไฟฟ้าชนิดที่ไม่เป็นต้นเหตุที่ก่อให้เกิดการติดไฟหรือระเบิดได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":761,"law_id":89,"seq":13,"text":"14. จัดให้มีอุปกรณ์ดับเพลิงที่เหมาะสมและมีประสิทธิภาพในจำนวนที่เพียงพอ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":413,"law_id":89,"seq":14,"text":"15. ห้ามนายจ้างอนุญาตให้ลูกจ้างทำงานที่ก่อให้เกิดความร้อนหรือประกายไฟ   และงานที่ใช้สารระเหยง่าย สารพิษ หรือสารไวไฟในที่อับอากาศ เว้นแต่ได้จัดให้มีมาตรการความปลอดภัยตามกฎกระทรวงนี้แล้ว   และหากลูกจ้างเห็นว่าการทำงานไม่มีมาตรการรองรับเพื่อให้เกิดความปลอดภัย  ลูกจ้างสามารถปฏิเสธไม่ทำงานดังกล่าวได้ \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":762,"law_id":89,"seq":15,"text":"16. นายจ้างเป็นผู้มีหน้าที่รับผิดชอบในการอนุญาตให้ลูกจ้างทำงานในที่อับอากาศ  หรือจะมอบหมายเป็นหนังสือ\nให้ลูกจ้างที่ได้รับการอบรมฯ เป็นผู้รับผิดชอบในการอนุญาตแทนก็ได้ และต้องเก็บหนังสือมอบหมายไว้ ณ สถานประกอบกิจการหรือสถานที่ทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":763,"law_id":89,"seq":16,"text":"17. ให้นายจ้างจัดให้มีหนังสืออนุญาตให้ลูกจ้างทำงานในที่อับอากาศทุกครั้ง โดยอย่างน้อยต้องมีรายละเอียด 12 ข้อตามที่กำหนด \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":764,"law_id":89,"seq":17,"text":"18.  ต้องเก็บหนังสืออนุญาตดังกล่าวไว้ ณ สถานประกอบกิจการหรือสถานที่ทำงาน รวมทั้งปิดหรือแสดงหนังสือสำเนาไว้ที่บริเวณทางเข้าที่อับอากาศให้เห็นชัดเจนตลอดเวลาที่ลูกจ้างทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":765,"law_id":89,"seq":18,"text":"19.  จัดให้มีการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศแก่ลูกจ้างทุกคนที่ทำงานในที่อับอากาศ  รวมทั้งผู้ที่เกี่ยวข้อง   \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":766,"law_id":89,"seq":19,"text":"20.  เก็บหลักฐานการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศไว้ ณ สถานประกอบกิจการหรือสถานที่ทำงาน  เพื่อให้พนักงานตรวจความปลอดภัยตรวจสอบได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":414,"law_id":89,"seq":20,"text":"21. ให้ประกาศกรมสวัสดิการและคุ้มครองแรงงาน เรื่อง หลักเกณฑ์ วิธีการ และหลักสูตรการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศ พ.ศ. 2549 และที่แก้ไขเพิ่มเติม ใช้ได้ต่อไปเท่าที่ไม่ขัดหรือแย้งกับกฎกระทรวงนี้ จนกว่าจะมีประกาศตามกฎกระทรวงนี้ใช้บังคับ และให้หน่วยงานฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศที่ได้ขึ้นทะเบียนก่อนวันที่ 15 กุมภาพันธ์ 2562 ดำเนินการได้ต่อไป และให้ถือเป็นนิติบุคคลที่ได้รับใบอนุญาต  จนกว่าจะมีนิติบุคคลที่ได้รับใบอนุญาตตามมาตรา 11 ดำเนินการ\n22.กรณีที่นายจ้างจัดให้มีการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามกฎกระทรวงกำหนดมาตรฐานในการบริหารและการจัดการด้านความปลอดภัย อาชีวอนามัยและสภาพแวดล้อมในการทำงานในที่อับอากาศ พ.ศ. 2547 \nให้ถือว่าได้จัดให้มีการฝึกอบรมแก่ลูกจ้างและลูกจ้างได้รับการฝึกอบรมตามข้อ 20 แล้ว","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":416,"law_id":91,"seq":0,"text":"1. ให้นายจ้างจัดฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศให้กับลูกจ้างที่มีหน้าที่รับผิดชอบในการอนุญาต ผู้ควบคุมงาน ผู้ช่วยเหลือ และผู้ปฏิบัติงานในที่อับอากาศ  และจัดฝึกอบรมเพื่อทบทวนความปลอดภัยในการทำงานในที่อับอากาศ\n    กรณีลูกจ้างเปลี่ยนงาน หรือเปลี่ยนสถานที่ทำงานที่อาจได้รับอันตรายจากงาน ให้นายจ้างจัดฝึกอบรมภาคปฏิบัติให้กับลูกจ้างผู้มีหน้าที่รับผิดชอบในการอนุญาต ผู้ควบคุมงาน ผู้ช่วยเหลือและผู้ปฏิบัติงานในที่อับอากาศ ก่อนเริ่มการทำงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":767,"law_id":91,"seq":1,"text":"2. ในการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศ  นายจ้างหรือนิติบุคคลที่ได้รับอนุญาตต้องดำเนินการดังนี้ \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":768,"law_id":91,"seq":2,"text":"1) แจ้งกำหนดการ หลักสูตรการฝึกอบรม รายชื่อและคุณสมบัติวิทยากร ต่ออธิบดีไม่น้อยกว่า 7 วันทำการก่อนการจัดฝึกอบรม \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":769,"law_id":91,"seq":3,"text":"3. กรณีนายจ้างเป็นผู้จัดฝึกอบรมฯ ให้จัดฝึกอบรมภาคปฏิบัติในสถานที่จริงหรือมีลักษณะเหมือนสถานที่จริง \nกรณีนิติบุคคลเป็นผู้จัดฝึกอบรมฯ ให้จัดฝึกอบรมภาคปฏิบัติในสถานที่ตั้งที่ได้รับอนุญาต\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":770,"law_id":91,"seq":4,"text":"4. ผู้เข้ารับการฝึกอบรมภาคปฏิบัติต้องมีอายุไม่ต่ำกว่า 18 ปี และมีใบรับรองแพทย์ว่าเป็นผู้มีสุขภาพสมบูรณ์ ร่างกายแข็งแรง ไม่เป็นโรคเกี่ยวกับทางเดินหายใจ โรคหัวใจ หรือโรคอื่นซึ่งแพทย์เห็นว่าการเข้าไปในที่อับอากาศอาจเป็นอันตรายต่อผู้เข้ารับการฝึกอบรม","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":417,"law_id":91,"seq":5,"text":"7. จัดฝึกอบรมทบทวนความปลอดภัยในการทำงานในที่อับอากาศทุก 5 ปี โดยให้ฝึกอบรมให้แล้วเสร็จภายใน 30 วันก่อนครบกำหนด 5 ปี\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":771,"law_id":91,"seq":6,"text":"8. ผู้เข้ารับการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศ ต้องเป็นผู้ที่ผ่านการฝึกการอบรมดับเพลิงขั้นต้น \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":772,"law_id":91,"seq":7,"text":"10. ให้นายจ้างจัดทำทะเบียนรายชื่อผู้ที่ผ่านการฝึกอบรม วัน เวลาที่ฝึกอบรมพร้อมรายชื่อวิทยากรเก็บไว้พร้อมที่จะให้พนักงานตรวจความปลอดภัยตรวจสอบได้ \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":773,"law_id":91,"seq":8,"text":"11. ให้นายจ้างจัดทำรายงานผลการฝึกอบรมความปลอดภัยในการทำงานในที่อับอากาศตามแบบท้ายประกาศนี้ ภายใน 30 วันนับแต่วันที่อบรมเสร็จสิ้น \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":774,"law_id":91,"seq":9,"text":"12. ผู้ที่เคยผ่านการฝึกอบรมหลักสูตรอนุญาต ผู้ควบคุมงาน ผู้ช่วยเหลือ และผู้ปฏิบัติงานในที่อับอากาศมาแล้ว ตามประกาศกรมฯ เดิม  ก่อนวันที่ประกาศนี้มีผลบังคับใช้ ให้ถือว่าผ่านการอบรมตามที่ประกาศนี้กำหนด    \n      โดยผู้ผ่านการอบรมจะต้องเข้ารับการฝึกอบรมทบทวน โดยต้องเข้ารับการฝึกอบรมทบทวนให้แล้วเสร็จภายใน 30 วันก่อนครบกำหนด 5 ปีนับแต่วันที่ผ่านการฝึกอบรม   เว้นแต่กรณีเป็นผู้ที่ผ่านการฝึกอบรมมาแล้วตั้งแต่ 5 ปีขึ้นไป ต้องเข้ารับการฝึกอบรมทบทวนให้แล้วเสร็จภายใน 90 วันนับแต่วันประกาศนี้มีผลบังคับใช้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":418,"law_id":92,"seq":0,"text":"หมวด ๑ เครื่องจักร\n2. ในบริเวณที่มีการติดตั้ง การซ่อมแซม หรือการตรวจสอบเครื่องจักรหรือเครื่องป้องกันอันตรายจากเครื่องจักร ต้องติดป้ายแสดงการดำเนินการดังกล่าว รวมทั้งจัดให้มีระบบ วิธีการ หรืออุปกรณ์ป้องกันมิให้เครื่องจักรนั้นทำงาน \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":507,"law_id":145,"seq":0,"text":"1.\tยกเว้นภาษีเงินได้ จำนวนเงิน 50% ของเงินที่บริษัทจ่ายในการลงทุนในเครื่องจักรหรืออุปกรณ์ที่มีประสิทธิภาพสูงหรือวัสดุหรืออุปกรณ์เพื่อการอนุรักษ์พลังงานที่มีผลต่อการประหยัดพลังงาน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":775,"law_id":92,"seq":1,"text":"3. ในการประกอบ การติดตั้ง การทดสอบ การใช้ การซ่อมแซม การบำรุงรักษา การตรวจสอบ การรื้อถอน หรือการเคลื่อนย้ายเครื่องจักร รถยก ลิฟต์ เครื่องจักรสำหรับใช้ในการยกคนขึ้นทำงานบนที่สูง นายจ้างต้องปฏิบัติตามรายละเอียดคุณลักษณะและคู่มือการใช้งานที่ผู้ผลิตกำหนดไว้ ในกรณีที่มีการเคลื่อนย้ายเครื่องจักรที่มีน้ำหนักตั้งแต่ 1 ตันขึ้นไป ต้องจัดให้มีแผนป้องกันอันตรายจากการเคลื่อนย้าย \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":776,"law_id":92,"seq":2,"text":"4. เครื่องจักรดังต่อไปนี้ ต้องจัดให้มีการตรวจสอบประจำปี โดยต้องมีสำเนาเอกสารการตรวจสอบไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบได้ \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":777,"law_id":92,"seq":3,"text":"5. นายจ้างต้องไม่ใช้หรือยอมให้ลูกจ้างใช้เครื่องจักรทำงานเกินพิกัดของเครื่องจักร \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":778,"law_id":92,"seq":4,"text":"7. นายจ้างต้องจัดให้มีการประเมินอันตรายของเครื่องจักรที่อาจก่อให้เกิดอันตรายจากการใช้งานถึงขั้นสูญเสียอวัยวะ ได้แก่ เครื่องจักรประเภทเครื่องบด เครื่องโม่ เครื่องตัดน้ำแข็ง หรือเครื่องจักรอื่นตามที่อธิบดีประกาศกำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":779,"law_id":92,"seq":5,"text":"8. ในการทำงานเกี่ยวกับเครื่องปั๊มโลหะ เครื่องเชื่อมไฟฟ้า เครื่องเชื่อมก๊าซ หรือเครื่องจักรชนิดอื่น ลูกจ้างต้องผ่านการอบรมเกี่ยวกับขั้นตอนและวิธีการทำงานที่ปลอดภัยในการทำงานของเครื่องจักร เป็นต้น โดยวิทยากรซึ่งมีคุณสมบัติตามหลักสูตรที่อธิบดีประกาศกำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":780,"law_id":92,"seq":6,"text":"9. ต้องดูแลให้พื้นบริเวณรอบเครื่องจักรมีความปลอดภัย","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":419,"law_id":92,"seq":7,"text":"10. นายจ้างต้องจัดให้มีวิธีการดำเนินการเพื่อป้องกันอันตรายจากเครื่องจักร ดังต่อไปนี้\n(1) เครื่องจักรที่ใช้พลังงานไฟฟ้าต้องมีระบบหรือวิธีการป้องกันกระแสไฟฟ้ารั่วเข้าตัวบุคคลหรือเครื่องจักรและต้องต่อสายดิน \n(2) เครื่องจักรที่ใช้พลังงานไฟฟ้า สายไฟฟ้าที่ต่อเข้าเครื่องจักรต้องเดินมาจากที่สูง \n(3) เครื่องจักรชนิดอัตโนมัติต้องมีสีเครื่องหมายปิด - เปิด ที่สวิตช์อัตโนมัติตามหลักสากลและมีเครื่องป้องกันมีสิ่งใดมากระทบสวิตช์อันเป็นเหตุให้เครื่องจักรทำงาน\n(4) เครื่องจักรที่มีการถ่ายทอดพลังงานโดยใช้เพลา สายพาน รอก ต้องมีตะแกรงหรือที่ครอบปิดคลุมส่วนที่หมุนได้และส่วนส่งถ่ายกำลังให้มิดชิด \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":781,"law_id":92,"seq":8,"text":"11. ต้องบำรุงรักษาและดูแลเครื่องป้องกันอันตรายจากเครื่องจักรให้อยู่ในสภาพที่สามารถป้องกันอันตรายได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":782,"law_id":92,"seq":9,"text":"12. ต้องจัดให้ทางเดินเข้าออกจากพื้นที่สำหรับปฏิบัติงานเกี่ยวกับเครื่องจักรมีความกว้างไม่น้อยกว่า 80 เซนติเมตร","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":420,"law_id":92,"seq":10,"text":"ส่วนที่ ๓ เครื่องเชื่อมไฟฟ้าและเครื่องเชื่อมก๊าซ\n(๑) จัดให้มีเครื่องดับเพลิงแบบเคลื่อนย้ายได้ติดตั้งไว้ในบริเวณใกล้เคียงที่สามารถนำมาใช้ดับเพลิงได้ทันที\n(๒) จัดให้มีอุปกรณ์คุ้มครองความปลอดภัยส่วนบุคคลให้ลูกจ้างสวมใส่\n(๓) จัดบริเวณที่ปฏิบัติงานไม่ให้มีวัสดุที่ติดไฟง่ายวางอยู่\n(๔) จัดให้มีฉากกั้นหรืออุปกรณ์ป้องกันอันตรายอื่น ๆ ที่เหมาะสมเพื่อป้องกันอันตรายจากประกายไฟและแสงจ้า\n(๕) จัดสถานที่ปฏิบัติงานให้มีแสงสว่างและการระบายอากาศอย่างเหมาะสม\nข้อ ๒๘ นายจ้างต้องจัดให้มีมาตรการด้านความปลอดภัยและควบคุมดูแลให้ลูกจ้างปฏิบัติโดยเคร่งครัด เมื่อใช้เครื่องเชื่อมไฟฟ้าหรือเครื่องเชื่อมก๊าซกับภาชนะบรรจุสารไวไฟ หรือในบริเวณที่อาจก่อให้เกิดอันตรายจากการรระเบิด เพลิงไหม้หรือไฟลามจากก๊าซนำมัน หรือวัตถุไวไฟอื่น","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":453,"law_id":110,"seq":0,"text":"เพิ่มเติมข้อยกเว้นความรับผิดผู้ให้บริการ 4 ประเภท ตามเงื่อนไขที่กฎหมายกำหนด\nซึ่งผู้ให้บริการอินเตอร์เน็ตถือเป็นผู้ให้บริการประเภทเป็นสื่อกลางส่งผ่านข้อมูลคอมพิวเตอร์หรือให้สามารถติดต่อถึงกันได้โดยประการอื่นผ่านทางระบบคอมพิวเตอร์ หรือ Mere Conduit (มาตรา 43/2)\n1. เงื่อนไขทั่วไป (มาตรา 43/1): ต้องประกาศมาตรการยกเลิกการให้บริการแก่ผู้ใช้บริการที่กระทำการละเมิดลิขสิทธิ์ซ้ำ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":421,"law_id":92,"seq":11,"text":"ส่วนที่ ๖ เครื่องจักรสำหรับใช้ในการยกคนขึ้นทำงานบนที่สูง\n(1) จัดให้มีการป้องกันการตกจากที่สูงตามกฎกระทรวงฯ \n(2) จัดให้มีป้ายบอกพิกัดน้ำหนักและจำนวนคนที่สามารถยกได้อย่างปลอดภัย\n(3) ตรวจสอบสภาพเครื่องจักรสำหรับใช้ในการยกคนขึ้นทำงานบนที่สูงและอุปกรณ์ที่เกี่ยวข้องก่อนการใช้งานทุกครั้ง และต้องมีสำเนาเอกสารการตรวจสอบไว้ให้พนักงานตรวจความปลอดภัยตรวจสอบได้\n(4) จัดให้มีสัญญาณเสียงหรือแสงไฟเตือนภัยขณะทำงาน\n(5) จัดให้มีอุปกรณ์ตัดระบบการทำงานเมื่อมีการใช้งานเกินพิกัดที่ผู้ผลิตกำหนด\n48. นายจ้างต้องจัดให้มีการอบรมลูกจ้างเกี่ยวกับการปฏิบัติตามรายละเอียดคุณลักษณะและคู่มือการใช้งานเครื่องจักรสำหรับใช้ในการยกคนขึ้นทำงานบนที่สูงเพื่อความปลอดภัยในการทำงาน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":450,"law_id":107,"seq":0,"text":"เมื่อมีการละเมิด CIA ของข้อมูลส่วนบุคคล นอกเหนือจากการดำเนินการเพื่อระงับเหตุ บริษัทฯ ยังมีหน้าที่ในการแจ้งเหตุการละเมิดข้อมูลส่วนบุคคล โดยแบ่ง 3 กรณี ดังนี้\n1. กรณีที่เหตุการละเมิดไม่มีความเสี่ยงต่อสิทธิและเสรีภาพของบุคคล\nไม่จำเป็นต้องแจ้งเหตุการละเมิด แต่ต้องนำส่งข้อมูลหรือเอกสารหลักฐานว่าเพราะเหตุใด เหตุการละเมิดดังกล่าวจึงไม่ก่อให้เกิดความเสี่ยง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":783,"law_id":107,"seq":1,"text":"2. กรณีที่เหตุการละเมิดมีความเสี่ยงต่อสิทธิและเสรีภาพของบุคคล\nต้องแจ้งสำนักงานคณะกรรมการคุ้มครองข้อมูลส่วนบุคคลภายใน 72 ชั่วโมง นับแต่เหตุการละเมิดเกิด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":784,"law_id":107,"seq":2,"text":"3.  กรณีที่เหตุการละเมิดมีความเสี่ยงสูงต่อสิทธิและเสรีภาพของบุคคล\nต้องแจ้งให้สำนักงานคณะกรรมการคุ้มครองข้อมูลส่วนบุคคลทราบภายใน 72 ชั่วโมง นับแต่เหตุการละเมิดเกิด และแจ้งเจ้าของข้อมูลส่วนบุคคลที่ได้รับผลกระทบโดยไม่ชักช้า","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":452,"law_id":109,"seq":0,"text":"กำหนดหลักเกณฑ์เฉพาะในการคุ้มครองข้อมูลส่วนบุคคลผู้ใช้บริการโทรคมนาคม (ยกเว้นผู้ใช้บริการที่เป็นผู้รับใบอนุญาตฯ ด้วยกัน) โดยมีหลักเกณฑ์สำคัญ ๆ ที่แตกต่างจาก PDPA ดังนี้\n1. โดยหลัก การเก็บรวบรวมข้อมูลส่วนบุคคลจะต้องเป็นไปเพื่อการให้บริการโทรคมนาคม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":785,"law_id":109,"seq":1,"text":"2. ห้ามเก็บรวบรวมข้อมูลอ่อนไหว เว้นแต่ได้รับความยินยอม และเป็นไปเพื่อประโยชน์ในการให้บริการให้เหมาะสมกับลักษณะพิการทางร่างกาย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":786,"law_id":109,"seq":2,"text":"3. ต้องจัดให้มีช่องทางปรับปรุงข้อมูล รวมถึงช่องทางการเลือกรับ/ยกเลิกการรับข้อมูล โดยมีระบบการพิสูจน์และยืนยันตัวบุคคลที่รัดกุม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":787,"law_id":109,"seq":3,"text":"4. กำหนดกรอบระยะเวลาการเก็บรักษาข้อมูลส่วนบุคคล โดยให้เก็บรักษาเป็นระยะเวลา 90 วัน ย้อนหลังตลอดระยะเวลาการใช้บริการ หรือเก็บรักษา 90 วัน นับแต่สัญญาสิ้นสุด เว้นแต่มีความจำเป็นอื่นตามที่ประกาศ กสทช. กำหนด อาจเก็บรักษาไว้นานกว่านั้นได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":788,"law_id":109,"seq":4,"text":"5. ต้องดำเนินการให้เป็นไปตามสิทธิเจ้าของข้อมูล ภายในเวลา 15 วัน นับแต่ได้รับคำขอ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":789,"law_id":109,"seq":5,"text":"6. กรณีมีเหตุละเมิดข้อมูลส่วนบุคคล ต้องแจ้ง กสทช. ด้วย โดยให้แจ้งภายใน 72 ชั่วโมง นับแต่ทราบเหตุ แต่ถ้าความเสี่ยงสูง ให้ระยะเวลาลดเหลือ 24 ชั่วโมง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":790,"law_id":109,"seq":6,"text":"7. กรณีได้รับคำขอจากหน่วยงานรัฐให้ดักฟัง ตรวจ กักสัญญาณ ฯลฯ ต้องรายงานข้อมูลให้ กสทช. เป็นรายไตรมาส\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":791,"law_id":109,"seq":7,"text":"8. ต้องจัดส่งนโยบายคุ้มครองข้อมูลส่วนบุคคล ให้เลขาธิการ กสทช. รับรอง ภายใน 90 วัน นับแต่วันถัดจากวันประกาศกำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":794,"law_id":110,"seq":1,"text":"2. เงื่อนไขเฉพาะสำหรับ  Mere Conduit (มาตรา 43/2): ต้องให้บริการภายใต้เงื่อนไข 5 ข้อ ดังนี้\n- ไม่ได้เป็นผู้ริเริ่มส่งข้อมูล \n- ไม่ได้เป็นผู้กำหนดผู้รับข้อมูล \n- ส่งข้อมูลผ่านกระบวนการทางเทคนิคโดยอัตโนมัติ \n- ไม่ได้กำหนดไม่ได้เปลี่ยนแปลงเนื้อหาของข้อมูล และ\n- ไม่ได้เก็บสำเนาข้อมูลที่ทำซ้ำขึ้นในระหว่างกระบวนการพักข้อมูลเป็นการชั่วคราว\nในลักษณะที่ผู้อื่นสามารถเข้าถึงได้โดยทั่วไปและนานเกินกว่าที่จำเป็น","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":456,"law_id":113,"seq":0,"text":"ผู้ประกอบกิจการโทรคมนาคม ต้องจัดให้มี DPO ของตนเอง เนื่องจาก\n1. การเก็บรวบรวม  ใช้  หรือเปิดเผยข้อมูลส่วนบุคคลของลูกค้าหรือผู้รับบริการโดยผู้ประกอบกิจการโทรคมนาคม ถือเป็นกรณีที่มีความจำเป็นต้องตรวจสอบข้อมูลส่วนบุคคลหรือระบบอย่างสม่ำเสมอ ตามข้อ 5 วรรคสอง (4) และ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":795,"law_id":113,"seq":1,"text":"2. การเก็บรวบรวม  ใช้  หรือเปิดเผยข้อมูลส่วนบุคคลของลูกค้าหรือผู้รับบริการโดยผู้รับใบอนุญาต ประกอบกิจการโทรคมนาคมแบบที่สามตามกฎหมายว่าด้วยการประกอบกิจการโทรคมนาคม  ให้ถือเป็นกรณีที่มีข้อมูลส่วนบุคคลเป็นจำนวนมาก  (on  a  large  scale) ตามข้อ 6 วรรคสอง (4)","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":460,"law_id":116,"seq":0,"text":"1. การเก็บข้อมูลประวัติอาชญากรรมจะกระทำได้ต่อเมื่อได้รับความยินยอมจากเจ้าของข้อมูล สำหรับวัตถุประสงค์ในการพิจารณารับบุคคลเข้าทำงาน หรือตรวจสอบคุณสมบัติ \n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":796,"law_id":116,"seq":1,"text":"2. ในการขอความยินยอม ต้องแจ้งผลกระทบของการไม่ให้ความยินยอมโดยชัดแจ้ง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":797,"law_id":116,"seq":2,"text":"3. การจัดเก็บข้อมูลประวัติอาชญากรรมจะต้องจัดมาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสม\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":798,"law_id":116,"seq":3,"text":"4. เมื่อใช้ข้อมูลประวัติอาชญากรรมสำเร็จตามวัตถุประสงค์ ให้เก็บข้อมูลนั้นต่อไปได้อีกไม่เกิน 6 เดือน นับแต่ดำเนินการเสร็จสิ้น","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":463,"law_id":119,"seq":0,"text":"หน่วยงานโครงสร้างพื้นฐานสำคัญทางสารสนเทศ \n1. กำหนดคุณลักษณะของข้อมูล/ระบบสารสนเทศ ตามประกาศ LF-026 โดยประเมินจากวัตถุประสงค์ด้านความมั่นคงปลอดภัยไซเบอร์และระดับผลกระทบเป็น (1) ระดับต่ำ (2) ระดับกลาง (3) ระดับสูง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":799,"law_id":119,"seq":1,"text":"2. กำหนดมาตรการควบคุมความมั่นคงปลอดภัยไซเบอร์ขั้นต่ำ ตามคุณลักษณะของข้อมูล ได้แก่\n2.1 ความมั่นคงปลอดภัยไซเบอร์ระดับต่ำ\n- การประเมินความเสี่ยง และกลยุทธ์จัดการความเสี่ยง\n- แผนรับมือภัยคุกคาม แผนสื่อสารในภาวะวิกฤต\n- การสร้างความตระหนักรู้ การฝึกซ้อม\n-  Access control\n- การทำให้ระบบมีความแข็งแกร่ง ตรวจสอบและเฝ้าระวังภัยคุกคามไซเบอร์\n2.2 ความมั่นคงปลอดภัยไซเบอร์ระดับกลาง (เพิ่มเติมจาก 2.1) \n- แผนตรวจสอบการรักษาความมั่นคงปลอดภัยไซเบอร์\n- Remote Connection\n- Removable  Storage  Media\n2.3 ความมั่นคงปลอดภัยไซเบอร์ระดับสูง (เพิ่มเติมจาก 2.1 และ 2.2)\n - การประเมินช่องโห่และทดสอบเจาะระบบ\n- บริหารจัดการผู้ให้บริการภายนอก\n- Information Sharing\n- การรักษาและฟื้นฟูความเสียหายที่เกิด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":464,"law_id":120,"seq":0,"text":"กำหนดแนวทางการจัดทำแผนการรักษาความมั่นคงปลอดภัยไซเบอร์  (มีเอกสารแนบท้ายประกาศ)\nประกอบด้วย  3 หัวข้อใหญ่\n1. รายละเอียดระบบสารสนเทศ\n- ชื่อและหมายเลขอ้างอิง\n- คำอธิบายและวัตถุประสงค์ของระบบสารสนเทศ\n- เจ้าหน้าที่ระดับอาวุโสด้านความมั่นคงปลอดภัยสารสนเทศ\n- เจ้าของระบบสารสนเทศ\n- เจ้าของสารสนเทศ\n- เจ้าหน้าที่ที่มีอำนาจ\n- ผู้ที่เกี่ยวข้องกับระบบสารสนเทศ\n- การกำหนดคุณลักษณะความมั่นคงปลอดภัยไซเบอร์\n- สถานะของระบบสารสนเทศ\n- การเชื่อมต่อระบบและใช้งานข้อมูลร่วมกัน\n- นโยบาย ระเบียบ หรือกฎหมายที่เกี่ยวข้อง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":466,"law_id":122,"seq":0,"text":"1. เมื่อเจ้าของข้อมูลส่วนบุคคลใช้สิทธิตามมาตรา 33 ขอให้มีการลบ ทำลาย หรือทำให้ข้อมูลส่วนบุคคลเป็นข้อมูลที่ไม่สามารถระบุตัวตนได้ ให้ดำเนินการดังต่อไปนี้\n- ต้องดำเนินการภายใน 90 วัน นับแต่ได้รับคำขอ หากไม่สามารถดำเนินการได้ภายใน 90 วัน เนื่องจากเหตุผลทางเทคนิค ต้องดำเนินการให้การเก็บรวบรวม ใช้ หรือเปิดเผยข้อมูลส่วนบุคคลเป็นไปได้ยากจนกว่าจะดำเนินการลบ ทำลาย หรือทำให้ข้อมูลส่วนบุคคลเป็นข้อมูลที่ไม่สามารถระบุตัวตนได้แล้วเสร็จ\n- กรณีสามารถปฏิเสธคำขอได้ตามกฎหมาย เช่น จำเป็นต้องเก็บรักษาข้อมูลตามกฎหมาย ต้องแจ้งเหตุผลและความจำเป็นให้เจ้าของข้อมูลทราบ\n- การลบหรือทำลาย ต้องดำเนินการครอบคลุมถึงข้อมูลสำรองหรือสำเนา\n- กรณีทำให้เป็นข้อมูลนิรนาม (anonymization) ต้องมีกระบวนการพิจารณาดำเนินการเพิ่มเติม เพื่อตรวจสอบว่าข้อมูลดังกล่าวไม่สามารถระบุตัวตนได้\n- กรณีข้อมูลส่วนบุคคลเป็นข้อมูลที่เก็บรวบรวม ใช้ และเปิดเผยโดยไม่ชอบ และไม่ใช่กรณีที่ปฏิเสธคำขอได้ตามกฎหมาย ต้องดำเนินการทำลายหรือลบข้อมูลดังกล่าวเท่านั้น ไม่อาจใช้วิธีการทำให้เป็นข้อมูลนิรนาม (anonymization) ได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":802,"law_id":122,"seq":1,"text":"2. นอกเหนือจากการลบ ทำลาย หรือทำให้ข้อมูลส่วนบุคคลเป็นข้อมูลที่ไม่สามารถระบุตัวตนได้ ตามคำขอของเจ้าของข้อมูลแล้ว ให้จัดให้มีระบบตรวจสอบเพื่อทำลายข้อมูลส่วนบุคคลที่พ้นระยะเวลาเก็บรักษา","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":468,"law_id":124,"seq":0,"text":"- การเข้ายื่นข้อเสนอกับหน่วยงานของรัฐในการจัดซื้อจัดจ้างที่มีวงเงินเกิน 300 ล้านบาทขึ้นไป ผู้ประกอบการต้องทำ ดังนี้\n1.\tทำมาตรฐานขั้นต่ำของนโยบายและแนวทางป้องกันการทุจริตในการจัดซื้อจัดจ้างที่เหมาะสมเป็นหนังสือ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":803,"law_id":124,"seq":1,"text":"2.\tยื่นแบบตรวจสอบข้อมูลของผู้ประกอบการและหลักฐานอ้างอิง\n- กรณีที่ผู้ประกอบการได้รับการรับรองมาตรฐานเกี่ยวกับการป้องกันการทุจริต ดังนี้ ถือว่าได้จัดให้มีมาตรฐานขั้นต่ำของนโยบายและแนวทางป้องกันการทุจริตในการจัดซื้อจัดจ้างแล้ว\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":804,"law_id":124,"seq":2,"text":"1.\tISO 37001 ระบบการจัดการต่อต้านการให้และรับสินบน (Anti-Bribery Management Systems)\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":805,"law_id":124,"seq":3,"text":"2.\tการรับรองจากแนวร่วมต่อต้านคอร์รัปชันภาคเอกชนไทย (CAC Certified)\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":806,"law_id":124,"seq":4,"text":"3.\tหรืออื่นๆ ตามที่คณะกรรมการ ค.ป.ท. กำหนด","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":490,"law_id":129,"seq":0,"text":"จัสเทลอยู่ในนิยามความหมายของ “ผู้ให้บริการโทรคมนาคมรายอื่น”\n1.\tมาตรา 4/1 (เพิ่มใหม่) \n\tวรรค 1 - กำหนดให้ ธปท. สำนักงาน กลต. กสทช. สำนักงาน กสทช. และคณะกรรมการธุรกรรมทางอิเล็คทรอนิกส์ มีอำนาจในการกำหนดมาตรฐานเพื่อป้องกันอาชญากรรมทางเทคโนโลยี\n            วรรค 2 - กำหนดให้ ผู้ให้บริการเครือข่ายโทรศัพท์ และผู้ให้บริการโทรคมนาคมรายอื่น มีหน้าที่ตรวจสอบเพื่อคัดกรองเนื้อหาบริการสารสั้น (SMS) ที่อาจเกี่ยวข้องกับอาชญากรรมทางเทคโนโลยีตามมาตรฐาน หรือมาตรการที่ สำนักงาน กสทช. กำหนด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":807,"law_id":129,"seq":1,"text":"2.\tมาตรา 5 วรรค 2 และ 3 (เพิ่มใหม่)\n\tวรรค 2 – กรณีปรากฏพยานหลักฐานอันควรเชื่อได้ว่ามีการใช้บริการโทรคมนาคมเพื่อกระทำผิดอาชญากรรมทางเทคโนโลยี สำนักงาน กสทช. สั่งให้ผู้ให้บริการเครือข่ายโทรศัพท์ ผู้ให้บริการโทรคมนาคมรายอื่น และผู้ให้บริการอื่นที่เกี่ยวข้องกับการกระทำนั้น ระงับการให้บริการโทรคมนาคมดังกล่าว\n\tวรรค 3 - การยกเลิกการระงับการให้บริการตามวรรค 2 ให้เป็นไปตามหลักเกณฑ์ วิธีการ และเงื่อนไขที่ สตช. DSI ปปง. สำนักงาน กสทช. และ ศปอท. เห็นชอบร่วมกัน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":808,"law_id":129,"seq":2,"text":"3.\tมาตรา 8/10 (เพิ่มใหม่)\nให้สถาบันการเงินหรือผู้ประกอบธุรกิจ ผู้ให้บริการเครือข่ายโทรศัพท์ ผู้ให้บริการโทรคมนาคมรายอื่น ผู้ให้บริการอื่นที่เกี่ยวข้อง  หรือผู้ให้บริการสื่อสังคมออนไลน์ มีส่วนร่วมรับผิดชอบในความเสียหายที่เกิดจากอาชญากรรมทางเทคโนโลยี เว้นแต่ จะพิสูจน์ได้ว่าสถาบันการเงินหรือผู้ประกอบธุรกิจ ผู้ให้บริการเครือข่ายโทรศัพท์ ผู้ให้บริการโทรคมนาคมรายอื่น ผู้ให้บริการอื่นที่เกี่ยวข้อง หรือผู้ให้บริการสื่อสังคมออนไลน์ ได้ปฏิบัติตามมาตรฐานหรือมาตรการป้องกันอาชญากรรมทางเทคโนโลยีที่กำหนดโดย ธปท. สำนักงาน กลต. กสทช. สำนักงาน กสทช. หรือคณะกรรมการธุรกรรมทางอิเล็คทรอน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":491,"law_id":129,"seq":3,"text":"ดังนั้น ตามที่ พรก. กำหนดเป็นการเพิ่มเติม ในส่วนที่บริษัทฯ จะต้องรับผิดชอบในความเสียหายที่เกิดจากอาชญากรรมทางเทคโนโลยีนั้น ยังคงต้องรอมาตรการป้องกันอาชญากรรมทางเทคโนโลยีที่กำหนดโดย กสทช / สำนักงาน กสทช. หรือหน่วยงานภาครัฐที่เกี่ยวเนื่อง และเกี่ยวข้องอีกครั้งหนึ่ง\n\nนอกจากนี้ ในส่วนที่อาจเกี่ยวข้องกับบริษัทฯ หากบริษัทมีลูกค้าประเภท “ผู้ประกอบธุรกิจสินทรัพย์ดิจิทัล” ในมาตรา 7/1 ของพรก. โดยหากพนักงานเจ้าหน้าที่ตรวจพบการกระทำความผิดเกี่ยวกับคอมพิวเตอร์ว่ามีผู้ประกอบธุรกิจสินทรัพย์ดิจิทอลโดยไม่ได้รับอนุญาตตามกฎหมายว่าด้วยการประกอบธุรกิจสินทรัพย์ดิจิทัล พนักงานเจ้าหน้าที่ดังกล่าวสามารถมีคำสั่ง “ระงับ” การทำให้แพร่หลายของข้อมูลคอมพิวเตอร์ หรือนำข้อมูลคอมพิวเตอร์ที่ผิดกฎหมายออกจากระบบคอมพิวเตอร์ทันที \n\nทั้งนี้ หากผู้ได้รับคำสั่งไม่ปฏิบัติตามมาตรา 7/1 ตามมาตรา 8/12 ของ พรก. กำหนดให้ต้องระวางโทษจำคุกไม่เกิน 1 ปี หรือปรับไม่เกิน 100,000 บาท หรือทั้งจำทั้งปรับ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":492,"law_id":130,"seq":0,"text":"1.\tหากนายจ้างให้ลูกจ้างในงานเฝ้าดูแลฯ ทำงานล่วงเวลา ต้องจ่ายค่าล่วงเวลาไม่น้อยกว่า 1.25 เท่าของอัตราค่าจ้างต่อชั่วโมงในวันทำงานปกติ และไม่น้อยกว่า 2.5 เท่าของอัตราค่าจ้างต่อชั่วโมงในวันทำงานตามชั่วโมงที่ทำ\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":809,"law_id":130,"seq":1,"text":"2.\tสำหรับลูกจ้างที่ไม่ได้รับค่าจ้างเป็นรายเดือน หากตกลงให้ทำงานปกติเกินวันละ 8 ชั่วโมง แต่ไม่เกิน 48 ชั่วโมงต่อสัปดาห์\n-\tจ่ายค่าตอบแทนในวันทำงานไม่น้อยกว่า 1.25 เท่าของอัตราค่าจ้างต่อชั่วโมง สำหรับชั่วโมงที่ทำเกิน\n-\tจ่ายค่าตอบแทนในวันหยุดไม่น้อยกว่า 2.5 เท่าของอัตราค่าจ้างต่อชั่วโมง สำหรับชั่วโมงที่ทำเกิน","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":496,"law_id":134,"seq":0,"text":"ผู้ได้รับอนุญาตใช้เขตทางหลวงท้องถิ่น ให้ดำเนินการ\n1.\tสร้างอาคารหรือสิ่งอื่นใดในเขตทางหลวงท้องถิ่นหรือรุกล้ำเข้าไปในเขตทางหลวงท้องถิ่น\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":810,"law_id":134,"seq":1,"text":"2.\tปักเสา พาดสาย วางท่อ หรือกระทำการใดๆในเขตทางหลวงท้องถิ่น\n\nค่าใช้เขตทางหลวงท้องถิ่น ดังนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":811,"law_id":134,"seq":2,"text":"1.\tกิจกรรมประโยชน์สาธารณะ บริการสาธารณะแก่ประชาชนทั่วไป (ประชาชนใช้ประโยชน์/บริการได้โดยไม่ถูกเรียกเก็บค่าใช้บริการ) 500 บาท/การอนุญาตแต่ละครั้ง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":812,"law_id":134,"seq":3,"text":"2.\tกิจกรรมให้บริการสาธารณะขั้นพื้นฐาน ประชาชนสามารถใช้ประโยชน์/บริการได้ และถูกเรียกเก็บค่าใช้บริการ ดังนี้\na.\tกิจกรรมของหน่วยงานรัฐที่ให้บริการสาธารณะ คิดอัตรา 500 บาท/การอนุญาตแต่ละครั้ง\nb.\tกิจกรรมของผู้ได้รับอนุญาตนอกจากหน่วยงานรัฐ ให้ชำระเป็นรายปี ในอัตรากึ่งหนึ่งของอัตราที่กำหนดท้ายกฎกระทรวงนี้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":813,"law_id":134,"seq":4,"text":"3.\tกิจกรรมมุ่งหวังประโยชน์ทางธุรกิจ แสวงหากำไรหรือเอื้อประโยชน์ต่อการดำเนินธุรกิจของผู้ได้รับอนุญาตใช้เขตทางหลวงท้องถิ่น ให้ชำระค่าใช้เขตทางหลวงท้องถิ่นเป็นรายปี ในอัตราตามที่กำหนดท้ายกฎกระทรวงนี้\nการชำระค่าใช้เขตทางหลวง เป็นรายปี \n(1) ในปีแรก ให้ชำระภายในสามสิบวันนับแต่วันที่ได้รับอนุญาตใช้เขตทางหลวงท้องถิ่น  \n(2) ในปีต่อไป ให้ชำระไม่เกินวันครบกำหนดรอบปีนับแต่วันที่ได้รับอนุญาต","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":497,"law_id":135,"seq":0,"text":"1.\tการซ่อมแซมอาคารหรือทรัพย์ที่ประกอบกับตัวอาคารหรือในที่ดิน จากอุทกภัย ระหว่างวันที่ 16 สิงหาคม – 31 ธันวาคม 2567\na.\tทรัพย์สินที่อยู่ในพื้นที่ที่ทางราชการประกาศให้เป็นเขตพื้นที่ประสบสาธารณภัยหรือเขตการให้ความช่วยเหลือผู้ประสบภัยพิบัติกรณีฉุกเฉิน \nb.\tที่ได้รับความเสียหายจากอุทกภัยระหว่างวันที่ 16 สิงหาคม – 31 ธันวาคม 2567 \nc.\tเป็นเจ้าของกรรมสิทธิ์ / ผู้เช่า / ผู้ใช้ประโยชน์จากทรัพย์สินที่เสียหายนั้น\nd.\tเพื่อเป็นที่อยู่อาศัย / ใช้ประกอบกิจการ / ใช้ประโยชน์อื่น\ne.\tได้จ่ายค่าซ่อมแซมหรือค่าวัสดุในการซ่อมแซมทรัพย์สินนั้นมากกว่า 1 แห่ง ให้รวมคำนวณเข้าด้วยกัน\nf.\tคิดตามจำนวนจริงแต่ไม่เกิน 1 แสนบาท เป็นเงินได้พึงประเมินที่ได้รับยกเว้นไม่ต้องรวมคำนวณเพื่อเสียภาษีเงินได้\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":814,"law_id":135,"seq":1,"text":"2.\tการซ่อมแซมรถ หรืออุปกรณ์หรือสิ่งอำนวยความสะดวกในรถ ได้รับความเสียหายจากอุทกภัย ระหว่างวันที่ 16 สิงหาคม – 31 ธันวาคม 2567\na.\tทรัพย์สินที่อยู่ในพื้นที่ที่ทางราชการประกาศให้เป็นเขตพื้นที่ประสบสาธารณภัยหรือเขตการให้ความช่วยเหลือผู้ประสบภัยพิบัติกรณีฉุกเฉิน\nb.\tที่ได้รับความเสียหายจากอุทกภัยระหว่างวันที่ 16 สิงหาคม – 31 ธันวาคม 2567\nc.\tเป็นเจ้าของกรรมสิทธิ์ / ผู้เช่า \nd.\tได้จ่ายค่าซ่อมแซมหรือค่าวัสดุหรืออุปกรณ์ในการซ่อมแซมรถหรืออุปกรณ์หรือสิ่งอำนวยความสะดวกในรถ มากกว่า 1 คัน ให้ควมคำนวณเข้าด้วยกัน\ne.\tคิดตามจำนวนจริงแต่ไม่เกิน 3 หมื่นบาท เป็นเงินได้พึงประเมินที่ได้รับยกเว้นไม่ต้องรวมคำนวณเพื่อเสียภาษีเงินได้","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":500,"law_id":138,"seq":0,"text":"ผู้ที่ยื่นข้อเสนอเพื่อทำการจัดซื้อจัดจ้างกับหน่วยงานรัฐ ไม่มีสิทธิอุทธรณ์เกี่ยวกับการจัดซื้อจัดจ้างพัสดุ ในเรื่องดังนี้\n1.\tคุณสมบัติของผู้ยื่นข้อเสนอรายอื่นที่เข้าร่วมการจัดซื้อจัดจ้างพัสดุในครั้งนั้น ในกรณีที่หน่วยงานของรัฐจัดซื้อจัดจ้างโดยวิธีประกาศเชิญชวนทั่วไป ด้วยวิธีตลาดอิเล็กทรอนิกส์\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":815,"law_id":138,"seq":1,"text":"2.\tขอบเขตของงานหรือรายลเอียดคุณลักษณะเฉพาะของพัสดุ ในกรณีที่หน่วยงานของรัฐเปิดโอกาสให้มีการรับฟังความคิดเห็นจากผู้ประกอบการก่อนจะทำการจัดซื้อจัดจ้าง และผู้ซึ่งได้ยื่นข้อเสนอนั้นมิได้วิจารณ์หรือเสนอแนะร่างขอบเขตของงานหรือรายละเอียดคุณลักษณะเฉพาะของพัสดุดังกล่าว\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":816,"law_id":138,"seq":2,"text":"3.\tการที่ผู้ซึ่งได้ยื่นข้อเสนอนั้นมิได้เป็นผู้ประกอบการงานก่อสร้างหรือผู้ประกอบการพัสดุอื่นที่ขึ้นทะเบียนไว้กับกรมบัญชีกลาง ในกรณีที่การจัดซื้อจัดจ้างนั้นเป็นงานก่อสร้างหรือผู้ประกอบการพัสดุอื่นที่ผู้ประกอบการต้องขึ้นทะเบียนไว้กับกรมบัญชีกลางตามมาตรา 51 หรือมาตรา 52 แล้วแต่กรณี\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":817,"law_id":138,"seq":3,"text":"4.\tผลการพิจารณาผู้ได้รับการคัดเลือก ในกรณีที่หน่วยงานของรัฐจัดซื้อจัดจ้างด้วยวิธีคัดเลือกตามมาตรา 56 (1) (ค)\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":818,"law_id":138,"seq":4,"text":"5.\tการที่ผู้ซึ่งได้ยื่นข้อเสนอนั้นขาดคุณสมบัติหรือมีลักษณะต้องห้ามตามมาตรา 64 วรรคหนึ่ง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":819,"law_id":138,"seq":5,"text":"6.\tการที่ผู้ซึ่งได้ยื่นข้อเสนอนั้นมิได้ยื่นหลักประกันการเสนอราคาหรือยื่นหลักประกันการเสนอราคาไม่เป็นไปตามที่กำหนดในระเบียบกระทรวงการคลังว่าด้วยการจัดซื้อจัดจ้างและการบริหารพัสดุภาครัฐ หรือไม่เป็นไปตามเงื่อนไขการยื่นหลักประกันการเสนอราคาตามที่กำหนดในเอกสารเชิญชวน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":820,"law_id":138,"seq":6,"text":"7.\tการที่ผู้ซึ่งได้ยื่นข้อเสนอนั้นนำผลงานซึ่งเป็นของบุคคลอื่นหรือที่ได้รับโอนจากบุคคลอื่นมายื่นเป็นผลงานของตน อันไม่เป็นไปตามหลักเกณฑ์ที่กำหนดไว้ในเอกสารเชิญชวนหรือหนังสือเชิญชวน\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":821,"law_id":138,"seq":7,"text":"8.\tการเปลี่ยนแปลงประกาศผลผู้ช","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":506,"law_id":144,"seq":0,"text":"1.\tยกเว้นภาษีเงินสำหรับการบริจาคให้แก่กองทัพอากาศ เพื่อสนับสนุนโครงการสร้างพระสถูปเจดีย์บรรจุพระบรมสารีริกธาตุ บริเวณพื้นที่พระมหาธาตุนภเมทนีดล นภพลภูมิสิริ จังหวัดเชียงใหม่\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":822,"law_id":144,"seq":1,"text":"2.\tสำหรับการบริจาคตั้งแต่วันที่ 1 มกราคม 2568 – 31 ธันวาคม 2570\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":823,"law_id":144,"seq":2,"text":"3.\tโดยยกเว้นภาษีเงินได้เท่าจำนวนเงินหรือราคาทรัพย์สินที่บริจาค แต่เมื่อรวมกับรายจ่ายเพื่อการกุศลสาธารณะหรือเพื่อการสาธารณประโยชน์แล้วต้องไม่เกินร้อยละ 2 ของกำไรสุทธิ","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":824,"law_id":145,"seq":1,"text":"2.\tอุปกรณ์นั้นต้องได้รับการรับรองฉลากแสดงระดับประสิทธิภาพพลังงานระดับ 5 ดาว จากกรมพัฒนาพลังงานทดแทนและอนุรักษ์พลังงานและการไฟฟ้าฝ่ายผลิตแห่งประเทศไทย\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":825,"law_id":145,"seq":2,"text":"3.\tตั้งแต่วันที่พระราชกฤษฎีกานี้ใช้บังคับ ถึงวันที่ 31 ธันวาคม 2571\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":826,"law_id":145,"seq":3,"text":"4.\tเกณฑ์การได้รับยกเว้นภาษีเงินได้ ตามกฎหมายนี้ คือ\n-\tจ่ายเงินแก่ผู้ขายที่จด VAT และต้องได้รับใบกำกับภาษีตามมาตรา 86/4 แบบอิเล็กทรอนิกส์\n-\tต้องไม่นำค่าใช้จ่ายที่ใช้สิทธิตามกฎหมายฉบับนี้ไปใช้สิทธิยกเว้นภาษีเงินได้ตามกฎหมายอื่น รวมถึงไม่นำค่าใช้จ่ายไปใช้ในกิจการที่ได้รับยกเว้นภาษีเงินได้นิติบุคคลตามกฎหมายว่าด้วยการส่งเสริมการลงทุน กฎหมายว่าด้วยการเพิ่มขีดความสามารถในการแข่งขันของประเทศสำหรับอุตสาหกรรมเป้าหมาย หรือกฎหมายว่าด้วยเขตพัฒนาพิเศษภาคตะวันออกไม่ว่าทั้งหมดหรือบางส่วน\n\n**หมายเหตุ**\nค่าใช้จ่าย 50% ของการลงทุนนี้ จะหักจากกำไรสุทธิก่อนคำนวณภาษีเงินได้นิติบุคคล","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":508,"law_id":146,"seq":0,"text":"1.\tนิติบุคคลที่ประสงค์แก้ไขเพิ่มเติมให้คนต่างด้าวเป็นหุ้นส่วนของห้างหุ้นส่วน หรือให้เป็นกรรมการผู้มีอำนาจลงนามในบริษัทจำกัด\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":827,"law_id":146,"seq":1,"text":"\n2.\tกรณีห้างหุ้นส่วน\n-\tเดิมผู้เป็นหุ้นส่วนทั้งหมดเป็นสัญชาติไทย หรือมีต่างด้าวรวมหุ้นกันตั้งแต่ 50% ของเงินลงทุน\n-\tประสงค์แก้ไขเพิ่มเติมให้คนต่างด้าวถือหุ้นรวมกันไม่ถึง 50% ของเงินลงทุน โดยไม่มีคนต่างด้าวเป็นหุ้นส่วนผู้จัดการ\n-\tให้หุ้นส่วนผู้จัดการลงชื่อในหนังสือยืนยันการลงทุนตามแบบฟอร์มท้ายคำสั่ง\n","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":828,"law_id":146,"seq":2,"text":"\n3.\tกรณีบริษัทจำกัด\n-\tเดิมกรรมการผู้มีอำนาจลงนามทั้งหมดมีสัญชาติไทย\n-\tประสงค์แก้ไขให้คนต่างด้าวเป็นกรรมการผู้มีอำนาจลงนามผูกพันบริษัท\n-\tให้กรรมการลงชื่อในหนังสือยืนยันการลงทุนตามแบบฟอร์มท้ายคำสั่ง","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":522,"law_id":153,"seq":0,"text":"1.   สำหรับการบริจาคตั้งแต่วันที่ 1 มกราคม 2568 – 321 ธันวาคม 2570\n","status":"met","responsible":"บัญชี","frequency":"-","documents":"เอกสารทางบัญชี","note":"เพื่ื่อทราบ","evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":829,"law_id":153,"seq":1,"text":"2.   สำหรับการบริจาคให้แก่กองทัพอากาศ ตามมาตรา 3 (2) แห่งพระราชกฤษฎีกาออกตามความในประมวลรัษฎากรว่าด้วยการยกเว้นรัษฎากร (ฉบับที่ 805) พ.ศ.2569 \n\t2.1\tกรณีบริจาคเป็นเงิน:\n\t\tบริจาคผ่านบัญชีธนาคารที่กองทัพอากาศ ชื่อบัญชี “รายได้เพื่อจัดสร้างพระสถูปเจดีย์บรรจุพระบรมสารีริกธาตุของ ทอ.”\n\t2.2\tกรณีบริจาคเป็นทรัพย์สินหรือสินค้า (มูลค่าต้องไม่เกินราคาปกติที่ซื้อขายทั่วไป):\n\t\t-   กรณีซื้อทรัพย์สินมาบริจาค ต้องมีหลักฐานการซื้อ ระบุจำนวนและมูลค่าของทรัพย์สิน โดยถือมูลค่าตามหลักฐานเป็นมูลค่าของรายจ่ายที่บริจาค\n\t\t-   กรณีนำทรัพย์สินที่บนัทึกบัญชีทรัพย์สินของบริษัทมาบริจาค ให้ถือมูลบค่าต้นทุนส่วนที่เหลือจากการคำนวณหักค่าสึกหรอและค่าเสื่อมเป็นมูลค่ารายจ่ายที่บริจาค\n\t\t-   กรณีนำสินค้ามาบริจาค ไม่ว่าจะผลิตเองหรือซื้อมาเพื่อขาย ให้ถือมูลค่าต้นทุนสินค้าที่พิสูจน์ได้เป็นมูลค่ารายจ่ายที่บริจาค\n","status":"met","responsible":"บัญชี","frequency":"-","documents":"เอกสารทางบัญชี","note":"เพื่ื่อทราบ","evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":830,"law_id":153,"seq":2,"text":"3.   ผู้จะใช้สิทธิยกเว้นภาษีเงินได้ VAT ภาษีธุรกิจเฉพาะ และอากรแสตมป์ ต้องมีเอกสารการบริจาคให้กองทัพอากาศพร้อมให้เจ้าพนักงานประเมินตรวจสอบได้ คือ ใบเสร็จรับเงิน หรือหลักฐานเป็นหนังสืออื่นที่ออกโดยกองทัพอากาศ เช่น หนังสือขอบคุณ ใบประกาศเกียรติคุณ ใบอนุโมทนาบัตร ที่ระบุจำนวนเงิน\n","status":"met","responsible":"บัญชี","frequency":"-","documents":"เอกสารทางบัญชี","note":"เพื่ื่อทราบ","evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":831,"law_id":153,"seq":3,"text":"4. ถ้ากองทัพอากาศรับบริจาคผ่าน e-Donation ผู้บริจาคไม่ต้องแสดงหลักฐาน","status":"met","responsible":"บัญชี","frequency":"-","documents":"เอกสารทางบัญชี","note":"เพื่ื่อทราบ","evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":246,"law_id":30,"seq":0,"text":"คุณสมบัติผู้ที่จะขอรับใบอนุญาตเป็นผู้ชำนาญการด้านความปลอดภัย\n1. มีสัญชาติไทย\n2. มีอายุไม่ต่ำกว่า 25 ปี\n3. ไม่เป็นคนไร้ความสามารถหรือคนเสมือนไร้ความสามารถ\n4. ไม่เป็นผู้เคยถูกไล่ออก ปลดออก หรือให้ออกจากราชการ หน่วยงานของรัฐ หรือรัฐวิสาหกิจเพราะกระทำผิดวินัยร้ายแรง\n5. ไม่เคยถูกพักใช้หรือถูกเพิกถอนใบอนุญาตตามกฎกระทรวงนี้ เว้นแต่พ้นกำหนด 5 ปี นับแต่วันถูกพักใช้หรือถูกเพิกถอนใบอนุญาต\n6. มีความรู้ ความเข้าใจ มีประสบการณ์เกี่ยวกับการประเมินอันตราย การศึกษาผลกระทบของสภาพแวดล้อมในการทำงานที่มีผลต่อลูกจ้าง การจัดทำแผนการควบคุมดูแลลูกจ้าง และสถานประกอบกิจการ ไม่น้อยกว่า 5 ปี\n7. และมีคุณสมบัติอย่างใดอย่างหนึ่งดังต่อไปนี้\na. สำเร็จการศึกษาไม่ต่ำกว่าปริญญาตรี สาขาอาชีวอนามัยและความปลอดภัยหรือเทียบเท่า\nb. สำเร็จการศึกษาไม่ต่ำกว่าปริญญาตรีทางวิทยาศาสตร์ ปริญญาตรีทางสาธารณสุขศาสตร์ หรือปริญญาตรีทางวิศวกรรมศาสตร์ ที่มีการเรียนการสอนทางด้านอาชีวอนามัยและความปลอดภัยและการประเมินอันตรายหรือประเมินความเสี่ยง ไม่น้อยกว่า 18 หน่วยกิต\nc. เป็นผู้ได้รับใบอนุญาตประกอบวิชาชีพวิทยาศาสตร์และเทคโนโลยีควบคุม สาขาอาชีวอนามัยและความปลอดภัย ตามกฎหมายว่าด้วยการส่งเสริมวิชาชีพวิทยาศาสตร์และเทคโนโลยี หรือเป็นผู้ได้รับใบอนุญาตประกอบวิชาชีพเกี่ยวกับอาชีวอนามัยและความปลอดภัยอื่นตามที่อธิบดีกำหนดโดยประกาศในราชกิจจานุเบกษา","status":"unmet","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":"QA & SHE","evaluated_at":"2026-08-02T13:57:48.694+00:00","evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":247,"law_id":31,"seq":0,"text":"ข้อ 5 ให้นายจ้างดำเนินการประเมินอันตรายฯ และทบทวนการดำเนินการทุก 3 ปี\n       การเปลี่ยนแปลงใดๆ รวมถึงการเปลี่ยนแปลงที่เกิดจากภัยธรรมชาติหรือเพื่อการช่วยเหลือ การบรรเทาเหตุ หรือปัจจัยอื่นๆ และส่งผลให้สภาวะการทำงานเปลี่ยนแปลง ให้นายจ้างดำเนินการให้ครอบคลุมก่อน ระหว่าง และหลังดำเนินการปรับปรุง/เปลี่ยนแปลง\n       นายจ้างต้องจัดให้ลูกจ้างปฏิบัติงานซึ่งมีความรู้ในขั้นตอนการทำงานนั้นฯ อย่างน้อย 1 คน มีส่วนร่วมกับ จป./คปอ. ในการดำเนินการ โดยต้องปฏิบัติตามคำแนะนำและได้รับการรับรองผลจากผู้ชำนาญการด้านความปลอดภัยฯ","status":"unmet","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":864,"law_id":31,"seq":1,"text":"ข้อ 6 ให้นายจ้างประเมินอันตรายด้วยการใช้วิธีการชี้บ่งอันตรายโดยครอบคลุมทุกขั้นตอนวิธีการปฏิบัติงานและทุกกิจกรรม โดยเลือกใช้วิธีใดวิธีการหนึ่งหรือหลายวิธีร่วมกัน (1)-(9)","status":"unmet","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":865,"law_id":31,"seq":2,"text":"ข้อ 7 ให้นายจ้างนำผลการชี้บ่งอันตรายตามข้อ 6 มาวิเคราะห์โอกาสและความรุนแรงเพื่อจัดระดับอันตรายฯ","status":"unmet","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":866,"law_id":31,"seq":3,"text":"ข้อ 8 กรณีที่ผลการวิเคราะห์ตามข้อ 7 อยู่ในระดับอันตรายที่ยอมรับไม่ได้ ให้นายจ้างจัดทำแผนการดำเนินงานด้านความปลอดภัยฯ","status":"unmet","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":867,"law_id":31,"seq":4,"text":"ข้อ 9 ให้นายจ้างจัดทำรายงานผลการประเมินอันตรายฯ ตามแบบแนบท้ายประกาศ พร้อมส่งรายงานผลทางอิเล็กทรอนิกส์ของกรมสวัสดิ์ฯหรือเป็นเอกสารด้วยตนเอง/ไปรษณีย์ ภายใน 60 วันนับแต่วันที่เสร็จสิ้น\n        ให้นายจ้างเก็บเอกสารหลักฐานเกี่ยวกับการประเมินอันตรายฯ ไว้ ณ สถานประกอบการ ไม่น้อยกว่า 3 ปี ในรูปแบบใดก็ได้","status":"unmet","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":null,"evaluated_at":null,"evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]},{"id":188,"law_id":6,"seq":4,"text":"ในกรณีที่นายจ้างได้จัดให้มีระบบการจัดการด้านความปลอดภัยตามมาตรฐาน\nผลิตภัณฑ์อุตสาหกรรม มาตรฐำนขององค์การมาตรฐานสากล\n(International Standardization for Organization : ISO) มาตรฐานขององค์การแรงงานระหว่างประเทศ (International Labour Organization : ILO) มาตรฐานของสถาบันมาตรฐานสหราชอาณาจักร (British Standards Institution : BSI) มาตรฐานของสำนักงานบริหารความปลอดภัยและอาชีวอนามัยแห่งชาติ\n(Occupational Safety and Health Administration : OSHA) มาตรฐานของสถาบันมาตรฐาน\nแห่งชาติประเทศสหรัฐอเมริกา (American National Standards Institute : ANSI) มาตรฐานของ\nประเทศออสเตรเลียและประเทศนิวซีแลนด์\n(Australia Standards/New Zealand Standards : AS/NZS) มาตรฐานของสมาพันธ์การกำหนดมาตรฐานของประเทศแคนาดา\n(Canadian Standards Association : CSA) หรือมาตรฐานอื่นที่เทียบเท่าตามที่อธิบดีประกาศกำหนด ให้ถือว่าได้จัดให้มีระบบการจัดการด้านความปลอดภัยตามกฎกระทรวงนี้แล้ว","status":"met","responsible":null,"frequency":null,"documents":null,"note":null,"evaluated_by":"QA & SHE","evaluated_at":"2026-07-29T15:04:16.959+00:00","evidence_url":null,"evidence_label":null,"from_related_law":null,"from_law_url":null,"from_law_confidence":null,"ref_answers":[]}]
